INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e40dcfce-c511-4740-99a8-d19c9ebb0852', '送胡澳下第歸蒲津', '送胡澳下第归蒲津', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["無媒甘下飛，君子尚麻衣。","歲月終榮在，家園近且歸。","山光臨舜廟，河氣隔王畿。","甚積湯原思，青青宿麥肥。"]', '["無媒甘下飞，君子尚麻衣。","歲月終榮在，家园近且归。","山光臨舜廟，河氣隔王畿。","甚積湯原思，青青宿麦肥。"]', '诗', 'shi', '', NULL, '送胡澳下第歸蒲津 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e191e57-f8fb-4321-8036-0959aae25b3d', '春日閑居', '春日闲居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["權門多見薄，吾道豈終行。","散地徒憂國，良時不在城。","花繁春正王，茶美夢初驚。","賴有茲文在，猶堪暢此生。"]', '["權门多见薄，吾道豈終行。","散地徒憂国，良时不在城。","花繁春正王，茶美梦初驚。","賴有茲文在，猶堪暢此生。"]', '诗', 'shi', '', NULL, '春日閑居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07eceda2-115a-4e64-80d8-7fddb48b22c6', '題逃戶', '題逃戶', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["幾世瞢農桑，凶年竟失鄉。","朽關生濕菌，傾屋照斜陽。","雨水淹殘臼，葵花壓倒牆。","明時豈致此，應自負蒼蒼。"]', '["幾世瞢農桑，凶年竟失乡。","朽关生濕菌，傾屋照斜陽。","雨水淹殘臼，葵花壓倒牆。","明时豈致此，應自負蒼蒼。"]', '诗', 'shi', '', NULL, '題逃戶 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b1418cd-3d56-48dd-abd1-9e2863f9f4a8', '郊居荅客', '郊居荅客', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["傍舍蟲聲滿，殘秋宿雨村。","遠勞才子騎，光顧野人門。","敗葉盤空蔓，彫叢露暗根。","相攜未盡語，川月照黃昏。"]', '["傍舍蟲声满，殘秋宿雨村。","远勞才子騎，光顧野人门。","敗葉盤空蔓，彫叢露暗根。","相携未尽語，川月照黄昏。"]', '诗', 'shi', '', NULL, '郊居荅客 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae29f55-2148-462c-8c64-a2b6b03dc6c0', '早春歸山中舊居', '早春归山中旧居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["綠草閉閑院，悄然花正開。","新年人未去，戊日燕還來。","雨地殘枯沫，燈窗積舊煤。","歸田語不忘，樗散料非才。"]', '["綠草閉闲院，悄然花正开。","新年人未去，戊日燕還来。","雨地殘枯沫，灯窗積旧煤。","归田語不忘，樗散料非才。"]', '诗', 'shi', '', NULL, '早春歸山中舊居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228fa652-eea8-4900-b4cc-21327395011b', '下第後春日長安寓居三首 一', '下第後春日长安寓居三首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一榜盡精選，此身猶陸沈。","自無功讜分，敢抱怨尤心。","暖陌開花氣，春居閉日陰。","相知豈不有，知淺未知深。"]', '["一榜尽精選，此身猶陸沈。","自無功讜分，敢抱怨尤心。","暖陌开花氣，春居閉日陰。","相知豈不有，知淺未知深。"]', '诗', 'shi', '', NULL, '下第後春日長安寓居三首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de7e928-d9f7-4162-b7c1-85e47235e2bf', '下第後春日長安寓居三首 二', '下第後春日长安寓居三首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["暫屈固何恨，所憂無此時。","隔年空仰望，臨日又參差。","勞力且成病，壯心能不衰。","猶將琢磨意，更欲候宗師。"]', '["暫屈固何恨，所憂無此时。","隔年空仰望，臨日又參差。","勞力且成病，壯心能不衰。","猶將琢磨意，更欲候宗師。"]', '诗', 'shi', '', NULL, '下第後春日長安寓居三首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce50954c-e00b-4c17-abb0-4d782936b82a', '下第後春日長安寓居三首 三', '下第後春日长安寓居三首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["關東歸不得，豈是愛他鄉。","草碧餘花落，春閑白日長。","全家期聖澤，半路敢農桑。","獨立應無侶，浮生欲自傷。"]', '["关东归不得，豈是愛他乡。","草碧餘花落，春闲白日长。","全家期聖澤，半路敢農桑。","独立應無侶，浮生欲自傷。"]', '诗', 'shi', '', NULL, '下第後春日長安寓居三首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88877dbb-3e4d-40a8-8626-3a13951718c0', '春早選寓長安二首 一', '春早選寓长安二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["疎拙自沈昏，長安豈是村。","春非閑客事，花在五侯門。","道僻惟憂禍，詩深不敢論。","揚雄若有薦，君聖合承恩。"]', '["疎拙自沈昏，长安豈是村。","春非闲客事，花在五侯门。","道僻惟憂禍，诗深不敢論。","揚雄若有薦，君聖合承恩。"]', '诗', 'shi', '', NULL, '春早選寓長安二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b77f6043-0350-434b-ac27-995a33036c76', '春早選寓長安二首 二', '春早選寓长安二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["舊論已浮海，此心猶滯秦。","上僚如報國，公道豈無人。","巖隱懸溪瀑，城居入榻塵。","漁舟即擬去，不待晚年身。"]', '["旧論已浮海，此心猶滯秦。","上僚如報国，公道豈無人。","巖隐懸溪瀑，城居入榻塵。","漁舟即擬去，不待晚年身。"]', '诗', 'shi', '', NULL, '春早選寓長安二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc66aeea-7169-4e2f-ba0a-ed9b67ebda12', '送進士許棠下第東歸', '送進士許棠下第东归', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["長安那不住，西笑又東行。","若以貧無計，何因事有成。","雲峰天外出，江色草中明。","謾忝相於分，吾言世甚輕。"]', '["长安那不住，西笑又东行。","若以貧無計，何因事有成。","云峰天外出，江色草中明。","謾忝相於分，吾言世甚轻。"]', '诗', 'shi', '', NULL, '送進士許棠下第東歸 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb0834e-6d83-4ebf-8538-b74f76b15867', '詠島', '詠島', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["孤島如江上，詩家猶閉門。","一池分倒影，空舸繫荒根。","煙濕高吟石，雲生偶坐痕。","登臨有新句，公退與誰論。"]', '["孤島如江上，诗家猶閉门。","一池分倒影，空舸繫荒根。","煙濕高吟石，云生偶坐痕。","登臨有新句，公退與誰論。"]', '诗', 'shi', '', NULL, '詠島 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7adca8b8-aedf-4568-9d31-6469c2a39414', '冬日寫懷', '冬日寫懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["幕府盡平蠻，客留戎閫間。","急流霜夾水，輕靄日連山。","設醴徒慙楚，爲郎未姓顏。","斯文苦不勝，會擬老民間。"]', '["幕府尽平蠻，客留戎閫间。","急流霜夾水，轻靄日連山。","設醴徒慙楚，爲郎未姓顏。","斯文苦不勝，會擬老民间。"]', '诗', 'shi', '', NULL, '冬日寫懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9ec30c-abcd-41ea-bf28-97b417b0466c', '和楊中丞早春即事', '和楊中丞早春即事', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["貴宅登臨地，春來見物華。","遠江橋外色，繁杏竹邊花。","戍客烽樓迥，文君酒幔斜。","新題好不極，珠府未窮奢。"]', '["貴宅登臨地，春来见物华。","远江橋外色，繁杏竹邊花。","戍客烽楼迥，文君酒幔斜。","新題好不極，珠府未窮奢。"]', '诗', 'shi', '', NULL, '和楊中丞早春即事 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0249dac2-b35c-4f36-84b6-6aeea1ba443a', '聞官軍破吉浪戎小而固慮史氏遺忽因記爲二章 一', '闻官軍破吉浪戎小而固慮史氏遺忽因記爲二章 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一戰便抽兵，蠻孤吉浪平。","通連無舊穴，要害有新城。","晝卒烽前寢，春農界上耕。","高樓一擬望，新雨劒南清。"]', '["一戰便抽兵，蠻孤吉浪平。","通連無旧穴，要害有新城。","晝卒烽前寢，春農界上耕。","高楼一擬望，新雨劒南清。"]', '诗', 'shi', '', NULL, '聞官軍破吉浪戎小而固慮史氏遺忽因記爲二章 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f26a797-019f-4028-af1a-2bfac690fb91', '聞官軍破吉浪戎小而固慮史氏遺忽因記爲二章 二', '闻官軍破吉浪戎小而固慮史氏遺忽因記爲二章 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["瀘水斷囂氛，妖巢已自焚。","漢江無敵國，蠻物在迴軍。","越雟通遊國，苴哶閉聚蚊。","空餘羅鳳曲，哀思滿邊雲。"]', '["瀘水斷囂氛，妖巢已自焚。","漢江無敵国，蠻物在迴軍。","越雟通游国，苴哶閉聚蚊。","空餘羅鳳曲，哀思满邊云。"]', '诗', 'shi', '', NULL, '聞官軍破吉浪戎小而固慮史氏遺忽因記爲二章 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab3a7d2-5d89-4471-b94f-d10d78722aae', '寒食有懷', '寒食有懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["流落傷寒食，登臨望歲華。","村毬高過索，墳樹綠和花。","晉聚應搜火，秦喧定走車。","誰知恨榆柳，風景似吾家。"]', '["流落傷寒食，登臨望歲华。","村毬高過索，墳樹綠和花。","晉聚應搜火，秦喧定走车。","誰知恨榆柳，风景似吾家。"]', '诗', 'shi', '', NULL, '寒食有懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0322b7-ad73-4406-8594-75182650064e', '綿樓', '綿楼', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["溪邊人浣紗，樓下海棠花。","極望雖懷土，多情擬置家。","前山應象外，此地已天涯。","未有銷憂賦，梁王禮欲奢。"]', '["溪邊人浣紗，楼下海棠花。","極望雖懷土，多情擬置家。","前山應象外，此地已天涯。","未有銷憂賦，梁王禮欲奢。"]', '诗', 'shi', '', NULL, '綿樓 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd93d7b5-9729-43f6-80af-539b8a7ccc67', '雕堂', '雕堂', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["丈室久多病，小園晴獨遊。","鳴蛩孤燭雨，啅雀一籬秋。","聖主恩難謝，生靈志亦憂。","他年誰識我，心跡在徐州。"]', '["丈室久多病，小园晴独游。","鳴蛩孤燭雨，啅雀一籬秋。","聖主恩难謝，生靈志亦憂。","他年誰識我，心跡在徐州。"]', '诗', 'shi', '', NULL, '雕堂 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4679e47-a212-452d-8039-048a86955f79', '贈歌人', '贈歌人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["溫燠坐相侵，羅襦一水沈。","拜深知有意，令背不無心。","近住應名玉，前生約姓陰。","東山期已定，相許便抽簪。"]', '["溫燠坐相侵，羅襦一水沈。","拜深知有意，令背不無心。","近住應名玉，前生約姓陰。","东山期已定，相許便抽簪。"]', '诗', 'shi', '', NULL, '贈歌人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a973802-1f1d-470d-a281-14ac37174dcb', '柘枝詞三首 一', '柘枝词三首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["同營三十萬，震鼓伐西羌。","戰血黏秋草，征塵攪夕陽。","歸來人不識，帝里獨戎裝。"]', '["同營三十万，震鼓伐西羌。","戰血黏秋草，征塵攪夕陽。","归来人不識，帝里独戎裝。"]', '诗', 'shi', '', NULL, '柘枝詞三首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebeac82d-2c4b-41cc-86d3-fabb837b7a1a', '柘枝詞三首 二', '柘枝词三首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["懸軍征拓羯，內地隔蕭關。","日色崑崙上，風聲朔漠間。","何當千萬騎，颯颯貳師還。"]', '["懸軍征拓羯，內地隔蕭关。","日色崑崙上，风声朔漠间。","何當千万騎，颯颯貳師還。"]', '诗', 'shi', '', NULL, '柘枝詞三首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174b7902-a90c-492a-baea-4627aa556ea5', '柘枝詞三首 三', '柘枝词三首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["意氣成功日，春風起絮天。","樓臺新邸第，歌舞小嬋娟。","急破[催]搖曳，羅衫半脫肩。"]', '["意氣成功日，春风起絮天。","楼台新邸第，歌舞小嬋娟。","急破[催]搖曳，羅衫半脫肩。"]', '诗', 'shi', '', NULL, '柘枝詞三首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a748148-082d-4666-ba95-438f2f7f6837', '詠柳花', '詠柳花', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["浮生失意頻，起絮又飄淪。","發自誰家樹，飛來獨院春。","朝容縈斷砌，晴影過諸鄰。","亂掩宮中蝶，繁衝陌上人。","隨波應到海，霑雨或依塵。","會向慈恩日，輕輕對此身。"]', '["浮生失意頻，起絮又飄淪。","發自誰家樹，飞来独院春。","朝容縈斷砌，晴影過諸鄰。","亂掩宮中蝶，繁衝陌上人。","隨波應到海，霑雨或依塵。","會向慈恩日，轻轻对此身。"]', '诗', 'shi', '', NULL, '詠柳花 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d0c667-b634-4962-8141-6a0cd84f56be', '一葉落', '一葉落', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["輕葉獨悠悠，天高片影流。","隨風來此地，何樹落先秋。","變色黃應近，辭林綠尚稠。","無雙浮水面，孤絕落關頭。","乍減誠難覺，將凋勢未休。","客心空自比，誰肯問新愁。"]', '["轻葉独悠悠，天高片影流。","隨风来此地，何樹落先秋。","变色黄應近，辞林綠尚稠。","無雙浮水面，孤絕落关头。","乍減誠难覺，將凋勢未休。","客心空自比，誰肯问新愁。"]', '诗', 'shi', '', NULL, '一葉落 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6434820-81da-4427-a554-caac87fc0cdf', '行路難', '行路难', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["何處力堪殫，人心險萬端。","藏山難測度，暗水自波瀾。","對面如千里，迴腸似七盤。","已經吳坂困，欲向鴈門難。","南北誠須泣，高深不可干。","無因善行止，車轍得平安。"]', '["何处力堪殫，人心險万端。","藏山难測度，暗水自波瀾。","对面如千里，迴腸似七盤。","已經吳坂困，欲向鴈门难。","南北誠須泣，高深不可干。","無因善行止，车轍得平安。"]', '诗', 'shi', '', NULL, '行路難 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0f2334-0b47-4ac2-a347-12ec1ae3ddd0', '蔡州蔣亭', '蔡州蔣亭', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["草徑徹林間，過橋如入山。","蔡侯添水榭，蔣氏本柴關。","靜汎窮幽趣，驚飛濕醉顏。","恨無優俸買，來得暫時閑。","步與招提接，舟臨夕照還。","春風應不到，前想負花灣。"]', '["草徑徹林间，過橋如入山。","蔡侯添水榭，蔣氏本柴关。","静汎窮幽趣，驚飞濕醉顏。","恨無優俸買，来得暫时闲。","步與招提接，舟臨夕照還。","春风應不到，前想負花灣。"]', '诗', 'shi', '', NULL, '蔡州蔣亭 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec0c18dc-509b-41d2-b17e-d0359d6ad1f9', '戲題', '戲題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["閃閃動鳴璫，初來燭影傍。","擁頭珠翠重，縈步綺羅長。","靜發歌如磬，連飄氣覺香。","不言微有笑，多媚總無妝。","坐缺初離席，簾垂却入房。","思惟不是夢，此會勝高唐。"]', '["閃閃动鳴璫，初来燭影傍。","擁头珠翠重，縈步綺羅长。","静發歌如磬，連飄氣覺香。","不言微有笑，多媚總無妝。","坐缺初離席，簾垂却入房。","思惟不是梦，此會勝高唐。"]', '诗', 'shi', '', NULL, '戲題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bfc9e50-ef86-4df8-8d7c-0a0a7bdff2ea', '酬曹侍御見寄', '酬曹侍御见寄', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["儒道苦不勝，邇來惟慕禪。","觸途非巧者，於世分沈然。","要地羞難入，閑居鈍更便。","清和挑菜食，悶寂閉花眠。","累遣期拋俸，機忘怕與權。","妨春愁筦榷，響夜憶林泉。","匪石從遭刖，殊膏枉被煎。","討論唯子厚，藏退合吾先。","舊製羣英伏，來章六義全。","休旬一擬和，鄉思亂情田。"]', '["儒道苦不勝，邇来惟慕禪。","觸途非巧者，於世分沈然。","要地羞难入，闲居鈍更便。","清和挑菜食，悶寂閉花眠。","累遣期拋俸，機忘怕與權。","妨春愁筦榷，响夜憶林泉。","匪石從遭刖，殊膏枉被煎。","討論唯子厚，藏退合吾先。","旧製羣英伏，来章六義全。","休旬一擬和，乡思亂情田。"]', '诗', 'shi', '', NULL, '酬曹侍御見寄 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2887c0-d432-4dd8-83e9-852fb352c6f8', '送趙道士歸天目舊山', '送趙道士归天目旧山', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["愚朴尚公平，此心鄰道情。","有緣終自鄙，何計逐師行。","日者聞高躅，時人蓋強名。","口無滋味入，身有羽儀生。","奏乞還鄉遠，詩曾對御成。","土毛珍到越，塵髮倦離京。","符叱風雷惡，朝脩月露清。","觀臨天目頂，家住海潮聲。","道引圖看足，參同注解精。","休糧一擬問，窗草俟回程。"]', '["愚朴尚公平，此心鄰道情。","有緣終自鄙，何計逐師行。","日者闻高躅，时人蓋強名。","口無滋味入，身有羽儀生。","奏乞還乡远，诗曾对御成。","土毛珍到越，塵髮倦離京。","符叱风雷惡，朝脩月露清。","观臨天目頂，家住海潮声。","道引圖看足，參同注解精。","休糧一擬问，窗草俟回程。"]', '诗', 'shi', '', NULL, '送趙道士歸天目舊山 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c067e29-9c3a-4911-8bf6-f7d66c0c91de', '除夜作', '除夜作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["和吹度穹旻，虛徐接建寅。","不辭加一歲，唯喜到三春。","燎照雲煙好，幡懸井邑新。","禎祥應北極，調燮驗平津。","樹欲含遲日，山將退舊塵。","蘭萎殘此夜，竹爆和諸鄰。","祝壽思明聖，驅儺看鬼神。","團圓多少輩，眠寢獨勞筋。","茜斾猶雙節，雕盤又五辛。","何當平賊後，歸作自由身。"]', '["和吹度穹旻，虛徐接建寅。","不辞加一歲，唯喜到三春。","燎照云煙好，幡懸井邑新。","禎祥應北極，調燮驗平津。","樹欲含遲日，山將退旧塵。","蘭萎殘此夜，竹爆和諸鄰。","祝壽思明聖，驱儺看鬼神。","團圓多少輩，眠寢独勞筋。","茜斾猶雙節，雕盤又五辛。","何當平賊後，归作自由身。"]', '诗', 'shi', '', NULL, '除夜作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13fc10b0-140d-4db3-a984-a0bfe985c6c6', '桃花', '桃花', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["香色自天種，千年豈易逢。","開齊全未落，繁極欲相重。","泠濕朝如淡，晴乾午更濃。","風光新社燕，時節舊春農。","籬落欹臨竹，亭臺盛間松。","亂緣堪羨蟻，深入不如蜂。","有影宜暄煦，無言自冶容。","洞連非俗世，溪靜接仙蹤。","子熟河應變，根盤土已封。","西王潛愛惜，東朔盜過從。","醉席眠英好，題詩戀景慵。","芳菲聊一望，何必在臨邛。"]', '["香色自天種，千年豈易逢。","开齊全未落，繁極欲相重。","泠濕朝如淡，晴乾午更濃。","风光新社燕，时節旧春農。","籬落欹臨竹，亭台盛间松。","亂緣堪羨蟻，深入不如蜂。","有影宜暄煦，無言自冶容。","洞連非俗世，溪静接仙蹤。","子熟河應变，根盤土已封。","西王潛愛惜，东朔盜過從。","醉席眠英好，題诗戀景慵。","芳菲聊一望，何必在臨邛。"]', '诗', 'shi', '', NULL, '桃花 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff8314f9-d177-421a-b9fb-9bc743969b6d', '黃河', '黄河', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["何處發崑崙，連乾復浸坤。","波渾經鴈塞，聲振自龍門。","岸裂新衝勢，灘餘舊落痕。","橫溝通海上，遠色盡山根。","勇逗三峰坼，雄標四瀆尊。","灣中秋景樹，闊外夕陽村。","沫亂知魚呴，槎來見鳥蹲。","飛沙當白日，凝霧接黃昏。","潤可資農畝，清能表帝恩。","雨吟堪極目，風度想驚魂。","顯瑞龜曾出，陰靈伯固存。","盤渦寒漸急，淺瀨暑微溫。","九曲終柔勝，常流可暗吞。","人間無博望，誰復到窮源。"]', '["何处發崑崙，連乾复浸坤。","波渾經鴈塞，声振自龙门。","岸裂新衝勢，灘餘旧落痕。","橫溝通海上，远色尽山根。","勇逗三峰坼，雄標四瀆尊。","灣中秋景樹，闊外夕陽村。","沫亂知鱼呴，槎来见鸟蹲。","飞沙當白日，凝霧接黄昏。","潤可資農畝，清能表帝恩。","雨吟堪極目，风度想驚魂。","显瑞龟曾出，陰靈伯固存。","盤渦寒漸急，淺瀨暑微溫。","九曲終柔勝，常流可暗吞。","人间無博望，誰复到窮源。"]', '诗', 'shi', '', NULL, '黃河 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd1545b-cdf0-43e8-a396-675c3f6a6e78', '華嶽', '华嶽', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["簇簇復亭亭，三峰卓杳冥。","每思窮本末，應合記圖經。","發地連宮觀，衝天接井星。","河微臨巨勢，秦重載奇形。","太古朝羣后，中央擘巨靈。","鄰州猶映檻，幾縣恰當庭。","鶴毳壇風亂，龍漦洞水腥。","望遙通北極，上徹見東溟。","客翫晴難偶，農祈雨必零。","度關無暑氣，過路得愁醒。","羽客時應見，霜猨夜可聽。","頂懸飛瀑峻，崦合白雲青。","混石猜良玉，尋苗得茯苓。","從官知側近，悉俸致巖扃。"]', '["簇簇复亭亭，三峰卓杳冥。","每思窮本末，應合記圖經。","發地連宮观，衝天接井星。","河微臨巨勢，秦重載奇形。","太古朝羣后，中央擘巨靈。","鄰州猶映檻，幾縣恰當庭。","鹤毳壇风亂，龙漦洞水腥。","望遙通北極，上徹见东溟。","客翫晴难偶，農祈雨必零。","度关無暑氣，過路得愁醒。","羽客时應见，霜猨夜可听。","頂懸飞瀑峻，崦合白云青。","混石猜良玉，尋苗得茯苓。","從官知側近，悉俸致巖扃。"]', '诗', 'shi', '', NULL, '華嶽 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f7d4937-da1e-4b8b-8054-53feed0425c8', '秋雨', '秋雨', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["宿雨覺纔初，亭林忽復徐。","簇聲諸樹密，懸滴四簷疎。","省漏疑方丈，愁炊問斗儲。","步難多入屐，窗淺欲飄書。","動蠖蒼苔靜，藏蠶落葉虛。","吹交來翕習，雷慢歇躊躇。","滯已妨行路，晴應好荷鋤。","醉樓思蜀客，鯹市想淮魚。","徑草因緣合，欄花自此除。","有形皆霢霂，無地不汙瀦。","境晦宜甘寢，風清□退居。","我魂驚曉簟，鄰話喜秋蔬。","既用功成歲，旋應慘變舒。","倉箱足可恃，歸去傲吾廬。"]', '["宿雨覺纔初，亭林忽复徐。","簇声諸樹密，懸滴四簷疎。","省漏疑方丈，愁炊问斗儲。","步难多入屐，窗淺欲飄书。","动蠖蒼苔静，藏蠶落葉虛。","吹交来翕習，雷慢歇躊躇。","滯已妨行路，晴應好荷鋤。","醉楼思蜀客，鯹市想淮鱼。","徑草因緣合，欄花自此除。","有形皆霢霂，無地不汙瀦。","境晦宜甘寢，风清□退居。","我魂驚晓簟，鄰話喜秋蔬。","既用功成歲，旋應慘变舒。","倉箱足可恃，归去傲吾廬。"]', '诗', 'shi', '', NULL, '秋雨 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4e65e3-f1fc-4dc2-9d91-5c3590907cd7', '春色滿皇州', '春色满皇州', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["藹藹復悠悠，春歸十二樓。","最明雲裏闕，先滿日邊州。","色媚青門外，光搖紫陌頭。","上林榮舊樹，太液鏡新流。","暖帶祥煙起，清添瑞景浮。","陽和如啓蟄，從此事芳遊。"]', '["藹藹复悠悠，春归十二楼。","最明云裏闕，先满日邊州。","色媚青门外，光搖紫陌头。","上林榮旧樹，太液镜新流。","暖带祥煙起，清添瑞景浮。","陽和如啓蟄，從此事芳游。"]', '诗', 'shi', '', NULL, '春色滿皇州 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33728d98-46d4-4929-bf68-c8825bd978cd', '寄唁張喬喻坦之', '寄唁張喬喻坦之', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["何事盡參差，惜哉吾子詩。","日令銷此道，天亦負明時。","有路當重振，無門即不知。","何當見堯日，相與啜澆漓。"]', '["何事尽參差，惜哉吾子诗。","日令銷此道，天亦負明时。","有路當重振，無门即不知。","何當见堯日，相與啜澆漓。"]', '诗', 'shi', '', NULL, '寄唁張喬喻坦之 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94a929a6-5aff-48ef-a3a2-a9b8023e5a99', '贈僧', '贈僧', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["盡日行方到，何年獨此林。","客歸惟鶴伴，人少似師心。","坐石落松子，禪牀搖竹陰。","山靈怕驚定，不遣夜猨吟。"]', '["尽日行方到，何年独此林。","客归惟鹤伴，人少似師心。","坐石落松子，禪牀搖竹陰。","山靈怕驚定，不遣夜猨吟。"]', '诗', 'shi', '', NULL, '贈僧 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2890b42e-a963-4d0e-af7b-6fea8787f576', '春日旅舍書懷', '春日旅舍书懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["出去歸來旅食人，麻衣長帶幾坊塵。","開門草色朝無客，落案燈花夜一身。","貧舍臥多消永日，故園鶯老憶殘春。","蹉跎冠蓋誰相念，二十年中盡苦辛。"]', '["出去归来旅食人，麻衣长带幾坊塵。","开门草色朝無客，落案灯花夜一身。","貧舍臥多消永日，故园鶯老憶殘春。","蹉跎冠蓋誰相念，二十年中尽苦辛。"]', '诗', 'shi', '', NULL, '春日旅舍書懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25b2850e-6107-45a3-a5bc-e1fbf91ff39b', '秋日將離滑臺酬所知二首 一', '秋日將離滑台酬所知二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["身起中宵骨亦驚，一分年少已無成。","松吹竹簟朝眠冷，雨濕蔬飡宿疾生。","僮汲野泉兼土味，馬磨霜樹作秋聲。","相知莫話詩心苦，未似前賢取得名。"]', '["身起中宵骨亦驚，一分年少已無成。","松吹竹簟朝眠冷，雨濕蔬飡宿疾生。","僮汲野泉兼土味，马磨霜樹作秋声。","相知莫話诗心苦，未似前賢取得名。"]', '诗', 'shi', '', NULL, '秋日將離滑臺酬所知二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282ededa-af64-410b-beb5-0220b4c0c45b', '秋日將離滑臺酬所知二首 二', '秋日將離滑台酬所知二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["燈澀秋光靜不眠，葉聲身影客窗前。","閑園露濕鳴蛩夜，急雨風吹落木天。","城見遠山應北嶽，野多空地本南燕。","明朝欲別忘形處，愁把離杯聽管弦。"]', '["灯澀秋光静不眠，葉声身影客窗前。","闲园露濕鳴蛩夜，急雨风吹落木天。","城见远山應北嶽，野多空地本南燕。","明朝欲別忘形处，愁把離杯听管弦。"]', '诗', 'shi', '', NULL, '秋日將離滑臺酬所知二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('309447c1-e083-41c4-83cc-234d2527bf44', '下第後夷門乘舟至永城驛題', '下第後夷门乘舟至永城驛題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["秋賦春還計盡違，自知身是拙求知。","唯思曠海爲休處，忽喜孤舟似去時。","連浦一城兼汴宋，夾堤千柳雜唐隋。","從來此恨皆前達，敢負吾君作楚辭。"]', '["秋賦春還計尽違，自知身是拙求知。","唯思曠海爲休处，忽喜孤舟似去时。","連浦一城兼汴宋，夾堤千柳杂唐隋。","從来此恨皆前達，敢負吾君作楚辞。"]', '诗', 'shi', '', NULL, '下第後夷門乘舟至永城驛題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4080e7b-319a-406b-8c28-0b0973b085b5', '秋夜旅舍寓懷', '秋夜旅舍寓懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["庭鎖荒蕪獨夜吟，西風吹動故山心。","三秋木落半年客，滿地月明何處砧？","漁唱亂沿汀鷺合，鴈聲寒咽隴雲深。","平生只有松堪對，露浥霜欺不受侵。"]', '["庭鎖荒蕪独夜吟，西风吹动故山心。","三秋木落半年客，满地月明何处砧？","漁唱亂沿汀鷺合，鴈声寒咽隴云深。","平生只有松堪对，露浥霜欺不受侵。"]', '诗', 'shi', '', NULL, '秋夜旅舍寓懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b7399e5-1997-4d68-9ba2-58f82998b827', '洛下寓懷', '洛下寓懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["胡爲遭遇孰爲官，朝野君親各自歡。","敢向官途爭虎首，尚嫌身累愛猪肝。","冰霜谷口晨樵遠，星火爐邊夜坐寒。","唯有報恩心未剖，退居猶欲佩芄蘭。"]', '["胡爲遭遇孰爲官，朝野君親各自歡。","敢向官途爭虎首，尚嫌身累愛猪肝。","冰霜谷口晨樵远，星火爐邊夜坐寒。","唯有報恩心未剖，退居猶欲佩芄蘭。"]', '诗', 'shi', '', NULL, '洛下寓懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('369f6a0c-9c9c-4509-9a9c-3ce449037ad1', '題平湖', '題平湖', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["平湖湖畔雨晴新，南北東西不隔塵。","映野煙波浮動日，損花風雨寂寥春。","山無俗路藏高士，岸泊仙舟憶主人。","那得載來都未保，此心離此甚情親。"]', '["平湖湖畔雨晴新，南北东西不隔塵。","映野煙波浮动日，損花风雨寂寥春。","山無俗路藏高士，岸泊仙舟憶主人。","那得載来都未保，此心離此甚情親。"]', '诗', 'shi', '', NULL, '題平湖 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c8d252-7815-447a-a937-57e4d8cbe30c', '平陽寓懷', '平陽寓懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["晉國風流阻洳川，家家弦管路岐邊。","曾爲郡職隨分竹，亦作歌詞乞採蓮。","北榭遠峰閑即望，西湖殘景醉常眠。","牆花此日休迴避，不是當時惡少年。"]', '["晉国风流阻洳川，家家弦管路岐邊。","曾爲郡職隨分竹，亦作歌词乞採蓮。","北榭远峰闲即望，西湖殘景醉常眠。","牆花此日休迴避，不是當时惡少年。"]', '诗', 'shi', '', NULL, '平陽寓懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147ac7fc-d1ac-4f6f-b687-a834bbb31b9e', '留題汾上舊居', '留題汾上旧居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["鄉園一別五年歸，迴首人間總禍機。","尚勝鄰翁常寂寞，敢嫌裘馬未輕肥。","塵顏不見應消落，庭樹曾栽已合圍。","難說累牽還却去，可憐榆柳尚依依。"]', '["乡园一別五年归，迴首人间總禍機。","尚勝鄰翁常寂寞，敢嫌裘马未轻肥。","塵顏不见應消落，庭樹曾栽已合圍。","难说累牽還却去，可怜榆柳尚依依。"]', '诗', 'shi', '', NULL, '留題汾上舊居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfbf356f-c704-467a-a157-d87791865dec', '懷汾上舊居', '懷汾上旧居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["素汾千載傍吾家，常憶衡門對浣紗。","好事喜逢投宿客，刈田因得自生瓜。","山頭鼓笛陰沈廟，陌上薪蒸突兀車。","投暗作珠何所用，被人專擬害靈蛇。"]', '["素汾千載傍吾家，常憶衡门对浣紗。","好事喜逢投宿客，刈田因得自生瓜。","山头鼓笛陰沈廟，陌上薪蒸突兀车。","投暗作珠何所用，被人專擬害靈蛇。"]', '诗', 'shi', '', NULL, '懷汾上舊居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b68dc1-5226-49f1-b463-4cda900d7fd4', '送同儒大德歸柏梯寺', '送同儒大德归柏梯寺', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["柏梯還擬謝微官，遙擬千峰送法蘭。","行徑未曾青石斷，拂牀終有白雲殘。","京塵濯後三衣潔，山舍禪初萬象安。","薇蕨縱多師莫踏，我心猶欲盡圖看。"]', '["柏梯還擬謝微官，遙擬千峰送法蘭。","行徑未曾青石斷，拂牀終有白云殘。","京塵濯後三衣潔，山舍禪初万象安。","薇蕨縱多師莫踏，我心猶欲尽圖看。"]', '诗', 'shi', '', NULL, '送同儒大德歸柏梯寺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac87c33-36bc-41ed-b6d8-9ad7bd82e387', '春日使府寓懷二首 一', '春日使府寓懷二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一想流年百事驚，已拋漁父戴塵纓。","青春背我堂堂去，白髮欺人故故生。","道困古來應有分，詩傳身後亦何榮。","誰憐合負清朝力，獨把風騷破鄭聲。"]', '["一想流年百事驚，已拋漁父戴塵纓。","青春背我堂堂去，白髮欺人故故生。","道困古来應有分，诗傳身後亦何榮。","誰怜合負清朝力，独把风騷破鄭声。"]', '诗', 'shi', '', NULL, '春日使府寓懷二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0e6dd61-d138-45d5-8b47-14f0f151ad9a', '春日使府寓懷二首 二', '春日使府寓懷二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["平生無解亦無操，永日書生坐獨勞。","唯覺宦情如水薄，不知人事有山高。","孤心好直迍猶強，病髮慵梳癢更搔。","何事故溪歸未得，幾拋清淺汎紅桃。"]', '["平生無解亦無操，永日书生坐独勞。","唯覺宦情如水薄，不知人事有山高。","孤心好直迍猶強，病髮慵梳癢更搔。","何事故溪归未得，幾拋清淺汎紅桃。"]', '诗', 'shi', '', NULL, '春日使府寓懷二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d074046-3761-418c-8d13-0ee19ead67f3', '許州題德星亭', '許州題德星亭', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["瀵水南流東有堤，堤邊亭是武陵溪。","槎松配石堪僧坐，蘂杏含春欲鳥啼。","高樹月生滄海外，遠郊山在夕陽西。","頻來不似軍從事，只戴紗巾曳杖藜。"]', '["瀵水南流东有堤，堤邊亭是武陵溪。","槎松配石堪僧坐，蘂杏含春欲鸟啼。","高樹月生滄海外，远郊山在夕陽西。","頻来不似軍從事，只戴紗巾曳杖藜。"]', '诗', 'shi', '', NULL, '許州題德星亭 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8002801-d823-4d6a-b80e-4a50f687e48e', '送人歸上黨', '送人归上黨', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["燕臺基壤穴狐蛇，計拙因循歲月賒。","兵革未銷王在鎬，桑蠶臨熟客還家。","霏微對岸漳邊雨，堆阜鄰疆薊北沙。","若到長平戰場地，爲求遺鏃辟魔邪。"]', '["燕台基壤穴狐蛇，計拙因循歲月賒。","兵革未銷王在鎬，桑蠶臨熟客還家。","霏微对岸漳邊雨，堆阜鄰疆薊北沙。","若到长平戰場地，爲求遺鏃辟魔邪。"]', '诗', 'shi', '', NULL, '送人歸上黨 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a437d554-6505-4e38-9ace-93459f0dab1c', '春日重遊平湖', '春日重游平湖', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["湖上春風發管弦，須臨三十此離筵。","離人忽有重來日，遊女初非舊少年。","官職已辜疲瘵望，詩名空被後生傳。","啼鶯莫惜蹉跎恨，閑事聽吟一兩篇。"]', '["湖上春风發管弦，須臨三十此離筵。","離人忽有重来日，游女初非旧少年。","官職已辜疲瘵望，诗名空被後生傳。","啼鶯莫惜蹉跎恨，闲事听吟一兩篇。"]', '诗', 'shi', '', NULL, '春日重遊平湖 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c86c1a4-8a34-459e-9236-19a2b0400bfe', '幷州', '幷州', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["少年流落在幷州，裘脫文君取次遊。","攜挈共過芳草渡，登臨齊凭綠楊樓。","庭前蛺蝶春方好，牀上樗蒲宿未收。","坊號偃松人在否，餅爐南畔曲西頭。"]', '["少年流落在幷州，裘脫文君取次游。","携挈共過芳草渡，登臨齊凭綠楊楼。","庭前蛺蝶春方好，牀上樗蒲宿未收。","坊號偃松人在否，餅爐南畔曲西头。"]', '诗', 'shi', '', NULL, '幷州 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b976a5a-f247-412c-9ec8-53419cb13ccb', '相國隴西公南征能以留務獨宿府城作', '相国隴西公南征能以留務独宿府城作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["吾君賢相事南征，獨宿軍廚負請纓。","燈室臥孤如怨別，月階簪草似臨行。","高墉撼鐸思巴棧，老木嘷風念野營。","殊憶好僧招不及，夜來倉卒鏁嚴城。"]', '["吾君賢相事南征，独宿軍廚負請纓。","灯室臥孤如怨別，月階簪草似臨行。","高墉撼鐸思巴棧，老木嘷风念野營。","殊憶好僧招不及，夜来倉卒鏁嚴城。"]', '诗', 'shi', '', NULL, '相國隴西公南征能以留務獨宿府城作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('360d74c9-21f0-439c-a941-e49d0ec1eab2', '早春書事', '早春书事', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["百蠻降伏委三秦，錦里風迴歲已新。","渠濫水泉花巷濕，日銷冰雪柳營春。","何年道勝蘇羣物，盡室天涯是旅人。","焚却蜀書宜不讀，武侯無可律余身。"]', '["百蠻降伏委三秦，錦里风迴歲已新。","渠濫水泉花巷濕，日銷冰雪柳營春。","何年道勝蘇羣物，尽室天涯是旅人。","焚却蜀书宜不读，武侯無可律余身。"]', '诗', 'shi', '', NULL, '早春書事 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b08e9cfa-ab7a-44d2-a447-4e0c51e669bd', '春日書懷', '春日书懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["伯牙琴絕豈求知，往往情牽自有詩。","壠月正當寒食夜，春陰初過海棠時。","耽書未必酬良相，斷酒唯堪作老師。","多病不任衣更薄，東風臺上莫相吹。"]', '["伯牙琴絕豈求知，往往情牽自有诗。","壠月正當寒食夜，春陰初過海棠时。","耽书未必酬良相，斷酒唯堪作老師。","多病不任衣更薄，东风台上莫相吹。"]', '诗', 'shi', '', NULL, '春日書懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c65a92-ad1c-4ecd-ad24-10a8dd630291', '投杜舍人', '投杜舍人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["牀上新詩詔草和，欄邊清酒落花多。","閒消白日舍人宿，夢覺紫薇山鳥過。","春刻幾分添禁漏，夏桐初葉滿庭柯。","風騷委地苦無主，此事聖君終若何。"]', '["牀上新诗詔草和，欄邊清酒落花多。","閒消白日舍人宿，梦覺紫薇山鸟過。","春刻幾分添禁漏，夏桐初葉满庭柯。","风騷委地苦無主，此事聖君終若何。"]', '诗', 'shi', '', NULL, '投杜舍人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849e62e4-d408-4529-95c5-6153612abc1f', '獻僕射相公', '獻僕射相公', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["清如冰雪重如山，百辟嚴趨禮絕攀。","強虜外聞應喪膽，平人相見盡開顏。","朝廷有道青春好，門館無私白日閑。","致却垂衣更何事，幾多詩句詠關關。"]', '["清如冰雪重如山，百辟嚴趨禮絕攀。","強虜外闻應喪膽，平人相见尽开顏。","朝廷有道青春好，门館無私白日闲。","致却垂衣更何事，幾多诗句詠关关。"]', '诗', 'shi', '', NULL, '獻僕射相公 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3500d0b7-c644-49ff-946f-c0c86e36cae1', '上鹽鐵尚書', '上鹽鐵尚书', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["南宮環雉隔囂塵，況值清齋宿大臣。","城絕鼓鐘更點後，雨涼煙樹月華新。","簷前漱曉穹蒼碧，庭下眠秋沆瀣津。","聞說務閑心更靜，此時憂國合求人。"]', '["南宮环雉隔囂塵，況值清斋宿大臣。","城絕鼓鐘更点後，雨涼煙樹月华新。","簷前漱晓穹蒼碧，庭下眠秋沆瀣津。","闻说務闲心更静，此时憂国合求人。"]', '诗', 'shi', '', NULL, '上鹽鐵尚書 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9941e5d6-e506-4263-b89d-cfd26cc350b7', '漢南春望', '漢南春望', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["獨尋春色上高臺，三月皇州駕未回。","幾處松筠燒後死，誰家桃李亂中開。","奸邪用法原非法，唱和求才不是才。","自古浮雲蔽白日，洗天風雨幾時來。"]', '["独尋春色上高台，三月皇州駕未回。","幾处松筠燒後死，誰家桃李亂中开。","奸邪用法原非法，唱和求才不是才。","自古浮云蔽白日，洗天风雨幾时来。"]', '诗', 'shi', '', NULL, '漢南春望 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('111d5959-a747-421e-80ce-d853a26856f0', '晚春', '晚春', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["惡憐風景極交親，每恨年年作瘦人。","臥晚不曾拋好夜，情多唯欲哭殘春。","陰成杏葉纔通日，雨著楊花已汙塵。","無限後期知有在，只愁煩作總戎身。"]', '["惡怜风景極交親，每恨年年作瘦人。","臥晚不曾拋好夜，情多唯欲哭殘春。","陰成杏葉纔通日，雨著楊花已汙塵。","無限後期知有在，只愁煩作總戎身。"]', '诗', 'shi', '', NULL, '晚春 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57acb0c8-c418-41aa-a886-ed7808ac8e31', '將赴鎮過太康縣有題', '將赴鎮過太康縣有題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["纔入東郊便太康，自聽何暮豈龔黃。","晴村透日桑榆影，曉露濕秋禾黍香。","十萬旌旗移巨鎮，幾多輗軏負孤莊。","時人欲識征東將，看取欃槍落太荒。"]', '["纔入东郊便太康，自听何暮豈龔黄。","晴村透日桑榆影，晓露濕秋禾黍香。","十万旌旗移巨鎮，幾多輗軏負孤莊。","时人欲識征东將，看取欃槍落太荒。"]', '诗', 'shi', '', NULL, '將赴鎮過太康縣有題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dae0cb8-4a30-4334-995d-2adf8e3bf82f', '彭門解嘲二首 一', '彭门解嘲二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嗚嗚吹角貳師營，落日身閑笑傲行。","盡覺文章尊萬事，却嫌官職剩雙旌。","終休未擬降低屈，忽遇還須致太平。","頻上水樓誰會我，泗濱浮磬是同聲。"]', '["嗚嗚吹角貳師營，落日身闲笑傲行。","尽覺文章尊万事，却嫌官職剩雙旌。","終休未擬降低屈，忽遇還須致太平。","頻上水楼誰會我，泗濱浮磬是同声。"]', '诗', 'shi', '', NULL, '彭門解嘲二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0449950c-0bf3-4126-99f6-5a17c7b203bc', '彭門解嘲二首 二', '彭门解嘲二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["傷禽栖後意猶驚，偶向黐竿脫此生。","身外不思簪組事，耳中唯要管弦聲。","耽吟乍可妨時務，淺飲無因致宿酲。","秦客莫嘲瓜戍遠，水風瀟灑是彭城。"]', '["傷禽栖後意猶驚，偶向黐竿脫此生。","身外不思簪組事，耳中唯要管弦声。","耽吟乍可妨时務，淺饮無因致宿酲。","秦客莫嘲瓜戍远，水风瀟灑是彭城。"]', '诗', 'shi', '', NULL, '彭門解嘲二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540971f7-0aca-4980-95ce-ef2309a75071', '清河汎舟', '清河汎舟', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["都人層立似山丘，坐嘯將軍擁棹遊。","遶郭煙波浮泗水，一船絲竹載涼州。","城中覩望皆丹雘，旗裏驚飛盡白鷗。","儒將不須誇郄縠，未聞詩句解風流。"]', '["都人層立似山丘，坐嘯將軍擁棹游。","遶郭煙波浮泗水，一船絲竹載涼州。","城中覩望皆丹雘，旗裏驚飞尽白鷗。","儒將不須誇郄縠，未闻诗句解风流。"]', '诗', 'shi', '', NULL, '清河汎舟 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c7bc07-b7d1-4973-99e5-82d36e686745', '新竹', '新竹', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["柳營茅土倦麤材，因向山家乞翠栽。","清露便敎終夜滴，好風疑是故園來。","欄邊匠去朱猶濕，溉後蟲浮穴暗開。","他日會應威鳳至，莫辭公府受塵埃。"]', '["柳營茅土倦麤材，因向山家乞翠栽。","清露便敎終夜滴，好风疑是故园来。","欄邊匠去朱猶濕，溉後蟲浮穴暗开。","他日會應威鳳至，莫辞公府受塵埃。"]', '诗', 'shi', '', NULL, '新竹 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('390bc411-91ee-4ebc-9b78-06ea6182c629', '晚春', '晚春', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["征東留滯一年年，又向軍前遇火前。","畫出鷁舟宜祓禊，鏤成雞卵有鞦韆。","澄明煙水孤城立，狼藉風花落日眠。","賴指清和櫻筍熟，不然愁殺暮春天。"]', '["征东留滯一年年，又向軍前遇火前。","畫出鷁舟宜祓禊，鏤成雞卵有鞦韆。","澄明煙水孤城立，狼藉风花落日眠。","賴指清和櫻筍熟，不然愁殺暮春天。"]', '诗', 'shi', '', NULL, '晚春 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069395bb-111f-436d-b00a-feaf52b57399', '題彭祖樓', '題彭祖楼', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["新晴天狀濕融融，徐國灘聲上下洪。","極目澄鮮無限景，入懷輕好可憐風。","身防潦倒師彭祖，妓擁登臨媿謝公。","誰致此樓潛惠我，萬家殘照在河東。"]', '["新晴天狀濕融融，徐国灘声上下洪。","極目澄鲜無限景，入懷轻好可怜风。","身防潦倒師彭祖，妓擁登臨媿謝公。","誰致此楼潛惠我，万家殘照在河东。"]', '诗', 'shi', '', NULL, '題彭祖樓 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f1e3453-1e0b-4da7-9ed4-38becac07afe', '漢廟祈雨回陽春亭有懷', '漢廟祈雨回陽春亭有懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["南榮軒檻接城闉，適罷祈農此訪春。","九九已從南至盡，芊芊初傍北籬新。","池中水是前秋雨，陌上風驚自古塵。","欲召羅敷傾一盞，乘閒言語不容人。"]', '["南榮軒檻接城闉，適罷祈農此訪春。","九九已從南至尽，芊芊初傍北籬新。","池中水是前秋雨，陌上风驚自古塵。","欲召羅敷傾一盞，乘閒言語不容人。"]', '诗', 'shi', '', NULL, '漢廟祈雨回陽春亭有懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3d940b6-839d-4702-853d-288d4a1c1172', '送李倍秀才', '送李倍秀才', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["南朝才子尚途窮，畢竟應須問葉公。","書劒伴身離泗上，雪風吹面立船中。","家園棗熟歸圭竇，會府槐疎試射弓。","相顧日偏留不得，夜深聊欲一桮同。"]', '["南朝才子尚途窮，畢竟應須问葉公。","书劒伴身離泗上，雪风吹面立船中。","家园棗熟归圭竇，會府槐疎試射弓。","相顧日偏留不得，夜深聊欲一桮同。"]', '诗', 'shi', '', NULL, '送李倍秀才 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4d9433-e381-41f7-baf4-3c837d10cb1a', '重遊德星亭感事', '重游德星亭感事', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["穎水川中枕水臺，當時難別此重來。","舟沈土岸生新草，詩映紗籠有薄埃。","事繫興亡人少到，地當今古我遲迴。","殘陽照樹明於旭，猶向池邊把酒桮。"]', '["穎水川中枕水台，當时难別此重来。","舟沈土岸生新草，诗映紗籠有薄埃。","事繫兴亡人少到，地當今古我遲迴。","殘陽照樹明於旭，猶向池邊把酒桮。"]', '诗', 'shi', '', NULL, '重遊德星亭感事 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1a56b6-db2c-43c2-84a8-3c60372128fe', '許州題觀察判官廳', '許州題观察判官廳', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["三載從戎類繫匏，重遊全許尚分茅。","劉郎別後無遺履，丁令歸來有舊巢。","冬暖井梧多未落，夜寒窗竹自相敲。","纖腰弟子知千恨，笑與揚雄作解嘲。"]', '["三載從戎類繫匏，重游全許尚分茅。","劉郎別後無遺履，丁令归来有旧巢。","冬暖井梧多未落，夜寒窗竹自相敲。","纖腰弟子知千恨，笑與揚雄作解嘲。"]', '诗', 'shi', '', NULL, '許州題觀察判官廳 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835ba8be-b9ca-417c-b9df-58a7a389a64c', '閒題', '閒題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["八年藩翰似僑居，只此誰知報玉除。","舊將已成三僕射，老身猶是六尚書。","時丁厚讟終無咎，道致中興尚有餘。","爲問春風誰是主，空催弱柳擬何如。"]', '["八年藩翰似僑居，只此誰知報玉除。","旧將已成三僕射，老身猶是六尚书。","时丁厚讟終無咎，道致中兴尚有餘。","爲问春风誰是主，空催弱柳擬何如。"]', '诗', 'shi', '', NULL, '閒題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4936dd7c-b1ca-4475-935e-33888de20c4f', '送福建李大夫', '送福建李大夫', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["洛州良牧帥甌閩，曾是西垣作諫臣。","紅斾已勝前尹正，尺書猶帶舊絲綸。","秋來海有幽都鴈，船到城添外國人。","行過小藩應大笑，只知誇近不知貧。"]', '["洛州良牧帥甌閩，曾是西垣作諫臣。","紅斾已勝前尹正，尺书猶带旧絲綸。","秋来海有幽都鴈，船到城添外国人。","行過小藩應大笑，只知誇近不知貧。"]', '诗', 'shi', '', NULL, '送福建李大夫 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70779e82-343e-41d5-b503-55027fbef28a', '送李倍巡官歸永樂舊居', '送李倍巡官归永乐旧居', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["羨君歸去五峰前，往往星河實見仙。","麥壠夏枯成廢地，棗枝秋赤近高天。","山泉飲犢流多變，村酒經蠶味可憐。","曾約道門終老住，步虛聲裏寄閑眠。"]', '["羨君归去五峰前，往往星河實见仙。","麦壠夏枯成廢地，棗枝秋赤近高天。","山泉饮犢流多变，村酒經蠶味可怜。","曾約道门終老住，步虛声裏寄闲眠。"]', '诗', 'shi', '', NULL, '送李倍巡官歸永樂舊居 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5ef131-5228-495f-935a-89a8f2913de3', '贈歌者', '贈歌者', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一字新聲一顆珠，轉喉疑是擊珊瑚。","聽時坐部音中有，唱後櫻花葉裏無。","漢浦蔑聞虛解佩，臨邛焉用枉當壚。","誰人得向青樓宿，便是仙郎不是夫。"]', '["一字新声一顆珠，轉喉疑是擊珊瑚。","听时坐部音中有，唱後櫻花葉裏無。","漢浦蔑闻虛解佩，臨邛焉用枉當壚。","誰人得向青楼宿，便是仙郎不是夫。"]', '诗', 'shi', '', NULL, '贈歌者 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487f1835-c97e-4368-a0fb-80caeef1b4f4', '舞者', '舞者', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["綠毛釵動小相思，一唱南軒日午時。","慢靸輕裾行欲近，待調諸曲起來遲。","筵停匕筯無非聽，吻帶宮商盡是詞。","爲問傾城年幾許，更勝瓊樹是瓊枝。"]', '["綠毛釵动小相思，一唱南軒日午时。","慢靸轻裾行欲近，待調諸曲起来遲。","筵停匕筯無非听，吻带宮商尽是词。","爲问傾城年幾許，更勝瓊樹是瓊枝。"]', '诗', 'shi', '', NULL, '舞者 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10fd9791-873b-4b45-9b7a-23c17eef5862', '天際識歸舟', '天際識归舟', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["斜日滿江樓，天涯照背流。","同人在何處，遠目認孤舟。","帆省當時席，歌聲舊日謳。","人浮津濟晚，棹倚泬寥秋。","晴闊忻全見，歸遲怪久遊。","離居意無限，貪此望難休。"]', '["斜日满江楼，天涯照背流。","同人在何处，远目認孤舟。","帆省當时席，歌声旧日謳。","人浮津濟晚，棹倚泬寥秋。","晴闊忻全见，归遲怪久游。","離居意無限，貪此望难休。"]', '诗', 'shi', '', NULL, '天際識歸舟 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c983a658-e451-41c8-bbb1-9b61206ace6e', '和曹侍御除夜有懷', '和曹侍御除夜有懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["有病無媒客，多慵亦太疎。","自憐成叔夜，誰與薦相如。","嗜退思年老，諳空笑歲除。","跡閑過寺宿，頭煖近階梳。","春立窮冬後，陽生舊物初。","葉多庭不掃，根在逕新鋤。","田事終歸彼，心情倦老於。","斵材須見像，藏劒豈爲魚。","效淺慙尹祿，恩多負辟書。","醻知必擬共，勿使浪躊躇。"]', '["有病無媒客，多慵亦太疎。","自怜成叔夜，誰與薦相如。","嗜退思年老，諳空笑歲除。","跡闲過寺宿，头煖近階梳。","春立窮冬後，陽生旧物初。","葉多庭不掃，根在逕新鋤。","田事終归彼，心情倦老於。","斵材須见像，藏劒豈爲鱼。","效淺慙尹祿，恩多負辟书。","醻知必擬共，勿使浪躊躇。"]', '诗', 'shi', '', NULL, '和曹侍御除夜有懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd60fbc-fd71-4c83-a553-76a880c8c1df', '華清宮和杜舍人', '华清宮和杜舍人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["五十年天子，離宮仰峻牆。","登封時正泰，御宇日何長。","上位先名實，中興事憲章。","起戎輕甲胄，餘地復河湟。","道降玄元祖，儒封孔子王。","因緣百司署，聚會一人湯。","渭水波搖綠，秦山草半黃。","馬馴金勒細，鷹健玉鈴鏘。","下箭朱方滿，鳴鞭皓腕攘。","畋思獲呂望，諫祗避周昌。","兔跡貪前逐，梟心不早防。","幾添鸚鵡勸，先賜荔枝嘗。","月鎖千門靜，天吹一笛涼。","細音搖羽佩，輕步宛霓裳。","禍亂基潛結，昇平意遽忘。","衣冠逃犬虜，鼙鼓動漁陽。","外戚心殊迫，中原事可量。","血埋妃子豔，刃斷祿兒腸。","近侍煙塵隔，前蹤輦路荒。","益知迷寵佞，遺恨喪賢良。","北闕尊明主，南宮遜上皇。","禁清餘鳳吹，池冷睡龍光。","祝壽山猶在，流年水共傷。","杜鵑魂厭蜀，蝴蝶夢悲壯。","雀卵遺雕栱，蟲絲罥畫梁。","紫苔侵壁潤，紅樹閉門芳。","守吏齊鴛瓦，耕民得翠璫。","登年昔酺樂，講武舊兵場。","暮草深巖翠，幽花墜逕香。","不堪垂白叟，行折御溝楊。"]', '["五十年天子，離宮仰峻牆。","登封时正泰，御宇日何长。","上位先名實，中兴事憲章。","起戎轻甲胄，餘地复河湟。","道降玄元祖，儒封孔子王。","因緣百司署，聚會一人湯。","渭水波搖綠，秦山草半黄。","马馴金勒細，鷹健玉鈴鏘。","下箭朱方满，鳴鞭皓腕攘。","畋思獲呂望，諫祗避周昌。","兔跡貪前逐，梟心不早防。","幾添鸚鵡勸，先賜荔枝嘗。","月鎖千门静，天吹一笛涼。","細音搖羽佩，轻步宛霓裳。","禍亂基潛結，昇平意遽忘。","衣冠逃犬虜，鼙鼓动漁陽。","外戚心殊迫，中原事可量。","血埋妃子豔，刃斷祿兒腸。","近侍煙塵隔，前蹤輦路荒。","益知迷寵佞，遺恨喪賢良。","北闕尊明主，南宮遜上皇。","禁清餘鳳吹，池冷睡龙光。","祝壽山猶在，流年水共傷。","杜鵑魂厭蜀，蝴蝶梦悲壯。","雀卵遺雕栱，蟲絲罥畫梁。","紫苔侵壁潤，紅樹閉门芳。","守吏齊鴛瓦，耕民得翠璫。","登年昔酺乐，講武旧兵場。","暮草深巖翠，幽花墜逕香。","不堪垂白叟，行折御溝楊。"]', '诗', 'shi', '', NULL, '華清宮和杜舍人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1018ad98-bcb0-4e76-9168-24d7d881f371', '送浙東王大夫', '送浙东王大夫', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["天爵擅忠貞，皇恩復寵榮。","遠源過晉史，甲族本緱笙。","亞相兼尤美，周行歷盡清。","制除天近曉，衙謝草初生。","賓客招閑地，戎裝擁上京。","九街鳴玉勒，一宅照紅旌。","細雨當離席，遙花顯去程。","佩刀畿甸色，歌吹館橋聲。","騕褭從秦賜，艅艎到汴迎。","步沙逢霽月，宿岸致嚴更。","渤澥流東鄙，天台壓屬城。","衆談稱重鎮，公意念疲甿。","井邑曾多難，瘡痍此未平。","察應均賦歛，逃必復桑耕。","隼重權兼帥，鼉雄設有兵。","越臺隨厚俸，剡硾得尤名。","夜蠟州中宴，春風部外行。","香匳扃鳳詔，朱篆動龍坑。","報後功何患，投虛論素精。","徵還真指掌，感激自關情。","舊業懷昏作，微班負旦評。","空餘騷雅事，千古傲劉楨。"]', '["天爵擅忠貞，皇恩复寵榮。","远源過晉史，甲族本緱笙。","亞相兼尤美，周行歷尽清。","制除天近晓，衙謝草初生。","賓客招闲地，戎裝擁上京。","九街鳴玉勒，一宅照紅旌。","細雨當離席，遙花显去程。","佩刀畿甸色，歌吹館橋声。","騕褭從秦賜，艅艎到汴迎。","步沙逢霽月，宿岸致嚴更。","渤澥流东鄙，天台壓屬城。","衆談稱重鎮，公意念疲甿。","井邑曾多难，瘡痍此未平。","察應均賦歛，逃必复桑耕。","隼重權兼帥，鼉雄設有兵。","越台隨厚俸，剡硾得尤名。","夜蠟州中宴，春风部外行。","香匳扃鳳詔，朱篆动龙坑。","報後功何患，投虛論素精。","徵還真指掌，感激自关情。","旧業懷昏作，微班負旦評。","空餘騷雅事，千古傲劉楨。"]', '诗', 'shi', '', NULL, '送浙東王大夫 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80560e30-5af8-40fc-8303-28a4023e6bf7', '送李殷遊京西', '送李殷游京西', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["立馬送君地，黯然愁到身。","萬途皆有匠，六義獨無人。","莫怪敢言此，已能甘世貧。","時來貴亦在，事是掩何因。","投刺皆羈旅，遊邊更苦辛。","岐山終蜀境，涇水復蠻塵。","埋沒飡須強，炎蒸醉莫頻。","俗徒欺合得，吾道死終新。","展分先難許，論詩永共親。","歸京稍作意，充斥犯西鄰。"]', '["立马送君地，黯然愁到身。","万途皆有匠，六義独無人。","莫怪敢言此，已能甘世貧。","时来貴亦在，事是掩何因。","投刺皆羈旅，游邊更苦辛。","岐山終蜀境，涇水复蠻塵。","埋沒飡須強，炎蒸醉莫頻。","俗徒欺合得，吾道死終新。","展分先难許，論诗永共親。","归京稍作意，充斥犯西鄰。"]', '诗', 'shi', '', NULL, '送李殷遊京西 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b31c72-4f72-4963-b44b-1d635a0360b6', '長安送友人之黔南', '长安送友人之黔南', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["衡嶽猶云過，君家獨幾千。","心從賤遊話，分向禁城偏。","陸路終何處，三湘在素船。","琴書去迢遞，星路照潺湲。","臺鏡簪秋晚，盤蔬飯雨天。","同文到鄉盡，殊國共行連。","後會應多日，歸程自一年。","貧交永無忘，孤進合相憐。"]', '["衡嶽猶云過，君家独幾千。","心從賤游話，分向禁城偏。","陸路終何处，三湘在素船。","琴书去迢遞，星路照潺湲。","台镜簪秋晚，盤蔬飯雨天。","同文到乡尽，殊国共行連。","後會應多日，归程自一年。","貧交永無忘，孤進合相怜。"]', '诗', 'shi', '', NULL, '長安送友人之黔南 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42d33d46-a704-4d7c-88d5-000a73d92394', '寄李頻', '寄李頻', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["長安千萬蹊，迷者自多迷。","直性身難達，良時日易低。","環簷消舊雪，晴氣滿春泥。","那得同君去，逢峰苦愛齊。"]', '["长安千万蹊，迷者自多迷。","直性身难達，良时日易低。","环簷消旧雪，晴氣满春泥。","那得同君去，逢峰苦愛齊。"]', '诗', 'shi', '', NULL, '寄李頻 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa9905e-5a6e-47aa-8af3-3f3db6afc434', '贈苗端公二首 一', '贈苗端公二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["繁總近何如，君才必有餘。","身歡步兵酒，吏寫魯連書。","坐默聞鼙吹，庭班見雪初。","沈碑若果去，一爲訪鄰居。"]', '["繁總近何如，君才必有餘。","身歡步兵酒，吏寫魯連书。","坐默闻鼙吹，庭班见雪初。","沈碑若果去，一爲訪鄰居。"]', '诗', 'shi', '', NULL, '贈苗端公二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f41380a-9669-46ec-b4f6-d4354ed6670e', '贈苗端公二首 二', '贈苗端公二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["至老不相疎，斯言不是虛。","兩心宜一體，同舍又鄰居。","曉角秋砧外，清雲白月初。","從軍何有用，未造魯連書。"]', '["至老不相疎，斯言不是虛。","兩心宜一體，同舍又鄰居。","晓角秋砧外，清云白月初。","從軍何有用，未造魯連书。"]', '诗', 'shi', '', NULL, '贈苗端公二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54aa96cd-630d-47cb-bdbb-911e31440a4d', '寄河南鄭侍郎', '寄河南鄭侍郎', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["三峽與三壕，門闌夢去勞。","細冰和洛水，初雪灑嵩高。","大雅何由接，微榮亦已逃。","寒窗不可寐，風地葉蕭騷。"]', '["三峽與三壕，门闌梦去勞。","細冰和洛水，初雪灑嵩高。","大雅何由接，微榮亦已逃。","寒窗不可寐，风地葉蕭騷。"]', '诗', 'shi', '', NULL, '寄河南鄭侍郎 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b057e18b-4184-43ee-9814-1fc18d2a09be', '蒙恩除侍御史行次華州寄蔣相', '蒙恩除侍御史行次华州寄蔣相', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["林下天書起遁逃，不堪移疾入塵勞。","黃河近岸陰風急，仙掌臨關旭日高。","行野衆喧聞鴈發，宿亭孤寂有狼嗥。","荀家位極兼禪理，應笑埋輪著所操。"]', '["林下天书起遁逃，不堪移疾入塵勞。","黄河近岸陰风急，仙掌臨关旭日高。","行野衆喧闻鴈發，宿亭孤寂有狼嗥。","荀家位極兼禪理，應笑埋輪著所操。"]', '诗', 'shi', '', NULL, '蒙恩除侍御史行次華州寄蔣相 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8831d0aa-6ec8-4978-8ca1-432b1e2d78dc', '寄唐州楊郎中', '寄唐州楊郎中', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["關雎憔悴一儒生，忽把魚鬚事聖明。","貧得俸錢還乍喜，晚登朝序却無榮。","前年坐蜀同樽俎，此日邊淮獨斾旌。","班列道孤君不見，曲江春暖共僧行。"]', '["关雎憔悴一儒生，忽把鱼鬚事聖明。","貧得俸錢還乍喜，晚登朝序却無榮。","前年坐蜀同樽俎，此日邊淮独斾旌。","班列道孤君不见，曲江春暖共僧行。"]', '诗', 'shi', '', NULL, '寄唐州楊郎中 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a04eb76-4382-4fef-aa8c-d2e11838508d', '塞上蒙汝州任中丞寄書', '塞上蒙汝州任中丞寄书', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["三省推賢兩掖才，關東深許稍遲迴。","舟浮汝水通淮去，雨出嵩峰到郡來。","投札轉京憂不遠，枉緘經虜喜初開。","西樓一望知無極，更與何人把酒桮。"]', '["三省推賢兩掖才，关东深許稍遲迴。","舟浮汝水通淮去，雨出嵩峰到郡来。","投札轉京憂不远，枉緘經虜喜初开。","西楼一望知無極，更與何人把酒桮。"]', '诗', 'shi', '', NULL, '塞上蒙汝州任中丞寄書 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b4ef7a-82b0-4b0f-b78b-8e0ee033063d', '題鹽鐵李尚書滻州別業', '題鹽鐵李尚书滻州別業', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["鹿原陰面滻州湄，坐覺林泉逼夢思。","閑景院開花落後，濕香風好雨來時。","鄰驚麥野聞雛雉，別創茅亭住老師。","備足好中還有闕，許昌軍裏李陵詩。"]', '["鹿原陰面滻州湄，坐覺林泉逼梦思。","闲景院开花落後，濕香风好雨来时。","鄰驚麦野闻雛雉，別創茅亭住老師。","備足好中還有闕，許昌軍裏李陵诗。"]', '诗', 'shi', '', NULL, '題鹽鐵李尚書滻州別業 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c1c091-3fa2-4da4-867f-8e64d2d3bb23', '送劉駕歸京', '送劉駕归京', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["相逢聽一吟，惟我不降心。","在世憂何事，前生得至音。","蒲多南去遠，汾盡北遊深。","爲宿關亭日，蒼蒼曉欲臨。"]', '["相逢听一吟，惟我不降心。","在世憂何事，前生得至音。","蒲多南去远，汾尽北游深。","爲宿关亭日，蒼蒼晓欲臨。"]', '诗', 'shi', '', NULL, '送劉駕歸京 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051c3033-e855-4c08-b186-0320b54b32d1', '夏日寺中有懷', '夏日寺中有懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["亭午四鄰睡，院中唯鳥鳴。","當門塞鴻去，欹枕世人情。","地燥蒼苔裂，天涼晚月生。","歸家豈不願，辛苦未知名。"]', '["亭午四鄰睡，院中唯鸟鳴。","當门塞鴻去，欹枕世人情。","地燥蒼苔裂，天涼晚月生。","归家豈不願，辛苦未知名。"]', '诗', 'shi', '', NULL, '夏日寺中有懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c4e72f-862d-4550-b42e-483f9e217c9c', '夏日蒲津寺居二首 一', '夏日蒲津寺居二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["日日閑車馬，誰來訪此身。","一門兼鶴靜，四院與僧鄰。","雨室牆穿溜，風窗筆染塵。","空餘氣長在，天子用平人。"]', '["日日闲车马，誰来訪此身。","一门兼鹤静，四院與僧鄰。","雨室牆穿溜，风窗笔染塵。","空餘氣长在，天子用平人。"]', '诗', 'shi', '', NULL, '夏日蒲津寺居二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90fd3ab-601b-4e1a-b29f-25604787a265', '夏日蒲津寺居二首 二', '夏日蒲津寺居二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["故國有如夢，省來長遠遊。","清晨起閑院，疎雨似深秋。","宿寢書稜疊，行吟杖跡稠。","天晴豈能出，春暖未更裘。"]', '["故国有如梦，省来长远游。","清晨起闲院，疎雨似深秋。","宿寢书稜叠，行吟杖跡稠。","天晴豈能出，春暖未更裘。"]', '诗', 'shi', '', NULL, '夏日蒲津寺居二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cdc4b09-0392-4b11-8180-1679c517cb75', '北都題崇福寺', '北都題崇福寺', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["此地潛龍寺，何基即帝臺。","細花庭樹蔭，清氣殿門開。","長老多相識，旬休暫一來。","空空亦擬解，干進幸無媒。"]', '["此地潛龙寺，何基即帝台。","細花庭樹蔭，清氣殿门开。","长老多相識，旬休暫一来。","空空亦擬解，干進幸無媒。"]', '诗', 'shi', '', NULL, '北都題崇福寺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9489529-9285-4797-b41e-be5b13788c22', '題龍興寺', '題龙兴寺', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["高戶列禪房，松門到上方。","像開祇樹嶺，人施蜀城香。","地遍磷磷石，江移孑孑檣。","林僧語不盡，身役事梁王。"]', '["高戶列禪房，松门到上方。","像开祇樹嶺，人施蜀城香。","地遍磷磷石，江移孑孑檣。","林僧語不尽，身役事梁王。"]', '诗', 'shi', '', NULL, '題龍興寺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9138bf74-5a90-4b43-b30f-4150cc9158fc', '題大雲寺西閣', '題大云寺西閣', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["閣臨偏險寺當山，獨坐西城笑滿顏。","四野有歌行路樂，五營無戰射堂閑。","鼙和調角秋空外，砧辦征衣落照間。","方擬殺身酬聖主，敢於高處戀鄉關。"]', '["閣臨偏險寺當山，独坐西城笑满顏。","四野有歌行路乐，五營無戰射堂闲。","鼙和調角秋空外，砧辦征衣落照间。","方擬殺身酬聖主，敢於高处戀乡关。"]', '诗', 'shi', '', NULL, '題大雲寺西閣 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f55264b-06f6-46b2-a56e-c9e7b831ef53', '舟行至平羌', '舟行至平羌', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["貔虎直沙壖，嚴更護早眠。","簇霜孤驛樹，落日下江船。","暫去非吳起，終休愛魯連。","平羌無一術，候吏莫加籩。"]', '["貔虎直沙壖，嚴更護早眠。","簇霜孤驛樹，落日下江船。","暫去非吳起，終休愛魯連。","平羌無一術，候吏莫加籩。"]', '诗', 'shi', '', NULL, '舟行至平羌 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b4b678-ca99-4bcc-a233-823edcf10281', '題開元寺閣', '題开元寺閣', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一閣見一郡，亂流仍亂山。","未能終日住，尤愛暫時閑。","唱棹吳門去，啼林杜宇還。","高僧不可羨，西景掩禪關。"]', '["一閣见一郡，亂流仍亂山。","未能終日住，尤愛暫时闲。","唱棹吳门去，啼林杜宇還。","高僧不可羨，西景掩禪关。"]', '诗', 'shi', '', NULL, '題開元寺閣 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f948988-6a95-4aa2-9cb7-434a69325507', '凌雲寺', '凌云寺', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["像閣與山齊，何人致石梯。","萬煙生聚落，一崦露招提。","齋月人來上，殘陽鴿去栖。","從邊亦已極，烽火是沈黎。"]', '["像閣與山齊，何人致石梯。","万煙生聚落，一崦露招提。","斋月人来上，殘陽鴿去栖。","從邊亦已極，烽火是沈黎。"]', '诗', 'shi', '', NULL, '凌雲寺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f05db6-01db-4cd1-8d32-7c6e7756cb5f', '石堂溪', '石堂溪', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["三面接漁樵，前門向郡橋。","岸沙崩橘樹，山徑入茶苗。","夜擁軍煙合，春浮妓舸邀。","此心無與醉，花影莫相燒。"]', '["三面接漁樵，前门向郡橋。","岸沙崩橘樹，山徑入茶苗。","夜擁軍煙合，春浮妓舸邀。","此心無與醉，花影莫相燒。"]', '诗', 'shi', '', NULL, '石堂溪 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af091f2d-1eb6-4b68-b180-7aa8cfbae23d', '荔枝樓', '荔枝楼', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["高檻起邊愁，荔枝誰致樓。","會須敎匠坼，不欲見蠻陬。","樹痺無春影，天連覺漢流。","仲宣如可擬，即此是荆州。"]', '["高檻起邊愁，荔枝誰致楼。","會須敎匠坼，不欲见蠻陬。","樹痺無春影，天連覺漢流。","仲宣如可擬，即此是荆州。"]', '诗', 'shi', '', NULL, '荔枝樓 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b936ba-6466-47fc-81c4-c18a5ddf1689', '聖岡', '聖岡', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["古跡是何王，平身入石房。","遠村通後徑，一郡隔前岡。","晝靜唯禪客，春來有女郎。","獨醒迴不得，無事可焚香。"]', '["古跡是何王，平身入石房。","远村通後徑，一郡隔前岡。","晝静唯禪客，春来有女郎。","独醒迴不得，無事可焚香。"]', '诗', 'shi', '', NULL, '聖岡 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc856e6-09cc-44bf-a4ad-b5badbc57951', '蜀州鄭史君寄鳥觜茶因以贈答八韻', '蜀州鄭史君寄鸟觜茶因以贈答八韻', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["鳥觜擷渾牙，精靈勝鏌鋣。","烹嘗方帶酒，滋味更無茶。","拒碾乾聲細，撐封利穎斜。","銜蘆齊勁實，啄木聚菁華。","鹽損添常誡，薑宜著更誇。","得來拋道藥，攜去就僧家。","旋覺前甌淺，還愁後信賒。","千慙故人意，此惠敵丹砂。"]', '["鸟觜擷渾牙，精靈勝鏌鋣。","烹嘗方带酒，滋味更無茶。","拒碾乾声細，撐封利穎斜。","銜蘆齊勁實，啄木聚菁华。","鹽損添常誡，薑宜著更誇。","得来拋道藥，携去就僧家。","旋覺前甌淺，還愁後信賒。","千慙故人意，此惠敵丹砂。"]', '诗', 'shi', '', NULL, '蜀州鄭史君寄鳥觜茶因以贈答八韻 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683e07bf-a042-480f-91d7-f543f64c8ef5', '暇日寓懷寄朝中親友', '暇日寓懷寄朝中親友', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["命與才違豈自由，我身何負我身愁。","臨生白髮方監郡，遙恥青衣懶上樓。","過客悶嫌疎妓樂，小兒憨愛□貔貅。","閑吟一寄清朝侶，未必淮陰不拜侯。"]', '["命與才違豈自由，我身何負我身愁。","臨生白髮方監郡，遙恥青衣懶上楼。","過客悶嫌疎妓乐，小兒憨愛□貔貅。","闲吟一寄清朝侶，未必淮陰不拜侯。"]', '诗', 'shi', '', NULL, '暇日寓懷寄朝中親友 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc2fc24-1296-4591-9cc4-7833dd8ab162', '春日寓懷', '春日寓懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["幽拙未謀身，無端患不均。","盜憎猶念物，花盡不知春。","井邑常多弊，江山豈有神。","犍爲何處在，一擬弔埋輪。"]', '["幽拙未謀身，無端患不均。","盜憎猶念物，花尽不知春。","井邑常多弊，江山豈有神。","犍爲何处在，一擬弔埋輪。"]', '诗', 'shi', '', NULL, '春日寓懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e315b847-2750-4f01-b3aa-160d02357ccf', '監郡犍爲舟中寓題寄同舍', '監郡犍爲舟中寓題寄同舍', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一寢閑身萬事空，任天敎作假文翁。","旗穿島樹孤舟上，家在山亭每日中。","疊果盤飱丹橘地，若花牀席早梅風。","佳期說盡君應笑，劉表尊前且不同。"]', '["一寢闲身万事空，任天敎作假文翁。","旗穿島樹孤舟上，家在山亭每日中。","叠果盤飱丹橘地，若花牀席早梅风。","佳期说尽君應笑，劉表尊前且不同。"]', '诗', 'shi', '', NULL, '監郡犍爲舟中寓題寄同舍 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d503b6-2234-45e1-9b70-8ef2f5411c94', '江柳', '江柳', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["條綠似垂纓，離筵日照輕。","向人雖有態，傷我爲無情。","橋遠孤臨水，牆低半出營。","天津曾此見，亦是愴行行。"]', '["條綠似垂纓，離筵日照轻。","向人雖有態，傷我爲無情。","橋远孤臨水，牆低半出營。","天津曾此见，亦是愴行行。"]', '诗', 'shi', '', NULL, '江柳 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be3a317-bca8-4718-8c4d-35305b9e7be2', '寄吉諫議', '寄吉諫議', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["將迎須學返抽身，合致蹉跎敢效顰。","性靜擬歸無上士，跡疎常負有情人。","終憑二頃謀婚嫁，謬著千篇斷斧斤。","聞說舊交賢且達，欲彈章甫自羞貧。"]', '["將迎須学返抽身，合致蹉跎敢效顰。","性静擬归無上士，跡疎常負有情人。","終憑二頃謀婚嫁，謬著千篇斷斧斤。","闻说旧交賢且達，欲彈章甫自羞貧。"]', '诗', 'shi', '', NULL, '寄吉諫議 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb744f11-b175-4dc8-b15c-af9acc547003', '江上寄情', '江上寄情', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["天際歸舟浩蕩中，我關王澤道何窮。","未爲時彥徒經國，尚有邊兵恥佐戎。","釀黍氣香村欲社，斫桑春盡野無風。","年來斷定知休處，一樹繁花一畝宮。"]', '["天際归舟浩蕩中，我关王澤道何窮。","未爲时彥徒經国，尚有邊兵恥佐戎。","釀黍氣香村欲社，斫桑春尽野無风。","年来斷定知休处，一樹繁花一畝宮。"]', '诗', 'shi', '', NULL, '江上寄情 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b5ab74-51d6-4651-8c3e-6b4a59b7943d', '平蓋觀', '平蓋观', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["巨柏與山高，玄門靜有猱。","春風開野杏，落日照江濤。","白璧心難說，青雲世未遭。","天涯望不極，誰識詠離騷。"]', '["巨柏與山高，玄门静有猱。","春风开野杏，落日照江濤。","白璧心难说，青云世未遭。","天涯望不極，誰識詠離騷。"]', '诗', 'shi', '', NULL, '平蓋觀 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa762606-0c71-442c-8916-f7585f53eaba', '春霽', '春霽', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["久客孤舟上，天涯漱曉津。","野芳榿似柳，江霽雪和春。","吏叫能驚鷺，官麤實害身。","何當窮蜀境，却憶滯遊人。"]', '["久客孤舟上，天涯漱晓津。","野芳榿似柳，江霽雪和春。","吏叫能驚鷺，官麤實害身。","何當窮蜀境，却憶滯游人。"]', '诗', 'shi', '', NULL, '春霽 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a575f90-37ef-4b5e-82ac-32665a01a5d9', '春居即事', '春居即事', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["雲密露晨暉，西園獨掩扉。","雨新臨斷火，春冷著單衣。","榆莢奔風健，蘭芽負土肥。","交親不是變，自作寄書稀。"]', '["云密露晨暉，西园独掩扉。","雨新臨斷火，春冷著單衣。","榆莢奔风健，蘭芽負土肥。","交親不是变，自作寄书稀。"]', '诗', 'shi', '', NULL, '春居即事 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353d1f85-0c72-41dc-a327-0204ba52610a', '邊城寓題', '邊城寓題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["孤蹇復飄零，天涯若墮螢。","東風吹痼疾，暖日極青冥。","蠶市歸農醉，漁舟釣客醒。","論邦苦不早，祗此負王庭。"]', '["孤蹇复飄零，天涯若墮螢。","东风吹痼疾，暖日極青冥。","蠶市归農醉，漁舟釣客醒。","論邦苦不早，祗此負王庭。"]', '诗', 'shi', '', NULL, '邊城寓題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f2fc5d-df4f-4a39-b5f6-27ce0825ea79', '春日江居寓懷', '春日江居寓懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["歸興乍離邊，蘭橈復錦川。","斫春槎枿樹，消雪土膏田。","岸暖尋新菜，舟寒著舊綿。","臨邛若箇是，欲向酒家眠。"]', '["归兴乍離邊，蘭橈复錦川。","斫春槎枿樹，消雪土膏田。","岸暖尋新菜，舟寒著旧綿。","臨邛若箇是，欲向酒家眠。"]', '诗', 'shi', '', NULL, '春日江居寓懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9dd550-e50c-43b1-9132-b95191cce9fa', '邊城作', '邊城作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["行止象分符，監州是戲儒。","管排蠻戶遠，出箐鳥巢孤。","北向秦何在，南來蜀已無。","懷沙悔不及，只有便乘桴。"]', '["行止象分符，監州是戲儒。","管排蠻戶远，出箐鸟巢孤。","北向秦何在，南来蜀已無。","懷沙悔不及，只有便乘桴。"]', '诗', 'shi', '', NULL, '邊城作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4695c33-7724-4958-9442-de565b98eda7', '聞李夷遇下第東歸因以寄贈', '闻李夷遇下第东归因以寄贈', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["囊中書是居山寫，海畔家貧乞食還。","吾子莫愁登第晚，古人惟愛賤遊閑。","舟行散適江亭上，郡宴歌吟蠟燭間。","從此樂章休敘戰，漢兵無陣亦無蠻。"]', '["囊中书是居山寫，海畔家貧乞食還。","吾子莫愁登第晚，古人惟愛賤游闲。","舟行散適江亭上，郡宴歌吟蠟燭间。","從此乐章休敘戰，漢兵無陣亦無蠻。"]', '诗', 'shi', '', NULL, '聞李夷遇下第東歸因以寄贈 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c61f91-42b2-4604-9209-f779f63af881', '留題', '留題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["茶興復詩心，一甌還一吟。","壓春甘蔗冷，喧雨荔枝深。","驟去無遺恨，幽棲已徧尋。","峨眉不可到，高處望千岑。"]', '["茶兴复诗心，一甌還一吟。","壓春甘蔗冷，喧雨荔枝深。","驟去無遺恨，幽棲已徧尋。","峨眉不可到，高处望千岑。"]', '诗', 'shi', '', NULL, '留題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78a6ae1-1875-4239-8bd1-52955b515db5', '春日北歸舟中有懷', '春日北归舟中有懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["盡日遶盤飧，歸舟向蜀門。","雨乾楊柳渡，山熱杏花村。","淨鏡空山曉，孤燈極浦昏。","邊城不是意，迴首未終恩。"]', '["尽日遶盤飧，归舟向蜀门。","雨乾楊柳渡，山熱杏花村。","淨镜空山晓，孤灯極浦昏。","邊城不是意，迴首未終恩。"]', '诗', 'shi', '', NULL, '春日北歸舟中有懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2c90b9-b679-4c61-8879-b1c2fa0487e0', '初發嘉州寓題', '初發嘉州寓題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["勞我是犍爲，南征又北移。","唯聞杜鵑夜，不見海棠時。","在闇曾無負，含靈合有知。","州人若愛樹，莫損召南詩。"]', '["勞我是犍爲，南征又北移。","唯闻杜鵑夜，不见海棠时。","在闇曾無負，含靈合有知。","州人若愛樹，莫損召南诗。"]', '诗', 'shi', '', NULL, '初發嘉州寓題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc602fe2-1cc5-4eb6-a67e-8dc478e1579c', '題漢州西湖', '題漢州西湖', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["西湖天下名，可以濯吾纓。","況是攜家賞，從妨半驛程。","嘗茶春味渴，斷酒晚懷清。","盡得幽人趣，猶嫌守吏迎。","重湌逢角暮，百事喜詩成。","坐阻湘江謫，誰爲話政聲。"]', '["西湖天下名，可以濯吾纓。","況是携家賞，從妨半驛程。","嘗茶春味渴，斷酒晚懷清。","尽得幽人趣，猶嫌守吏迎。","重湌逢角暮，百事喜诗成。","坐阻湘江謫，誰爲話政声。"]', '诗', 'shi', '', NULL, '題漢州西湖 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c5f343-c4d2-4442-80f3-b2b68b9913af', '自廣漢遊三學山', '自廣漢游三学山', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["殘陽終日望棲賢，歸路攜家得訪禪。","世缺一來應薄命，雨留三宿是前緣。","詩題不忍離巖下，屐齒難忘在水邊。","猨鳥可知僧可會，此心常似有香煙。"]', '["殘陽終日望棲賢，归路携家得訪禪。","世缺一来應薄命，雨留三宿是前緣。","诗題不忍離巖下，屐齒难忘在水邊。","猨鸟可知僧可會，此心常似有香煙。"]', '诗', 'shi', '', NULL, '自廣漢遊三學山 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57672af9-a6c0-42ea-8469-3889d698a0db', '三學山開照寺', '三学山开照寺', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["盡室徧相將，中方上下方。","夜深楠樹遠，春氣陌林香。","聖跡留巖險，靈燈出混茫。","何因將慧劒，割愛事空王。"]', '["尽室徧相將，中方上下方。","夜深楠樹远，春氣陌林香。","聖跡留巖險，靈灯出混茫。","何因將慧劒，割愛事空王。"]', '诗', 'shi', '', NULL, '三學山開照寺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa58b39f-33a7-4591-ac25-d0f8319102ef', '雨霽北歸留題三學山', '雨霽北归留題三学山', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["遠樹平川半夕陽，錦城遙辨立危牆。","閑思勝事多遺恨，却悔公心是謾忙。","灌口闕尋慙遠客，峨嵋乖約負支郎。","靈龕一望終何得，謬有人情滿蜀鄉。"]', '["远樹平川半夕陽，錦城遙辨立危牆。","闲思勝事多遺恨，却悔公心是謾忙。","灌口闕尋慙远客，峨嵋乖約負支郎。","靈龕一望終何得，謬有人情满蜀乡。"]', '诗', 'shi', '', NULL, '雨霽北歸留題三學山 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b1a43e-e8ad-47f6-bc0d-c710eb2410d0', '行次靈龕驛寄西蜀尚書', '行次靈龕驛寄西蜀尚书', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["北客推車指蜀門，乾陽知已近臨坤。","從辭府郭常迴首，欲別封疆更感恩。","援寡聖朝難望闕，暑催蠶麥得歸村。","雷公解斸衝天氣，白日何辜遣戴盆。"]', '["北客推车指蜀门，乾陽知已近臨坤。","從辞府郭常迴首，欲別封疆更感恩。","援寡聖朝难望闕，暑催蠶麦得归村。","雷公解斸衝天氣，白日何辜遣戴盆。"]', '诗', 'shi', '', NULL, '行次靈龕驛寄西蜀尚書 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b66e3627-9533-4d55-b4c9-95a06579acf7', '雨霽宿望喜驛', '雨霽宿望喜驛', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["風雷一罷思何清，江水依然浩浩聲。","飛鳥旋生啼鳥在，後人常似古人情。","將來道路終須達，過去山川實不平。","閑想更逢知舊否，館前楊柳種初成。"]', '["风雷一罷思何清，江水依然浩浩声。","飞鸟旋生啼鸟在，後人常似古人情。","將来道路終須達，過去山川實不平。","闲想更逢知旧否，館前楊柳種初成。"]', '诗', 'shi', '', NULL, '雨霽宿望喜驛 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f463bd2-2250-4f2d-a391-78d236e1f695', '籌筆驛', '籌笔驛', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["葛相終宜馬革還，未開天意便開山。","生欺仲達徒增氣，死見王陽合厚顏。","流運有功終是擾，陰符多術得非姦。"]', '["葛相終宜马革還，未开天意便开山。","生欺仲達徒增氣，死见王陽合厚顏。","流運有功終是擾，陰符多術得非姦。"]', '诗', 'shi', '', NULL, '籌筆驛 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f03d99f-bc1b-4cb6-a35e-4cd056ec196f', '通仙洞', '通仙洞', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["高龕險欲催，百尺洞門開。","白日仙何在，清風客暫來。","臨崖松直上，避石水低迴。","賈掾曾空去，題詩豈易哉。"]', '["高龕險欲催，百尺洞门开。","白日仙何在，清风客暫来。","臨崖松直上，避石水低迴。","賈掾曾空去，題诗豈易哉。"]', '诗', 'shi', '', NULL, '通仙洞 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ffb77b-3a99-499f-a31d-d5f1d07c16b5', '嘉陵驛見賈島舊題', '嘉陵驛见賈島旧題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["賈子命堪悲，唐人獨解詩。","左遷今已矣，清絕更無之。","畢竟吾猶許，商量衆莫疑。","嘉陵四十字，一一是天資。"]', '["賈子命堪悲，唐人独解诗。","左遷今已矣，清絕更無之。","畢竟吾猶許，商量衆莫疑。","嘉陵四十字，一一是天資。"]', '诗', 'shi', '', NULL, '嘉陵驛見賈島舊題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f70ba0-ebf2-4bf2-af45-b8d1e208103a', '嘉陵驛', '嘉陵驛', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["江濤千疊閣千層，銜尾相隨盡室登。","稠樹蔽山聞杜宇，午煙薰日食嘉陵。","頻題石上程多破，暫歇泉邊起不能。","如此幸非名利切，益州來日合攜僧。"]', '["江濤千叠閣千層，銜尾相隨尽室登。","稠樹蔽山闻杜宇，午煙薰日食嘉陵。","頻題石上程多破，暫歇泉邊起不能。","如此幸非名利切，益州来日合携僧。"]', '诗', 'shi', '', NULL, '嘉陵驛 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ee60b9-b4c4-4b73-b2ce-9ecaaf9807ef', '嘉陵驛', '嘉陵驛', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["盡室可招魂，蠻餘出蜀門。","雹涼隨雨氣，江熱傍山根。","蠶月繰絲路，農時碌碡村。","干將磨欲盡，無位可酬恩。"]', '["尽室可招魂，蠻餘出蜀门。","雹涼隨雨氣，江熱傍山根。","蠶月繰絲路，農时碌碡村。","干將磨欲尽，無位可酬恩。"]', '诗', 'shi', '', NULL, '嘉陵驛 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc618ba9-e099-45bf-9834-91a7e6a2faa8', '西縣途中二十韻', '西縣途中二十韻', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["野客誤桑麻，從軍帶鏌鋣。","豈論之白帝，未合過黃花。","落日投江縣，征塵漱齒牙。","蜀音連井絡，秦分隔褒斜。","硤路商逢使，山郵雀啅蛇。","憶歸臨角黍，良遇得新瓜。","食久庭陰轉，行多屐齒窪。","氣清巖下瀑，煙漫雨餘畬。","黃鳥當蠶候，稀蒿雜麥查。","汗涼風似雪，漿度蜜如沙。","野色生肥芋，鄉儀擣散茶。","梯航經杜宇，烽候徹苴咩。","逗石流何險，通關運固賒。","葛侯真竭澤，劉主合亡家。","陷彼貪功吠，貽爲黷武誇。","陣圖誰許可，廟貌我揄揶。","閑事休徵漢，斯行且詠巴。","音繁來有鐸，軏盡去無車。","溢目看風景，清懷嘯月華。","焰樵烹紫筍，腰簟憩烏紗。","杞國憂尋悟，臨邛渴自加。","移文莫有誚，必不滯天涯。"]', '["野客誤桑麻，從軍带鏌鋣。","豈論之白帝，未合過黄花。","落日投江縣，征塵漱齒牙。","蜀音連井絡，秦分隔褒斜。","硤路商逢使，山郵雀啅蛇。","憶归臨角黍，良遇得新瓜。","食久庭陰轉，行多屐齒窪。","氣清巖下瀑，煙漫雨餘畬。","黄鸟當蠶候，稀蒿杂麦查。","汗涼风似雪，漿度蜜如沙。","野色生肥芋，乡儀擣散茶。","梯航經杜宇，烽候徹苴咩。","逗石流何險，通关運固賒。","葛侯真竭澤，劉主合亡家。","陷彼貪功吠，貽爲黷武誇。","陣圖誰許可，廟貌我揄揶。","闲事休徵漢，斯行且詠巴。","音繁来有鐸，軏尽去無车。","溢目看风景，清懷嘯月华。","焰樵烹紫筍，腰簟憩烏紗。","杞国憂尋悟，臨邛渴自加。","移文莫有誚，必不滯天涯。"]', '诗', 'shi', '', NULL, '西縣途中二十韻 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20cf0cd4-1732-4be3-90c2-33f34096f514', '西縣作', '西縣作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["三年西蜀去如沈，西縣西來出萬岑。","樹石向聞清漢浪，水風初見綠萍陰。","平郊不愛行增氣，好井無疑漱入心。","從此漸知光景異，錦都廻首盡愁吟。"]', '["三年西蜀去如沈，西縣西来出万岑。","樹石向闻清漢浪，水风初见綠萍陰。","平郊不愛行增氣，好井無疑漱入心。","從此漸知光景異，錦都廻首尽愁吟。"]', '诗', 'shi', '', NULL, '西縣作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f3f685-cb25-42a9-a94c-4fdf6e59194d', '分水嶺望靈寶峰', '分水嶺望靈寶峰', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["千尋萬仞峰，靈寶號何從。","盛立同吾道，貪程阻聖蹤。","嶺奇應有藥，壁峭盡無松。","那得休于是，蹉跎亦臥龍。"]', '["千尋万仞峰，靈寶號何從。","盛立同吾道，貪程阻聖蹤。","嶺奇應有藥，壁峭尽無松。","那得休于是，蹉跎亦臥龙。"]', '诗', 'shi', '', NULL, '分水嶺望靈寶峰 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed14233-782c-4837-9c21-d6b8de27518b', '水簾吟', '水簾吟', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["萬滴相隨萬響兼，路塵天產盡旁霑。","源從顥氣何因絕，派助前溪豈覺添。","豪客每來清夏葛，愁人才見認愁簷。","嘉名已極終難稱，別是風流不是簾。"]', '["万滴相隨万响兼，路塵天產尽旁霑。","源從顥氣何因絕，派助前溪豈覺添。","豪客每来清夏葛，愁人才见認愁簷。","嘉名已極終难稱，別是风流不是簾。"]', '诗', 'shi', '', NULL, '水簾吟 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476a7515-beaf-48c6-9ac7-30a806289b97', '褒斜道中', '褒斜道中', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["十驛褒斜到處慵，眼前常似接靈蹤。","江遙旋入旁來水，山豁猶藏向後峰。","鳥徑惡時應立虎，畬田閑日自燒松。","行吟却笑公車役，夜發星馳半不逢。"]', '["十驛褒斜到处慵，眼前常似接靈蹤。","江遙旋入旁来水，山豁猶藏向後峰。","鸟徑惡时應立虎，畬田闲日自燒松。","行吟却笑公车役，夜發星驰半不逢。"]', '诗', 'shi', '', NULL, '褒斜道中 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a1456fc-1458-4bc8-b1ec-95a010d93b81', '褒城驛有故元相公舊題詩因仰歎而作', '褒城驛有故元相公旧題诗因仰歎而作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["鄂相頃題應好池，題云萬竹與千棃。","我來已變當初地，前過應無繼此詩。","敢歎臨行殊舊境，惟愁後事劣今時。","閑吟四壁堪搔首，頻見青蘋白鷺鷥。"]', '["鄂相頃題應好池，題云万竹與千棃。","我来已变當初地，前過應無繼此诗。","敢歎臨行殊旧境，惟愁後事劣今时。","闲吟四壁堪搔首，頻见青蘋白鷺鷥。"]', '诗', 'shi', '', NULL, '褒城驛有故元相公舊題詩因仰歎而作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73d28ef-9d03-43ac-a2a9-18f7efe55726', '題褒城驛池', '題褒城驛池', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["池館通秦檻向衢，舊聞佳賞此踟躕。","清涼不散亭猶在，事力何銷舫已無。","釣客坐風臨島嶼，牧牛當雨食菰蒲。","西川吟吏偏思葺，只恐歸尋水亦枯。"]', '["池館通秦檻向衢，旧闻佳賞此踟躕。","清涼不散亭猶在，事力何銷舫已無。","釣客坐风臨島嶼，牧牛當雨食菰蒲。","西川吟吏偏思葺，只恐归尋水亦枯。"]', '诗', 'shi', '', NULL, '題褒城驛池 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('631c54d9-ed1d-4e96-8394-021ab805c0d1', '送崔學士赴東川', '送崔学士赴东川', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["羽人仙籍冠浮丘，欲作酇侯且蜀侯。","導騎已多行劒閣，親軍全到近綿州。","文翁勸學人應戀，魏絳和戎戍自休。","唯有夜罇懽莫厭，廟堂他日少閑遊。"]', '["羽人仙籍冠浮丘，欲作酇侯且蜀侯。","導騎已多行劒閣，親軍全到近綿州。","文翁勸学人應戀，魏絳和戎戍自休。","唯有夜罇懽莫厭，廟堂他日少闲游。"]', '诗', 'shi', '', NULL, '送崔學士赴東川 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('999dd198-0503-496e-9a0a-2a0f4414584d', '海棠', '海棠', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["酷烈復離披，玄功莫我知。","青苔浮落處，暮柳間開時。","帶醉遊人插，連陰被叟移。","晨前清露濕，晏後惡風吹。","香少傳何許，妍多畫半遺。","島蘇漣水脉，庭綻粒松枝。","偶汎因沈硯，閑飄欲亂碁。","遶山生玉壘，和郡徧坤維。","負賞慙休飲，牽吟分失飢。","明年應不見，留此贈巴兒。"]', '["酷烈复離披，玄功莫我知。","青苔浮落处，暮柳间开时。","带醉游人插，連陰被叟移。","晨前清露濕，晏後惡风吹。","香少傳何許，妍多畫半遺。","島蘇漣水脉，庭綻粒松枝。","偶汎因沈硯，闲飄欲亂碁。","遶山生玉壘，和郡徧坤維。","負賞慙休饮，牽吟分失飢。","明年應不见，留此贈巴兒。"]', '诗', 'shi', '', NULL, '海棠 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918ace29-2ca6-4146-9993-0a9dac3f5835', '詠夾逕菊', '詠夾逕菊', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["夾逕盡黃英，不通人竝行。","幾曾相對綻，元自兩行生。","叢比高低等，香連左右幷。","畔搖風勢斷，中夾日華明。","間隔蛩吟隔，交橫蝶亂橫。","頻應泛桑落，摘處近前楹。"]', '["夾逕尽黄英，不通人竝行。","幾曾相对綻，元自兩行生。","叢比高低等，香連左右幷。","畔搖风勢斷，中夾日华明。","间隔蛩吟隔，交橫蝶亂橫。","頻應泛桑落，摘处近前楹。"]', '诗', 'shi', '', NULL, '詠夾逕菊 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f046f5b8-ac87-4fe5-8791-72a4c73cf0f0', '碧鮮亭春題竹', '碧鲜亭春題竹', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["竹少竹更重，碧鮮疆更名。","有欄常凭立，無徑獨穿行。","夕月陰何亂，春風葉盡輕。","已聞圖畫客，兼寫薛先生。"]', '["竹少竹更重，碧鲜疆更名。","有欄常凭立，無徑独穿行。","夕月陰何亂，春风葉尽轻。","已闻圖畫客，兼寫薛先生。"]', '诗', 'shi', '', NULL, '碧鮮亭春題竹 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ff6be6-3f77-4ab2-b666-4b148d1bae90', '竹逕', '竹逕', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["盤逕入依依，旋驚幽鳥飛。","尋多苔色古，踏碎籜聲微。","鞭節橫妨戶，枝梢動拂衣。","前溪聞到處，應接釣魚磯。"]', '["盤逕入依依，旋驚幽鸟飞。","尋多苔色古，踏碎籜声微。","鞭節橫妨戶，枝梢动拂衣。","前溪闻到处，應接釣鱼磯。"]', '诗', 'shi', '', NULL, '竹逕 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9458886b-b242-4dea-b299-6f435fa11ccb', '新柳', '新柳', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["輕輕須重不須輕，衆木難成獨早成。","柔性定勝剛性立，一枝還引萬枝生。","天鍾和氣元無力，時遇風光別有情。","誰道少逢知己用，將軍因此建雄名。"]', '["轻轻須重不須轻，衆木难成独早成。","柔性定勝剛性立，一枝還引万枝生。","天鍾和氣元無力，时遇风光別有情。","誰道少逢知己用，將軍因此建雄名。"]', '诗', 'shi', '', NULL, '新柳 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcbce961-5f45-4684-b8ec-c7ad497c1a13', '牡丹四首 一', '牡丹四首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["異色稟陶甄，常疑主者偏。","衆芳殊不類，一笑獨奢妍。","顆折羞含嬾，藂虛隱陷圓。","亞心堆勝被，美色豔於蓮。","品格如寒食，精光似少年。","種堪收子子，價合易賢賢。","迥秀應無妬，奇香稱有仙。","深陰宜映幕，富貴助開筵。","蜀水爭能染，巫山未可憐。","數難忘次第，立困戀傍邊。","逐日愁風雨，和星祝夜天。","且從留盡賞，離此便歸田。"]', '["異色稟陶甄，常疑主者偏。","衆芳殊不類，一笑独奢妍。","顆折羞含嬾，藂虛隐陷圓。","亞心堆勝被，美色豔於蓮。","品格如寒食，精光似少年。","種堪收子子，價合易賢賢。","迥秀應無妬，奇香稱有仙。","深陰宜映幕，富貴助开筵。","蜀水爭能染，巫山未可怜。","數难忘次第，立困戀傍邊。","逐日愁风雨，和星祝夜天。","且從留尽賞，離此便归田。"]', '诗', 'shi', '', NULL, '牡丹四首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f26f6d3-1404-40c9-8215-9a4658635435', '牡丹四首 二', '牡丹四首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["萬朵照初筵，狂遊憶少年。","曉光如曲水，顏色似西川。","白向庚辛受，朱從造化研。","衆開成伴侶，相笑極神仙。","見焰寧勞火，聞香不帶煙。","自高輕月桂，非偶賤池蓮。","影接彫盤動，藂遭惡草偏。","招歡憂事阻，就臥覺情牽。","四面宜綈錦，當頭稱管弦。","泊來鶯定憶，粉擾蝶何顛。","蘇息承朝露，滋榮仰霽天。","壓欄多盡好，敵國貴宜然。","未落須迷醉，因茲任病纏。","人誰知極物，空負感麟篇。"]', '["万朵照初筵，狂游憶少年。","晓光如曲水，顏色似西川。","白向庚辛受，朱從造化研。","衆开成伴侶，相笑極神仙。","见焰寧勞火，闻香不带煙。","自高轻月桂，非偶賤池蓮。","影接彫盤动，藂遭惡草偏。","招歡憂事阻，就臥覺情牽。","四面宜綈錦，當头稱管弦。","泊来鶯定憶，粉擾蝶何顛。","蘇息承朝露，滋榮仰霽天。","壓欄多尽好，敵国貴宜然。","未落須迷醉，因茲任病纏。","人誰知極物，空負感麟篇。"]', '诗', 'shi', '', NULL, '牡丹四首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5526e1-3419-41e3-8c98-824d05c344a3', '牡丹四首 三', '牡丹四首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["去年零落暮春時，淚濕紅牋怨別離。","常恐便隨巫峽散，何因重有武陵期。","傳情每向馨香得，不語還應彼此知。","欲就欄邊安枕席，夜深閑共說相思。"]', '["去年零落暮春时，泪濕紅牋怨別離。","常恐便隨巫峽散，何因重有武陵期。","傳情每向馨香得，不語還應彼此知。","欲就欄邊安枕席，夜深闲共说相思。"]', '诗', 'shi', '', NULL, '牡丹四首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f257cfa8-0bf5-4def-bcfe-3eb334896b72', '牡丹四首 四', '牡丹四首 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["牡丹愁爲牡丹飢，自惜多情欲瘦羸。","濃豔冷香初蓋後，好風乾雨正開時。","吟蜂遍坐無閑蘂，醉客曾偷有折枝。","京國別來誰占翫，此花光景屬吾詩。"]', '["牡丹愁爲牡丹飢，自惜多情欲瘦羸。","濃豔冷香初蓋後，好风乾雨正开时。","吟蜂遍坐無闲蘂，醉客曾偷有折枝。","京国別来誰占翫，此花光景屬吾诗。"]', '诗', 'shi', '', NULL, '牡丹四首 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d535dbb0-7b9e-4396-9d86-717098deeb18', '使院栽葦', '使院栽葦', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["戛戛復差差，一叢千萬枝。","格如僧住處，栽得吏閑時。","筍自廳中出，根從府外移。","從軍無宿例，空想夜風吹。"]', '["戛戛复差差，一叢千万枝。","格如僧住处，栽得吏闲时。","筍自廳中出，根從府外移。","從軍無宿例，空想夜风吹。"]', '诗', 'shi', '', NULL, '使院栽葦 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c3b1442-6043-4896-ba6f-507c542f6439', '失鶴二首 一', '失鹤二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["偶背雕籠與我違，四方端佇竟忘歸。","誰家白日雲間見，何處滄洲雨裏飛。","曾啄稻粱殘粒在，舊翹泥潦半蹤稀。","憑人轉覺多相誤，盡道皤然作令威。"]', '["偶背雕籠與我違，四方端佇竟忘归。","誰家白日云间见，何处滄洲雨裏飞。","曾啄稻粱殘粒在，旧翹泥潦半蹤稀。","憑人轉覺多相誤，尽道皤然作令威。"]', '诗', 'shi', '', NULL, '失鶴二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b98f192e-32d0-4201-98fa-9ffaed303fbd', '失鶴二首 二', '失鹤二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["華表翹風未可期，變丁投衛兩堪疑。","應緣失路防人損，空有歸心最我知。","但見空籠拋夕月，若何無樹宿荒陂。","不然直道高空外，白水青山屬臘師。"]', '["华表翹风未可期，变丁投衛兩堪疑。","應緣失路防人損，空有归心最我知。","但见空籠拋夕月，若何無樹宿荒陂。","不然直道高空外，白水青山屬臘師。"]', '诗', 'shi', '', NULL, '失鶴二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e4f87c-442b-461b-b1bd-94e569cd4748', '答賈支使寄鶴', '答賈支使寄鹤', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["瑞羽奇姿踉蹌形，稱爲仙馭過清冥。","何年厚祿曾居衛，幾世前身本姓丁。","幸有遠雲兼遠水，莫臨華表望華亭。","勞君贈我清歌侶，將去田園夜坐聽。"]', '["瑞羽奇姿踉蹌形，稱爲仙馭過清冥。","何年厚祿曾居衛，幾世前身本姓丁。","幸有远云兼远水，莫臨华表望华亭。","勞君贈我清歌侶，將去田园夜坐听。"]', '诗', 'shi', '', NULL, '答賈支使寄鶴 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5ae326-1ccf-458e-8787-8cb6bbdb8de3', '陳州刺史寄鶴', '陳州刺史寄鹤', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["臨風高視聳奇形，渡海沖天想盡經。","因得羽儀來合浦，便無魂夢去華亭。","春飛見境乘桴切，夜唳聞時醉枕醒。","南守欲知多少重，撫毛千萬喚丁丁。"]', '["臨风高視聳奇形，渡海沖天想尽經。","因得羽儀来合浦，便無魂梦去华亭。","春飞见境乘桴切，夜唳闻时醉枕醒。","南守欲知多少重，撫毛千万喚丁丁。"]', '诗', 'shi', '', NULL, '陳州刺史寄鶴 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad94711-e545-4a3b-822d-ced27a8cfc4c', '孔雀', '孔雀', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["偶有功名正俗才，靈禽何事降瑤臺。","天仙黼黻毛應是，宮后屏幃尾忽開。","曾處嶂中真霧隱，每過庭下似春來。","佳人爲我和衫拍，遣作傞傞送一杯。"]', '["偶有功名正俗才，靈禽何事降瑤台。","天仙黼黻毛應是，宮后屏幃尾忽开。","曾处嶂中真霧隐，每過庭下似春来。","佳人爲我和衫拍，遣作傞傞送一杯。"]', '诗', 'shi', '', NULL, '孔雀 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e50695-e4c1-4426-bb7a-844c91ec4a14', '鄜州進白野鵲', '鄜州進白野鵲', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["輕毛疊雪翅開霜，紅觜能深練尾長。","名應玉符朝北闕，色柔金性瑞西方。","不憂雲路填河遠，爲對天顏送喜忙。","從此定知栖息處，月宮瓊樹是仙鄉。"]', '["轻毛叠雪翅开霜，紅觜能深練尾长。","名應玉符朝北闕，色柔金性瑞西方。","不憂云路填河远，爲对天顏送喜忙。","從此定知栖息处，月宮瓊樹是仙乡。"]', '诗', 'shi', '', NULL, '鄜州進白野鵲 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c8d29b5-19cd-4ea0-be5b-81a62849f9a9', '早蟬', '早蟬', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["不見上庭樹，日高聲忽吟。","他人豈無耳，遠客自關心。","暫落還因雨，橫飛亦向林。","分明去年意，從此漸聞砧。"]', '["不见上庭樹，日高声忽吟。","他人豈無耳，远客自关心。","暫落還因雨，橫飞亦向林。","分明去年意，從此漸闻砧。"]', '诗', 'shi', '', NULL, '早蟬 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ea4119-61ac-466f-a213-12e142367f09', '申湖', '申湖', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["昔年依峽寺，每日見申湖。","下淚重來此，知心一已無。","雨霖舟色暗，岸拔木形枯。","舊境深相惱，新春宛不殊。","方來尋熟侶，起去恨驚鳧。","忍事花何笑，喧吟瀑正麤。","堪憂從宦到，倍遣曩懷孤。","上馬終回首，傍人怪感吁。"]', '["昔年依峽寺，每日见申湖。","下泪重来此，知心一已無。","雨霖舟色暗，岸拔木形枯。","旧境深相惱，新春宛不殊。","方来尋熟侶，起去恨驚鳧。","忍事花何笑，喧吟瀑正麤。","堪憂從宦到，倍遣曩懷孤。","上马終回首，傍人怪感吁。"]', '诗', 'shi', '', NULL, '申湖 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4636285-4584-486f-8b92-1192ac91983a', '謝劉相寄天柱茶', '謝劉相寄天柱茶', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["兩串春團敵夜光，名題天柱印維揚。","偷嫌曼倩桃無味，搗覺嫦娥藥不香。","惜恐被分緣利市，盡應難覓爲供堂。","麤官寄與真拋却，賴有詩情合得嘗。"]', '["兩串春團敵夜光，名題天柱印維揚。","偷嫌曼倩桃無味，捣覺嫦娥藥不香。","惜恐被分緣利市，尽應难覓爲供堂。","麤官寄與真拋却，賴有诗情合得嘗。"]', '诗', 'shi', '', NULL, '謝劉相寄天柱茶 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3816c063-78bf-4c2b-a95b-34c41e858712', '題後集', '題後集', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["詩源何代失澄清，處處狂波汙後生。","常感道孤吟有淚，却緣風壞語無情。","難甘惡少欺韓信，枉被諸侯殺禰衡。","縱到緱山也無益，四方聯絡盡蛙聲。"]', '["诗源何代失澄清，处处狂波汙後生。","常感道孤吟有泪，却緣风壞語無情。","难甘惡少欺韓信，枉被諸侯殺禰衡。","縱到緱山也無益，四方聯絡尽蛙声。"]', '诗', 'shi', '', NULL, '題後集 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8afbf6d1-854d-4d11-9b9e-ac1a7224b5df', '秋晚送無可上人', '秋晚送無可上人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["半夜覺松雨，照書燈悄然。","河聲纔淅瀝，舊業近潺湲。","坐滴寒更盡，吟驚宿鶴遷。","相思不相見，日短復愁牽。"]', '["半夜覺松雨，照书灯悄然。","河声纔淅瀝，旧業近潺湲。","坐滴寒更尽，吟驚宿鹤遷。","相思不相见，日短复愁牽。"]', '诗', 'shi', '', NULL, '秋晚送無可上人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44143931-90d0-4137-b3aa-a7a24442916d', '贈源寂禪師', '贈源寂禪師', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["缾鉢鎮隨腰，怡然處寂寥。","門禪從北祖，僧格似南朝。","性近徒相許，緣多媿未銷。","何傳能法慧，此岸要津橋。"]', '["缾鉢鎮隨腰，怡然处寂寥。","门禪從北祖，僧格似南朝。","性近徒相許，緣多媿未銷。","何傳能法慧，此岸要津橋。"]', '诗', 'shi', '', NULL, '贈源寂禪師 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('150741f5-a2c3-4a9f-8f6e-401232d39302', '贈禪師', '贈禪師', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嗜慾本無性，此生長在禪。","九州空有路，一室獨多年。","鳴磬微塵落，移缾濕地圓。","相尋偶同宿，星月坐忘眠。"]', '["嗜慾本無性，此生长在禪。","九州空有路，一室独多年。","鳴磬微塵落，移缾濕地圓。","相尋偶同宿，星月坐忘眠。"]', '诗', 'shi', '', NULL, '贈禪師 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('932041d0-4755-40d0-92a8-2b5ad1ea352f', '夏日青龍寺尋僧二首 一', '夏日青龙寺尋僧二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["帝里欲何待，人間無闕遺。","不能安舊隱，都屬擾明時。","違理須齊辱，雄圖豈藉知。","縱橫悉已悞，斯語是吾師。"]', '["帝里欲何待，人间無闕遺。","不能安旧隐，都屬擾明时。","違理須齊辱，雄圖豈藉知。","縱橫悉已悞，斯語是吾師。"]', '诗', 'shi', '', NULL, '夏日青龍寺尋僧二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0291f9c5-7edb-42e6-9203-3e1cf3608bdd', '夏日青龍寺尋僧二首 二', '夏日青龙寺尋僧二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["得官殊未喜，失計是忘愁。","不是無心速，焉能有自由。","涼風盈夏扇，蜀茗半形甌。","笑向權門客，應難見道流。"]', '["得官殊未喜，失計是忘愁。","不是無心速，焉能有自由。","涼风盈夏扇，蜀茗半形甌。","笑向權门客，應难见道流。"]', '诗', 'shi', '', NULL, '夏日青龍寺尋僧二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('220a2648-e3ad-4015-9126-86a498b19703', '寄題巨源禪師', '寄題巨源禪師', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["風雨禪思外，應殘木槿花。","何年別鄉土，一衲代袈裟。","日氣侵瓶暖，雷聲動枕斜。","還當掃樓影，天晚自煎茶。"]', '["风雨禪思外，應殘木槿花。","何年別乡土，一衲代袈裟。","日氣侵瓶暖，雷声动枕斜。","還當掃楼影，天晚自煎茶。"]', '诗', 'shi', '', NULL, '寄題巨源禪師 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8d762b-47fb-4980-b607-c0192be75491', '題河中亭子', '題河中亭子', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["河擘雙流島在中，島中亭上正南空。","蒲根舊浸臨關道，沙色遙飛傍苑風。","晴見樹卑知岳大，晚聞車亂覺橋通。","無窮勝事應須宿，霜白蒹葭月在東。"]', '["河擘雙流島在中，島中亭上正南空。","蒲根旧浸臨关道，沙色遙飞傍苑风。","晴见樹卑知岳大，晚闻车亂覺橋通。","無窮勝事應須宿，霜白蒹葭月在东。"]', '诗', 'shi', '', NULL, '題河中亭子 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46363da9-21bd-4264-a42b-de9ca9c437a8', '逢友人邊遊迴', '逢友人邊游迴', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["遊子新從絕塞迴，自言曾上李陵臺。","尊前語盡北風起，秋色蕭條胡雁來。"]', '["游子新從絕塞迴，自言曾上李陵台。","尊前語尽北风起，秋色蕭條胡雁来。"]', '诗', 'shi', '', NULL, '逢友人邊遊迴 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89fe9ccb-a211-431f-bb99-1314656edd3f', '春雨', '春雨', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["電闊照潺潺，驚流往復還。","遠聲如有洞，迷色似無山。","利物乾坤內，幷風竹樹間。","靜思來朔漠，愁望滿柴關。","迸濕消塵慮，吹風觸疾顏。","誰知草茅逕，霑此尚虛閑。"]', '["電闊照潺潺，驚流往复還。","远声如有洞，迷色似無山。","利物乾坤內，幷风竹樹间。","静思来朔漠，愁望满柴关。","迸濕消塵慮，吹风觸疾顏。","誰知草茅逕，霑此尚虛闲。"]', '诗', 'shi', '', NULL, '春雨 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99365897-a87c-4fc7-b36a-9b687f847aa1', '夏雨', '夏雨', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["何處發天涯，風雷一道賒。","去聲隨地急，殘勢傍樓斜。","透樹垂紅葉，霑塵帶落花。","瀟湘無限思，閑看下蒹葭。"]', '["何处發天涯，风雷一道賒。","去声隨地急，殘勢傍楼斜。","透樹垂紅葉，霑塵带落花。","瀟湘無限思，闲看下蒹葭。"]', '诗', 'shi', '', NULL, '夏雨 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b3183b2-8f62-4300-9ee1-b89a723b9aea', '秋夜山中述事', '秋夜山中述事', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["初宵門未掩，獨坐對霜空。","極目故鄉月，滿溪寒草風。","樵聲當嶺上，僧語在雲中。","正恨歸期晚，蕭蕭聞塞鴻。"]', '["初宵门未掩，独坐对霜空。","極目故乡月，满溪寒草风。","樵声當嶺上，僧語在云中。","正恨归期晚，蕭蕭闻塞鴻。"]', '诗', 'shi', '', NULL, '秋夜山中述事 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa14c7f-f540-41c6-b510-314cf6a9a75e', '長安道', '长安道', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["汲汲復營營，東西連兩京。","關繻古若在，山岳累應成。","各自有身事，不相知姓名。","交馳兼衆類，分散入重城。","此去應無盡，萬方人旋生。","空餘片言苦，來往覓劉楨。"]', '["汲汲复營營，东西連兩京。","关繻古若在，山岳累應成。","各自有身事，不相知姓名。","交驰兼衆類，分散入重城。","此去應無尽，万方人旋生。","空餘片言苦，来往覓劉楨。"]', '诗', 'shi', '', NULL, '長安道 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e11d25-2030-4754-9924-c9d0c17b3bf0', '酬泗州韋中丞埇上日寄贈兼次本韻', '酬泗州韋中丞埇上日寄贈兼次本韻', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["魯儒相悟欲成空，學盡文章不見功。","官自掖垣飄海上，鎮從隨岸入山中。","嘗遭火發瞿雲宅，爭得天如老氏弓。","何意杜陵懷寶客，也隨迷路出關東。"]', '["魯儒相悟欲成空，学尽文章不见功。","官自掖垣飄海上，鎮從隨岸入山中。","嘗遭火發瞿云宅，爭得天如老氏弓。","何意杜陵懷寶客，也隨迷路出关东。"]', '诗', 'shi', '', NULL, '酬泗州韋中丞埇上日寄贈兼次本韻 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e61e1f-e5da-4924-950b-0eeda938c055', '泛觴池', '泛觴池', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["通咽遠華罇，泛觴名自君。","淨看籌見影，輕動酒生紋。","細滴隨杯落，來聲就浦分。","便應半酣後，清冷漱兼雲。"]', '["通咽远华罇，泛觴名自君。","淨看籌见影，轻动酒生紋。","細滴隨杯落，来声就浦分。","便應半酣後，清冷漱兼云。"]', '诗', 'shi', '', NULL, '泛觴池 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cc527e-28e0-4e0f-ac6a-b0b29ff0ce4a', '荔枝', '荔枝', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["顆如松子色如櫻，未識蹉跎欲半生。","歲杪監州曾見樹，時新入座久聞名。"]', '["顆如松子色如櫻，未識蹉跎欲半生。","歲杪監州曾见樹，时新入座久闻名。"]', '诗', 'shi', '', NULL, '荔枝 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf379d92-0456-4a9d-b0f9-eac0d86833cc', '丁巳上元日放三雉', '丁巳上元日放三雉', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嬰網雖皆困，褰籠喜共歸。","無心期爾報，相見莫驚飛。"]', '["嬰網雖皆困，褰籠喜共归。","無心期爾報，相见莫驚飞。"]', '诗', 'shi', '', NULL, '丁巳上元日放三雉 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8cf66e-f9c8-4ead-98b0-7df7c811e412', '寓題', '寓題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["王澤猶來雅在新，尚詞微事可愁人。","淫哇滿眼關雎弱，猶賀清朝有此身。"]', '["王澤猶来雅在新，尚词微事可愁人。","淫哇满眼关雎弱，猶賀清朝有此身。"]', '诗', 'shi', '', NULL, '寓題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df8c412-98ba-4e49-b4df-a4ccb373761f', '望蜀亭', '望蜀亭', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["樹簇烟迷蜀國深，嶺頭分界戀登臨。","前軒一望無他處，從此西川只在心。"]', '["樹簇烟迷蜀国深，嶺头分界戀登臨。","前軒一望無他处，從此西川只在心。"]', '诗', 'shi', '', NULL, '望蜀亭 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1f6fbb8-8d72-4c58-a4c1-1a515a3ea09b', '游嘉州後溪', '游嘉州後溪', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["山屐經過滿逕蹤，隔溪遙見夕陽舂。","當時諸葛成何事，只合終身作臥龍。"]', '["山屐經過满逕蹤，隔溪遙见夕陽舂。","當时諸葛成何事，只合終身作臥龙。"]', '诗', 'shi', '', NULL, '游嘉州後溪 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace729f4-de76-4b78-b067-18029f3ba3dc', '自諷', '自諷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["千題萬詠過三旬，忘食貪魔作瘦人。","行處便吟君莫笑，就中詩病不任春。"]', '["千題万詠過三旬，忘食貪魔作瘦人。","行处便吟君莫笑，就中诗病不任春。"]', '诗', 'shi', '', NULL, '自諷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb6904f-a200-435c-96a4-0a18eee66e9a', '乞假歸題候館', '乞假归題候館', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["僕帶雕弓馬似飛，老萊衣上著戎衣。","郵亭不暇吟山水，塞外經年皆未歸。"]', '["僕带雕弓马似飞，老萊衣上著戎衣。","郵亭不暇吟山水，塞外經年皆未归。"]', '诗', 'shi', '', NULL, '乞假歸題候館 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae07da10-1611-4d09-ab1b-668174ed07ab', '監郡犍爲將歸使府登樓寓題', '監郡犍爲將归使府登楼寓題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["幾日監臨向蜀春，錯拋歌酒強憂人。","江樓一望西歸去，不負嘉州只負身。"]', '["幾日監臨向蜀春，錯拋歌酒強憂人。","江楼一望西归去，不負嘉州只負身。"]', '诗', 'shi', '', NULL, '監郡犍爲將歸使府登樓寓題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c4ce05a-8390-4f51-87f0-2485cf3fff22', '過象耳山二首 一', '過象耳山二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一色青松幾萬栽，異香薰路帶花開。","山門欲別心潛願，更到蜀中還到來。"]', '["一色青松幾万栽，異香薰路带花开。","山门欲別心潛願，更到蜀中還到来。"]', '诗', 'shi', '', NULL, '過象耳山二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98bbdf4d-d139-4aa1-ad85-f5c8884e1d7d', '過象耳山二首 二', '過象耳山二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["到處逢山便欲登，自疑身作往來僧。","徒行至此三千里，不是有緣應不能。"]', '["到处逢山便欲登，自疑身作往来僧。","徒行至此三千里，不是有緣應不能。"]', '诗', 'shi', '', NULL, '過象耳山二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580c66f7-8653-4e62-9cdf-24f3b662369f', '聖燈', '聖灯', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["莽莽空中稍稍燈，坐看迷濁變[清澄]。","須知火盡煙無益，一夜欄邊說向僧。"]', '["莽莽空中稍稍灯，坐看迷濁变[清澄]。","須知火尽煙無益，一夜欄邊说向僧。"]', '诗', 'shi', '', NULL, '聖燈 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('413d4b5c-fbe3-4600-a40b-8d4e420405fc', '過昌利觀有懷', '過昌利观有懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["萬仞雲峯八石泉，李君仙後更誰仙。","我來駐馬人何問，老柏無多不種田。"]', '["万仞云峯八石泉，李君仙後更誰仙。","我来駐马人何问，老柏無多不種田。"]', '诗', 'shi', '', NULL, '過昌利觀有懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9df24b-d5b8-40d7-861e-90e1cd230f2a', '蜀路', '蜀路', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["劒閣緣雲拂斗魁，疾風生樹過龍媒。","前程憩罷知無益，但是駑蹄亦到來。"]', '["劒閣緣云拂斗魁，疾风生樹過龙媒。","前程憩罷知無益，但是駑蹄亦到来。"]', '诗', 'shi', '', NULL, '蜀路 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281d1378-d0e8-49c3-9915-57b6994fae0e', '山下偶作', '山下偶作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["零雨霑山百草香，樹梢高頂盡斜陽。","橫流巨石皆堪住，何事無僧有石房。"]', '["零雨霑山百草香，樹梢高頂尽斜陽。","橫流巨石皆堪住，何事無僧有石房。"]', '诗', 'shi', '', NULL, '山下偶作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08d05dcc-9355-4b5f-9c33-43be2826e1ca', '伏牛山', '伏牛山', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["虎蹲峰狀屈名牛，落日連村好望秋。","不爲時危耕不得，一犁風雨便歸休。"]', '["虎蹲峰狀屈名牛，落日連村好望秋。","不爲时危耕不得，一犁风雨便归休。"]', '诗', 'shi', '', NULL, '伏牛山 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74fd5a2-480a-486f-8be1-f41acacd51fb', '老圃堂', '老圃堂', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["邵平瓜地接吾廬，穀雨乾時偶自鋤。","昨日春風欺不在，就牀吹落讀殘書。"]', '["邵平瓜地接吾廬，穀雨乾时偶自鋤。","昨日春风欺不在，就牀吹落读殘书。"]', '诗', 'shi', '', NULL, '老圃堂 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2fef66-69fd-4be7-b9c8-263ec345282d', '春題', '春題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["柳莫搖搖花莫開，此心因病亦成灰。","人生只有家園樂，及取春農歸去來。"]', '["柳莫搖搖花莫开，此心因病亦成灰。","人生只有家园乐，及取春農归去来。"]', '诗', 'shi', '', NULL, '春題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('207fcfd4-0d58-4721-8840-61c2677c84e9', '幷州寓懷', '幷州寓懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["人多知遇獨難求，人負知音獨愛酬。","常恐此心無樂處，枉稱年少在幷州。"]', '["人多知遇独难求，人負知音独愛酬。","常恐此心無乐处，枉稱年少在幷州。"]', '诗', 'shi', '', NULL, '幷州寓懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c30762-824e-444a-98b7-4c21597e3f39', '中秋旅舍', '中秋旅舍', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["雲卷庭虛月逗空，一方秋草盡鳴蟲。","是時兄弟正南北，黃葉滿階來去風。"]', '["云卷庭虛月逗空，一方秋草尽鳴蟲。","是时兄弟正南北，黄葉满階来去风。"]', '诗', 'shi', '', NULL, '中秋旅舍 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07a2c0a-2ee3-4e4c-8c67-b13079494901', '符亭二首 一', '符亭二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["符亭之地雅離羣，萬古懸泉一旦新。","若念農桑也如此，縣人應得似行人。"]', '["符亭之地雅離羣，万古懸泉一旦新。","若念農桑也如此，縣人應得似行人。"]', '诗', 'shi', '', NULL, '符亭二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c99ee213-2957-40d7-b43d-f8dceeede87f', '符亭二首 二', '符亭二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["山如巫峽煙雲好，路似嘉祥水木清。","大抵游人總應愛，就中難說是詩情。"]', '["山如巫峽煙云好，路似嘉祥水木清。","大抵游人總應愛，就中难说是诗情。"]', '诗', 'shi', '', NULL, '符亭二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4f93c1-d9b3-4ff5-b21f-d29d8c5b7112', '秋夜聽任郎中琴', '秋夜听任郎中琴', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["十指宮商膝上秋，七條絲動雨修修。","空堂半夜孤燈冷，彈著鄉心欲白頭。"]', '["十指宮商膝上秋，七條絲动雨修修。","空堂半夜孤灯冷，彈著乡心欲白头。"]', '诗', 'shi', '', NULL, '秋夜聽任郎中琴 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1916f332-5689-4843-89d4-7bf8ca6ac779', '留別關東舊遊', '留別关东旧游', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["我去君留十載中，未曾相見及花紅。","他時住得君應老，長短看花心不同。"]', '["我去君留十載中，未曾相见及花紅。","他时住得君應老，长短看花心不同。"]', '诗', 'shi', '', NULL, '留別關東舊遊 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9881a024-6000-4a37-a7b2-6ed7d3b85318', '贈出塞客', '贈出塞客', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["出郊征騎逐飛埃，此別惟愁春未回。","寒葉夕陽投宿意，蘆關門向遠河開。"]', '["出郊征騎逐飞埃，此別惟愁春未回。","寒葉夕陽投宿意，蘆关门向远河开。"]', '诗', 'shi', '', NULL, '贈出塞客 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a876d70-237a-40d7-83eb-88212d425c85', '秋溪獨坐', '秋溪独坐', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["黃葉分飛砧上下，白雲零落馬東西。","人生萬意此端坐，日暮水深流出溪。"]', '["黄葉分飞砧上下，白云零落马东西。","人生万意此端坐，日暮水深流出溪。"]', '诗', 'shi', '', NULL, '秋溪獨坐 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee54bb30-2df5-4fa9-a6eb-cb24b2db59e7', '蒲中霽後晚望', '蒲中霽後晚望', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["河邊霽色無人見，身帶春風立岸頭。","濁水茫茫有何意，日斜還向古蒲州。"]', '["河邊霽色無人见，身带春风立岸头。","濁水茫茫有何意，日斜還向古蒲州。"]', '诗', 'shi', '', NULL, '蒲中霽後晚望 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62dd234b-3782-4839-8154-e82355fc5d03', '宋氏林亭', '宋氏林亭', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["地濕莎青雨後天，桃花紅近竹林邊。","行人本是農桑客，記得春深欲種田。"]', '["地濕莎青雨後天，桃花紅近竹林邊。","行人本是農桑客，記得春深欲種田。"]', '诗', 'shi', '', NULL, '宋氏林亭 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe47120-cf31-48ff-829f-89f32d7a9fcf', '雲花寺寓居贈海岸上人', '云花寺寓居贈海岸上人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["暫寄空門未是歸，上方林榭獨儒衣。","吾師不語應相怪，頻惹街塵入寺飛。"]', '["暫寄空门未是归，上方林榭独儒衣。","吾師不語應相怪，頻惹街塵入寺飞。"]', '诗', 'shi', '', NULL, '雲花寺寓居贈海岸上人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a08ee6d-973b-428c-a940-1b662a218da1', '關中秋夕', '关中秋夕', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["簟濕秋庭岳在煙，露光明滑竹蒼然。","何人意緒還相似，鶴宿松枝月半天。"]', '["簟濕秋庭岳在煙，露光明滑竹蒼然。","何人意緒還相似，鹤宿松枝月半天。"]', '诗', 'shi', '', NULL, '關中秋夕 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea1835ae-01fe-4152-887b-c42d66b9d8fe', '西縣道中有短亭巖穴飛泉隔江灑至因成二首 一', '西縣道中有短亭巖穴飞泉隔江灑至因成二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["風涼津濕共微微，隔岸泉衝石竅飛。","爭得巨靈從野性，舊鄉無此擘將歸。"]', '["风涼津濕共微微，隔岸泉衝石竅飞。","爭得巨靈從野性，旧乡無此擘將归。"]', '诗', 'shi', '', NULL, '西縣道中有短亭巖穴飛泉隔江灑至因成二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000256d0-21ac-4d7f-b03b-1f6af7be7d54', '西縣道中有短亭巖穴飛泉隔江灑至因成二首 二', '西縣道中有短亭巖穴飞泉隔江灑至因成二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一瀑三峰赤日天，路人才見便翛然。","誰能夜向山根宿，涼月初生的有仙。"]', '["一瀑三峰赤日天，路人才见便翛然。","誰能夜向山根宿，涼月初生的有仙。"]', '诗', 'shi', '', NULL, '西縣道中有短亭巖穴飛泉隔江灑至因成二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a014ec2-00f5-4636-a006-6bbdb02e8ffa', '省試夜', '省試夜', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["白蓮千朵照廊明，一片承平雅頌聲。","更報第三條燭盡，文昌風景畫難成。"]', '["白蓮千朵照廊明，一片承平雅頌声。","更報第三條燭尽，文昌风景畫难成。"]', '诗', 'shi', '', NULL, '省試夜 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bc1bd7-b636-4e79-a91f-b87860b9a87b', '過驪山', '過驪山', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["丹雘蒼蒼簇背山，路塵應滿舊簾間。","玄宗不是偏行樂，只爲當時四海閑。"]', '["丹雘蒼蒼簇背山，路塵應满旧簾间。","玄宗不是偏行乐，只爲當时四海闲。"]', '诗', 'shi', '', NULL, '過驪山 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c742f25-9579-4741-b100-ea75925f5d07', '曲江醉題', '曲江醉題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["閑身行止屬年華，馬上懷中盡落花。","狂遍曲江還醉臥，覺來人靜日西斜。"]', '["闲身行止屬年华，马上懷中尽落花。","狂遍曲江還醉臥，覺来人静日西斜。"]', '诗', 'shi', '', NULL, '曲江醉題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0062cc38-7134-47cd-b1e4-25756b3f0f6d', '參軍廳新池', '參軍廳新池', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["簾外無塵勝物外，牆根有竹似山根。","流泉不至客來久，坐見新池落舊痕。"]', '["簾外無塵勝物外，牆根有竹似山根。","流泉不至客来久，坐见新池落旧痕。"]', '诗', 'shi', '', NULL, '參軍廳新池 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d513c087-4243-4cc8-b124-2696c09279ee', '太原使院晚出', '太原使院晚出', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["青門無路入清朝，濫作將軍最下僚。","同舍盡歸身獨在，晚風開印葉蕭蕭。"]', '["青门無路入清朝，濫作將軍最下僚。","同舍尽归身独在，晚风开印葉蕭蕭。"]', '诗', 'shi', '', NULL, '太原使院晚出 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f8882c-40e5-4d86-9a9f-e0b9755a5d59', '寒食日曲江', '寒食日曲江', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["曲水池邊青草岸，春風林下落花盃。","都門此日是寒食，人去看多身獨來。"]', '["曲水池邊青草岸，春风林下落花盃。","都门此日是寒食，人去看多身独来。"]', '诗', 'shi', '', NULL, '寒食日曲江 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb1e4f66-c42a-4bf4-9a01-cbca409e1115', '盩厔官舍新竹', '盩厔官舍新竹', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["心覺清涼體似吹，滿風輕撼葉垂垂。","無端種在幽閑地，衆鳥嫌寒鳳未知。"]', '["心覺清涼體似吹，满风轻撼葉垂垂。","無端種在幽闲地，衆鸟嫌寒鳳未知。"]', '诗', 'shi', '', NULL, '盩厔官舍新竹 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71dbe3b0-c23c-4494-a306-ea14299a7cf0', '京中客舍聞箏', '京中客舍闻箏', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["十二三弦共五音，每聲如截遠人心。","當時向秀聞鄰笛，不是離家歲月深。"]', '["十二三弦共五音，每声如截远人心。","當时向秀闻鄰笛，不是離家歲月深。"]', '诗', 'shi', '', NULL, '京中客舍聞箏 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f65c9bb3-c5b1-41a1-8afa-095fd56273ff', '銅雀臺', '銅雀台', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["魏帝當時銅雀臺，黃花深映棘叢開。","人生富貴須回首，此地豈無歌舞來。"]', '["魏帝當时銅雀台，黄花深映棘叢开。","人生富貴須回首，此地豈無歌舞来。"]', '诗', 'shi', '', NULL, '銅雀臺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe82ee3d-e42a-454a-8611-87b0b40be7c3', '壽安水館', '壽安水館', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["地接山林兼有石，天懸星月更無雲。","驚鷗上樹滿池水，瀺灂一聲中夜聞。"]', '["地接山林兼有石，天懸星月更無云。","驚鷗上樹满池水，瀺灂一声中夜闻。"]', '诗', 'shi', '', NULL, '壽安水館 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c138067-b4c7-43dd-8975-f54ac54bb211', '雨後早發永寧', '雨後早發永寧', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["春霖朝罷客西東，雨足泥聲路未通。","獨愛千峰最高處，一峰初日白雲中。"]', '["春霖朝罷客西东，雨足泥声路未通。","独愛千峰最高处，一峰初日白云中。"]', '诗', 'shi', '', NULL, '雨後早發永寧 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd9488d-812e-411e-9766-04db0aa6d1c2', '宿仙遊寺望月生峰', '宿仙游寺望月生峰', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["公門身入洞門行，出穽離籠似有情。","僧語夜涼雲樹黑，月生峰上月初生。"]', '["公门身入洞门行，出穽離籠似有情。","僧語夜涼云樹黑，月生峰上月初生。"]', '诗', 'shi', '', NULL, '宿仙遊寺望月生峰 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788bd925-bb03-425e-a9e9-6e73129fb881', '秋題', '秋題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["獨坐東南見曉星，白雲微透泬寥清。","磷磷甃石堪僧坐，一葉梧桐落半庭。"]', '["独坐东南见晓星，白云微透泬寥清。","磷磷甃石堪僧坐，一葉梧桐落半庭。"]', '诗', 'shi', '', NULL, '秋題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9907abf9-b9ac-40be-9f0c-c639e7093a65', '和友人寄懷', '和友人寄懷', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["從來行樂近來希，蘧瑗知言與我違。","自是衰心不如舊，非關四十九年非。"]', '["從来行乐近来希，蘧瑗知言與我違。","自是衰心不如旧，非关四十九年非。"]', '诗', 'shi', '', NULL, '和友人寄懷 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd6cadc-63d9-4f17-95b9-b2159d0bf59c', '子夜', '子夜', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嫖姚家宴敵吳王，子夜歌聲滿畫堂。","此日相逢眉翠盡，女真行李乞齋糧。"]', '["嫖姚家宴敵吳王，子夜歌声满畫堂。","此日相逢眉翠尽，女真行李乞斋糧。"]', '诗', 'shi', '', NULL, '子夜 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd155ce-c814-4865-ab1f-226732c1fa51', '鴈和韋侍御', '鴈和韋侍御', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["肅肅雍雍義有餘，九天鸞鳳莫相疎。","唯應靜向山窗過，激發英雄夜讀書。"]', '["肅肅雍雍義有餘，九天鸾鳳莫相疎。","唯應静向山窗過，激發英雄夜读书。"]', '诗', 'shi', '', NULL, '鴈和韋侍御 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1939702-4ad5-4362-83f7-f38cb02ba8de', '和府帥相公', '和府帥相公', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["竹映高牆似傍山，鄒陽歸後令威還。","君看將相才多少，兩首詩成七步間。"]', '["竹映高牆似傍山，鄒陽归後令威還。","君看將相才多少，兩首诗成七步间。"]', '诗', 'shi', '', NULL, '和府帥相公 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf47485b-f897-443f-bdee-967a4caf31cd', '又和留山雞', '又和留山雞', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["五色文勝百鳥王，相思兼絕寄芸香。","由來不是池中物，雞樹歸時即取將。"]', '["五色文勝百鸟王，相思兼絕寄芸香。","由来不是池中物，雞樹归时即取將。"]', '诗', 'shi', '', NULL, '又和留山雞 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff701bd-ab08-4d70-9cdc-2b2ffe992d08', '舟中酬楊中丞春早見寄', '舟中酬楊中丞春早见寄', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["錦樓春望憶丹楹，更遇高情說早鶯。","江上境寒吟不得，濕風梅雨滿船輕。"]', '["錦楼春望憶丹楹，更遇高情说早鶯。","江上境寒吟不得，濕风梅雨满船轻。"]', '诗', 'shi', '', NULL, '舟中酬楊中丞春早見寄 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6559a5-6734-4063-8f3d-06c6c6f8efb8', '寒食日題', '寒食日題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["美人寒食事春風，折盡青青賞盡紅。","夜半無燈還有睡，鞦韆懸在月明中。"]', '["美人寒食事春风，折尽青青賞尽紅。","夜半無灯還有睡，鞦韆懸在月明中。"]', '诗', 'shi', '', NULL, '寒食日題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300a7043-4b2c-4e6b-a121-c20aeb89857e', '杏花', '杏花', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["活色生香第一流，手中移得近青樓。","誰知豔性終相負，亂向春風笑不休。"]', '["活色生香第一流，手中移得近青楼。","誰知豔性終相負，亂向春风笑不休。"]', '诗', 'shi', '', NULL, '杏花 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131bb13a-12b1-499f-bcb7-1d10ac6a04c3', '黃蜀葵', '黄蜀葵', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嬌黃新嫩欲題詩，盡日含毫有所思。","記得玉人初病起，道家粧束厭禳時。"]', '["嬌黄新嫩欲題诗，尽日含毫有所思。","記得玉人初病起，道家粧束厭禳时。"]', '诗', 'shi', '', NULL, '黃蜀葵 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8bbb2cc-a330-4d67-800f-5124c1fd62f2', '春詠', '春詠', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["春來還似去年時，手把花枝唱竹枝。","狂瘦未曾餐有味，不緣中酒却緣詩。"]', '["春来還似去年时，手把花枝唱竹枝。","狂瘦未曾餐有味，不緣中酒却緣诗。"]', '诗', 'shi', '', NULL, '春詠 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6190e1a-0b40-4c1f-a70a-3c67abc3af49', '贈歡娘', '贈歡娘', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一束龍吟細竹枝，青娥擎在手中吹。","當時縱使雙成在，不得如伊是小時。"]', '["一束龙吟細竹枝，青娥擎在手中吹。","當时縱使雙成在，不得如伊是小时。"]', '诗', 'shi', '', NULL, '贈歡娘 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c487c5-43fd-4fca-8da2-90324c2a5ec3', '戲瞻相', '戲瞻相', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["失意蹉跎到舊遊，見吹楊柳便遮羞。","瞻相趙女休相拽，不及人前詐擺頭。"]', '["失意蹉跎到旧游，见吹楊柳便遮羞。","瞻相趙女休相拽，不及人前詐擺头。"]', '诗', 'shi', '', NULL, '戲瞻相 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f2ee017-aebe-465f-8873-575f82059669', '贈解詩歌人', '贈解诗歌人', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["同有詩情自合親，不須歌調更含嚬。","朝天御史非韓壽，莫竊香來帶累人。"]', '["同有诗情自合親，不須歌調更含嚬。","朝天御史非韓壽，莫竊香来带累人。"]', '诗', 'shi', '', NULL, '贈解詩歌人 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58510824-7fae-427d-bd92-53ab35243446', '贈韋氏歌人二首 一', '贈韋氏歌人二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["弦管聲凝發唱高，幾人心地暗傷刀。","思量更有何堪比，王母新開一樹桃。"]', '["弦管声凝發唱高，幾人心地暗傷刀。","思量更有何堪比，王母新开一樹桃。"]', '诗', 'shi', '', NULL, '贈韋氏歌人二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca5a9b3-0a9d-4100-b887-33ad6661fcbb', '贈韋氏歌人二首 二', '贈韋氏歌人二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一曲新聲慘畫堂，可能心事憶周郎。","朝來爲客頻開口，綻盡桃花幾許香。"]', '["一曲新声慘畫堂，可能心事憶周郎。","朝来爲客頻开口，綻尽桃花幾許香。"]', '诗', 'shi', '', NULL, '贈韋氏歌人二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cedaeb1-61f1-4940-8950-a18b66a76e4f', '加階', '加階', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["二年中散似稽康，此日無功換寵光。","唯有一般酬聖主，勝於東晉是文章。"]', '["二年中散似稽康，此日無功換寵光。","唯有一般酬聖主，勝於东晉是文章。"]', '诗', 'shi', '', NULL, '加階 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3828c6-ddf7-482d-8ccc-3aa58f83c5ca', '野園', '野园', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["野園無鼓又無旗，鞍馬傳盃用柳枝。","嬌養翠娥無怕懼，插人頭上任風吹。"]', '["野园無鼓又無旗，鞍马傳盃用柳枝。","嬌養翠娥無怕懼，插人头上任风吹。"]', '诗', 'shi', '', NULL, '野園 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf9862b1-0822-47e5-8daa-8bfa5b22d121', '郊亭', '郊亭', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["郊亭宴罷欲回車，滿郭傳呼調角初。","尚擁笙歌歸未得，笑娥扶著醉尚書。"]', '["郊亭宴罷欲回车，满郭傳呼調角初。","尚擁笙歌归未得，笑娥扶著醉尚书。"]', '诗', 'shi', '', NULL, '郊亭 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab90a140-e7c0-48ae-bd7a-60389088ca1f', '老僧', '老僧', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["清瘦形容八十餘，匏懸籬落似村居。","勸師莫羨人間有，幸是元無免破除。"]', '["清瘦形容八十餘，匏懸籬落似村居。","勸師莫羨人间有，幸是元無免破除。"]', '诗', 'shi', '', NULL, '老僧 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('447a8229-f89b-43fa-9128-ee1216b023fd', '僧窗', '僧窗', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["不悟時機滯有餘，近來爲事更乖疎。","朱輪皂蓋蹉跎盡，猶愛明窗好讀書。"]', '["不悟时機滯有餘，近来爲事更乖疎。","朱輪皂蓋蹉跎尽，猶愛明窗好读书。"]', '诗', 'shi', '', NULL, '僧窗 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54ec5e02-ad5a-48f7-a210-947c6e4ccbc0', '題平等院', '題平等院', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["十里城中一院僧，各持巾鉢事南能。","還應笑我功名客，未解嫌官學大乘。"]', '["十里城中一院僧，各持巾鉢事南能。","還應笑我功名客，未解嫌官学大乘。"]', '诗', 'shi', '', NULL, '題平等院 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d264b50a-39c7-489b-b5b3-d20980c41078', '影燈夜二首 一', '影灯夜二首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["偃王燈塔古徐州，二十年來樂事休。","此日將軍心似海，四更身領萬人遊。"]', '["偃王灯塔古徐州，二十年来乐事休。","此日將軍心似海，四更身領万人游。"]', '诗', 'shi', '', NULL, '影燈夜二首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22488a34-a7de-4fb4-90ea-1cd6c9e7e7da', '影燈夜二首 二', '影灯夜二首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["十萬軍城百萬燈，酥油香暖夜如烝。","紅粧滿地煙光好，只恐笙歌引上昇。"]', '["十万軍城百万灯，酥油香暖夜如烝。","紅粧满地煙光好，只恐笙歌引上昇。"]', '诗', 'shi', '', NULL, '影燈夜二首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7beb9de-4024-41b5-9f9c-1f25defba1ee', '許州旌節到作', '許州旌節到作', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["兩地旌旗擁一身，半緣傷舊半榮新。","州人若憶將軍面，寫取雕堂報國真。"]', '["兩地旌旗擁一身，半緣傷旧半榮新。","州人若憶將軍面，寫取雕堂報国真。"]', '诗', 'shi', '', NULL, '許州旌節到作 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b055a50a-952c-41ad-b83f-d54237fa9d89', '重遊通波亭', '重游通波亭', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["十年拋擲故園花，最憶紅桃竹外斜。","此日郊亭心乍喜，敗榆芳草似還家。"]', '["十年拋擲故园花，最憶紅桃竹外斜。","此日郊亭心乍喜，敗榆芳草似還家。"]', '诗', 'shi', '', NULL, '重遊通波亭 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50ae828-56ed-4262-b405-57f06008c41a', '戲舸', '戲舸', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["遠舸衝開一路萍，岸傍偷上小茅亭。","遊人莫覓盃盤分，此地纔應聚德星。"]', '["远舸衝开一路萍，岸傍偷上小茅亭。","游人莫覓盃盤分，此地纔應聚德星。"]', '诗', 'shi', '', NULL, '戲舸 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00c8ba0d-e202-4baf-9e05-44709096db23', '偶題', '偶題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["到處吟兼上馬吟，總無愁恨自傷心。","無端夢得鈞天樂，盡覺宮商不是音。"]', '["到处吟兼上马吟，總無愁恨自傷心。","無端梦得鈞天乐，尽覺宮商不是音。"]', '诗', 'shi', '', NULL, '偶題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('238ce639-9299-4622-bd67-0d04c262d0e9', '折楊柳十首 一', '折楊柳十首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["華清高樹出離宮，南陌柔條帶暖風。","誰見輕陰是良夜，瀑泉聲畔月明中。"]', '["华清高樹出離宮，南陌柔條带暖风。","誰见轻陰是良夜，瀑泉声畔月明中。"]', '诗', 'shi', '', NULL, '折楊柳十首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf850a3b-d6cd-47cf-ad7c-44cfb11e4e1f', '折楊柳十首 二', '折楊柳十首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["洛橋晴影覆江船，羌笛秋聲濕塞煙。","閑想習池公宴罷，水蒲風絮夕陽天。"]', '["洛橋晴影覆江船，羌笛秋声濕塞煙。","闲想習池公宴罷，水蒲风絮夕陽天。"]', '诗', 'shi', '', NULL, '折楊柳十首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26102866-ae6f-4417-9598-8a750edf7358', '折楊柳十首 三', '折楊柳十首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嫩綠輕懸似綴旒，路人遙見隔宮樓。","誰能更近丹墀種，解播皇風入九州。"]', '["嫩綠轻懸似綴旒，路人遙见隔宮楼。","誰能更近丹墀種，解播皇风入九州。"]', '诗', 'shi', '', NULL, '折楊柳十首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec0807c-13d4-4be4-bf27-3fff6423a7c6', '折楊柳十首 四', '折楊柳十首 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["暖風晴日斷浮埃，廢路新條發釣臺。","處處輕陰可惆悵，後人攀處古人栽。"]', '["暖风晴日斷浮埃，廢路新條發釣台。","处处轻陰可惆悵，後人攀处古人栽。"]', '诗', 'shi', '', NULL, '折楊柳十首 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e9e2b6e-ed06-4638-98d3-fdd58a2c644f', '折楊柳十首 五', '折楊柳十首 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["潭上江邊嫋嫋垂，日高風靜絮相隨。","青樓一樹無人見，正是女郎眠覺時。"]', '["潭上江邊嫋嫋垂，日高风静絮相隨。","青楼一樹無人见，正是女郎眠覺时。"]', '诗', 'shi', '', NULL, '折楊柳十首 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d4275a-2094-43f6-8589-9e91ef5dffa1', '折楊柳十首 六', '折楊柳十首 六', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["汴水高懸百萬條，風清兩岸一時搖。","隋家力盡虛栽得，無限春風屬聖朝。"]', '["汴水高懸百万條，风清兩岸一时搖。","隋家力尽虛栽得，無限春风屬聖朝。"]', '诗', 'shi', '', NULL, '折楊柳十首 六 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3450fbd5-ff49-437f-90c7-7af0ce6fb040', '折楊柳十首 七', '折楊柳十首 七', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["和風煙樹九重城，夾路春陰十萬營。","唯向邊頭不堪望，一株顦顇少人行。"]', '["和风煙樹九重城，夾路春陰十万營。","唯向邊头不堪望，一株顦顇少人行。"]', '诗', 'shi', '', NULL, '折楊柳十首 七 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b223e4-007e-425f-8bf4-86f967ad823c', '折楊柳十首 八', '折楊柳十首 八', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["窗外齊垂旭日初，樓邊輕暖好風徐。","游人莫道栽無益，桃李清陰却不如。"]', '["窗外齊垂旭日初，楼邊轻暖好风徐。","游人莫道栽無益，桃李清陰却不如。"]', '诗', 'shi', '', NULL, '折楊柳十首 八 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dff19f9-273e-4a86-9726-78a9bcbf7d61', '折楊柳十首 九', '折楊柳十首 九', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["衆木猶寒獨早青，御溝橋畔曲江亭。","陶家舊日應如此，一院春條綠遶廳。"]', '["衆木猶寒独早青，御溝橋畔曲江亭。","陶家旧日應如此，一院春條綠遶廳。"]', '诗', 'shi', '', NULL, '折楊柳十首 九 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('367a4b38-14dc-4aed-a725-b70643c2178d', '折楊柳十首 十', '折楊柳十首 十', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["帳偃纓垂細復繁，令人心想石家園。","風條月影皆堪重，何事侯門愛樹萱。"]', '["帳偃纓垂細复繁，令人心想石家园。","风條月影皆堪重，何事侯门愛樹萱。"]', '诗', 'shi', '', NULL, '折楊柳十首 十 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae97e8f-20a3-4afc-b48e-b1a8aef541d6', '柳枝四首 一', '柳枝四首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["數首新詩帶恨成，柳絲牽我我傷情。","柔娥幸有腰支穩，試踏吹聲作唱聲。"]', '["數首新诗带恨成，柳絲牽我我傷情。","柔娥幸有腰支穩，試踏吹声作唱声。"]', '诗', 'shi', '', NULL, '柳枝四首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61eb84d3-ed42-49ad-8f2c-458ea6119127', '柳枝四首 二', '柳枝四首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["高出軍營遠映橋，賊兵曾斫火曾燒。","風流性在終難改，依舊春來萬萬條。"]', '["高出軍營远映橋，賊兵曾斫火曾燒。","风流性在終难改，依旧春来万万條。"]', '诗', 'shi', '', NULL, '柳枝四首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ba3695-699d-4c0b-9af0-01873fbccc4b', '柳枝四首 三', '柳枝四首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["縣依陶令想嫌迂，營畔將軍即大麤。","此日與君除萬恨，數篇風調更應無。"]', '["縣依陶令想嫌迂，營畔將軍即大麤。","此日與君除万恨，數篇风調更應無。"]', '诗', 'shi', '', NULL, '柳枝四首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c18141-6d05-4aad-ad22-f3115c58f8f3', '柳枝四首 四', '柳枝四首 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["狂似纖腰嫩勝綿，自多情態竟誰憐。","遊人不折還堪恨，拋向橋邊與路邊。"]', '["狂似纖腰嫩勝綿，自多情態竟誰怜。","游人不折還堪恨，拋向橋邊與路邊。"]', '诗', 'shi', '', NULL, '柳枝四首 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e577b8d-1c61-4ea9-9e05-345a3b818883', '柳枝詞五首 一', '柳枝词五首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["朝陽晴照綠楊煙，一別通波十七年。","應有舊枝無處覓，萬株風裏卓旌旃。"]', '["朝陽晴照綠楊煙，一別通波十七年。","應有旧枝無处覓，万株风裏卓旌旃。"]', '诗', 'shi', '', NULL, '柳枝詞五首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7cd2515-7b11-4397-9db6-e2f2d8b30ac7', '柳枝詞五首 二', '柳枝词五首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["晴垂芳態吐牙新，雨擺輕條濕面春。","別有出墻高數尺，不知搖動是何人。"]', '["晴垂芳態吐牙新，雨擺轻條濕面春。","別有出墻高數尺，不知搖动是何人。"]', '诗', 'shi', '', NULL, '柳枝詞五首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e927224-95d1-410e-bd95-6857f9eb769b', '柳枝詞五首 三', '柳枝词五首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["暖梳簪朵事登樓，因挂垂楊立地愁。","牽斷綠絲攀不得，半空懸著玉搔頭。"]', '["暖梳簪朵事登楼，因挂垂楊立地愁。","牽斷綠絲攀不得，半空懸著玉搔头。"]', '诗', 'shi', '', NULL, '柳枝詞五首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f41fea8-3ed2-4a59-8e78-369a42861066', '柳枝詞五首 四', '柳枝词五首 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["西園高樹後庭根，處處尋芳有折痕。","終憶舊遊桃葉舍，一株斜映竹籬門。"]', '["西园高樹後庭根，处处尋芳有折痕。","終憶旧游桃葉舍，一株斜映竹籬门。"]', '诗', 'shi', '', NULL, '柳枝詞五首 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce56f58c-a66c-4b15-8e1a-ec7bcd90e80a', '柳枝詞五首 五', '柳枝词五首 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["劉白蘇臺總近時，當初章句是誰推。","纖腰舞盡春楊柳，未有儂家一首詩。"]', '["劉白蘇台總近时，當初章句是誰推。","纖腰舞尽春楊柳，未有儂家一首诗。"]', '诗', 'shi', '', NULL, '柳枝詞五首 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50dea09f-4e36-4d85-909b-5219a1471d2f', '吳姬十首 一', '吳姬十首 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["夜鎖重門晝亦監，眼波嬌利瘦巖巖。","偏憐不怕傍人笑，自把春羅等舞衫。"]', '["夜鎖重门晝亦監，眼波嬌利瘦巖巖。","偏怜不怕傍人笑，自把春羅等舞衫。"]', '诗', 'shi', '', NULL, '吳姬十首 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5eef33b-8ecb-4b1b-8776-93751918758a', '吳姬十首 二', '吳姬十首 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["龍麝薰多骨亦香，因經寒食好風光。","何人畫得天生態，枕破施朱隔宿粧。"]', '["龙麝薰多骨亦香，因經寒食好风光。","何人畫得天生態，枕破施朱隔宿粧。"]', '诗', 'shi', '', NULL, '吳姬十首 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bafe460-9265-428c-ab3e-1d2844809efa', '吳姬十首 三', '吳姬十首 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["滴滴春霖透荔枝，筆題牋動手中垂。","天陰不得君王召，嚬著青蛾作小詩。"]', '["滴滴春霖透荔枝，笔題牋动手中垂。","天陰不得君王召，嚬著青蛾作小诗。"]', '诗', 'shi', '', NULL, '吳姬十首 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b99b6a5b-e92a-4430-9686-d77260d0d148', '吳姬十首 四', '吳姬十首 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["鈿合重盛繡結深，昭陽初幸賜同心。","君知一夜恩多少，明日宣敎放德音。"]', '["鈿合重盛繡結深，昭陽初幸賜同心。","君知一夜恩多少，明日宣敎放德音。"]', '诗', 'shi', '', NULL, '吳姬十首 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97667ae1-7bd2-48bb-a062-e3a0d0415e78', '吳姬十首 五', '吳姬十首 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["退紅香汗濕輕紗，高捲蚊廚獨臥斜。","嬌淚半垂珠不破，恨君瞋折後庭花。"]', '["退紅香汗濕轻紗，高捲蚊廚独臥斜。","嬌泪半垂珠不破，恨君瞋折後庭花。"]', '诗', 'shi', '', NULL, '吳姬十首 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ddecd5-d850-42e5-80af-5611fe4580ee', '吳姬十首 六', '吳姬十首 六', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["取次衣裳盡帶珠，別添龍腦裛羅襦。","年來寄與鄉中伴，殺盡春蠶稅亦無。"]', '["取次衣裳尽带珠，別添龙腦裛羅襦。","年来寄與乡中伴，殺尽春蠶稅亦無。"]', '诗', 'shi', '', NULL, '吳姬十首 六 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c47d99-d3fb-4c92-8186-be3bda410e9a', '吳姬十首 七', '吳姬十首 七', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["畫燭燒蘭暖復迷，殿幃深密下銀泥。","開門欲作侵晨散，已是明朝日向西。"]', '["畫燭燒蘭暖复迷，殿幃深密下銀泥。","开门欲作侵晨散，已是明朝日向西。"]', '诗', 'shi', '', NULL, '吳姬十首 七 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d09d0d-cb3b-4fbd-a369-bea9b472203d', '吳姬十首 八', '吳姬十首 八', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["樓臺重疊滿天雲，殷殷鳴鼉世上聞。","此日楊花初似雪，女兒弦管弄參軍。"]', '["楼台重叠满天云，殷殷鳴鼉世上闻。","此日楊花初似雪，女兒弦管弄參軍。"]', '诗', 'shi', '', NULL, '吳姬十首 八 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ccf740-3731-4449-9fb5-44e20b022b30', '吳姬十首 九', '吳姬十首 九', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["冠剪黃綃帔紫羅，薄施鉛粉畫青娥。","因將素手誇纖巧，從此椒房寵更多。"]', '["冠剪黄綃帔紫羅，薄施鉛粉畫青娥。","因將素手誇纖巧，從此椒房寵更多。"]', '诗', 'shi', '', NULL, '吳姬十首 九 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c67f8cc-b311-4798-9ea3-a02ebce7e333', '吳姬十首 十', '吳姬十首 十', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["身是三千第一名，內家叢裏獨分明。","芙蓉殿上中元日，水拍銀臺弄化生。"]', '["身是三千第一名，內家叢裏独分明。","芙蓉殿上中元日，水拍銀台弄化生。"]', '诗', 'shi', '', NULL, '吳姬十首 十 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370684bf-dd34-4d02-9ea7-e42789a0cca0', '題于公花園', '題于公花园', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["含桃莊主後園深，繁實初成靜掃陰。","若使明年花可待，應須惱破事花心。"]', '["含桃莊主後园深，繁實初成静掃陰。","若使明年花可待，應須惱破事花心。"]', '诗', 'shi', '', NULL, '題于公花園 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('038b65eb-9b5b-40af-86de-e02947a3b47e', '登城', '登城', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["偶作閑身上古城，路人遙望不相驚。","無端將吏逡巡至，又作都頭一隊行。"]', '["偶作闲身上古城，路人遙望不相驚。","無端將吏逡巡至，又作都头一隊行。"]', '诗', 'shi', '', NULL, '登城 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348706f7-15b7-4622-96be-bcef4f3369ec', '好客', '好客', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["好客連宵在醉鄉，蠟煙紅暖勝春光。","誰人肯信山僧語，寒雨唯煎治氣湯。"]', '["好客連宵在醉乡，蠟煙紅暖勝春光。","誰人肯信山僧語，寒雨唯煎治氣湯。"]', '诗', 'shi', '', NULL, '好客 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3902f9b-b4b5-4171-b8da-62758500aabf', '贈普恭禪師', '贈普恭禪師', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一日迢迢每一飡，我心難伏我無難。","南簷十月繩牀暖，背卷真經向日看。"]', '["一日迢迢每一飡，我心难伏我無难。","南簷十月繩牀暖，背卷真經向日看。"]', '诗', 'shi', '', NULL, '贈普恭禪師 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('873c2154-67e3-4223-9d08-83b011608bd8', '贈無表禪師', '贈無表禪師', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["笠戴圓陰楚地椶，磬敲清響蜀山銅。","秋來說偈寅朝殿，爽爽楊枝滿手風。"]', '["笠戴圓陰楚地椶，磬敲清响蜀山銅。","秋来说偈寅朝殿，爽爽楊枝满手风。"]', '诗', 'shi', '', NULL, '贈無表禪師 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('447e806a-406e-49b7-bca5-45978db07e68', '彭門偶題', '彭门偶題', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["淮王西舍固非夫，柳惲偏州未是都。","直到春秋諸列國，擁旄才子也應無。"]', '["淮王西舍固非夫，柳惲偏州未是都。","直到春秋諸列国，擁旄才子也應無。"]', '诗', 'shi', '', NULL, '彭門偶題 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46605d7a-4f84-4900-9017-210f267a64fa', '嘲趙璘', '嘲趙璘', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["巡關每傍摴蒲局，望月還登乞巧樓。","第一莫敎嬌太過，緣人衣帶上人頭。"]', '["巡关每傍摴蒲局，望月還登乞巧楼。","第一莫敎嬌太過，緣人衣带上人头。"]', '诗', 'shi', '', NULL, '嘲趙璘 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f44cd6d-266d-4232-a075-51d87b80dfe5', '句', '句', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["百首如一首，卷初如卷終。","坐久僕頭出，語多僧齒寒。","西塞長雲盡，南湖片月斜。","李白終無取，陶潛固不刊。","我身若在開元日，爭遣名爲李翰林。"]', '["百首如一首，卷初如卷終。","坐久僕头出，語多僧齒寒。","西塞长云尽，南湖片月斜。","李白終無取，陶潛固不刊。","我身若在开元日，爭遣名爲李翰林。"]', '诗', 'shi', '', NULL, '句 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03b763c-fd98-4e42-b4b8-3d62030aa7eb', '早春', '早春', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["曉來庭戶外，草樹似依依。","一夜東風起，萬山春色歸。","冰消泉派動，日暖露珠晞。","已醞看花酒，嬌鶯莫預飛。"]', '["晓来庭戶外，草樹似依依。","一夜东风起，万山春色归。","冰消泉派动，日暖露珠晞。","已醞看花酒，嬌鶯莫預飞。"]', '诗', 'shi', '', NULL, '早春 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f657ed-4a19-4456-a596-ab719f5cacc6', '傷春感懷', '傷春感懷', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["花飛惜不得，年長更堪悲。","春盡有歸日，老來無去時。","風前千片雪，鏡裏數莖絲。","腸斷青山暮，獨攀楊柳枝。"]', '["花飞惜不得，年长更堪悲。","春尽有归日，老来無去时。","风前千片雪，镜裏數莖絲。","腸斷青山暮，独攀楊柳枝。"]', '诗', 'shi', '', NULL, '傷春感懷 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45dc8ca6-5d43-4e30-84f6-45feda11d5ed', '閏三月', '閏三月', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["三年皆一閏，此閏勝常時。","莫怪花開晚，都緣春盡遲。","節分炎氣近，律應蕙風移。","夢得成胡蝶，芳菲幸不遺。"]', '["三年皆一閏，此閏勝常时。","莫怪花开晚，都緣春尽遲。","節分炎氣近，律應蕙风移。","梦得成胡蝶，芳菲幸不遺。"]', '诗', 'shi', '', NULL, '閏三月 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810dbe7f-09aa-45d5-b727-7b761660a70c', '早秋遊湖上亭', '早秋游湖上亭', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["危亭秋尚早，野思已無窮。","竹葉一尊酒，荷香四座風。","曉煙孤嶼外，歸鳥夕陽中。","漸愛湖光冷，移舟月滿空。"]', '["危亭秋尚早，野思已無窮。","竹葉一尊酒，荷香四座风。","晓煙孤嶼外，归鸟夕陽中。","漸愛湖光冷，移舟月满空。"]', '诗', 'shi', '', NULL, '早秋遊湖上亭 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14703bf5-d8a6-4107-a57c-07add19ecd85', '宿漁家', '宿漁家', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["竹屋清江上，風煙四五家。","水園分芰葉，鄰界認蘆花。","雨到魚翻浪，洲迴鳥傍沙。","月明何處去，片片席帆斜。"]', '["竹屋清江上，风煙四五家。","水园分芰葉，鄰界認蘆花。","雨到鱼翻浪，洲迴鸟傍沙。","月明何处去，片片席帆斜。"]', '诗', 'shi', '', NULL, '宿漁家 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf41d1b-b03d-408a-804f-43a6e4dae6ac', '旅中早秋', '旅中早秋', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["金威生止水，爽氣遍遙空。","草色蕭條路，槐花零落風。","夜來萬里月，覺後一聲鴻。","莫問前程事，颯然沙上蓬。"]', '["金威生止水，爽氣遍遙空。","草色蕭條路，槐花零落风。","夜来万里月，覺後一声鴻。","莫问前程事，颯然沙上蓬。"]', '诗', 'shi', '', NULL, '旅中早秋 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('871701ca-3791-454c-a3e7-34f91aa8951b', '早秋西歸有懷', '早秋西归有懷', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["求歸方有計，惜別更堪愁。","上馬江城暮，出郊山戍秋。","暗銷何限事，白盡去年頭。","莫怪頻惆悵，異鄉難再遊。"]', '["求归方有計，惜別更堪愁。","上马江城暮，出郊山戍秋。","暗銷何限事，白尽去年头。","莫怪頻惆悵，異乡难再游。"]', '诗', 'shi', '', NULL, '早秋西歸有懷 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('484e4b8b-1f12-4c49-b5a2-717d8d1b9685', '冬夜旅懷', '冬夜旅懷', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["寒窗危竹枕，月過半牀陰。","嫩葉不歸夢，晴蟲成苦吟。","酒無通夜力，事滿五更心。","寂寞誰相似，殘燈與素琴。"]', '["寒窗危竹枕，月過半牀陰。","嫩葉不归梦，晴蟲成苦吟。","酒無通夜力，事满五更心。","寂寞誰相似，殘灯與素琴。"]', '诗', 'shi', '', NULL, '冬夜旅懷 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8298cc54-e826-4ca8-bf6b-8285dbce5378', '塞上作', '塞上作', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["蕭蕭隴水側，落日客愁中。","古塞一聲笛，長沙千里風。","鳥無棲息處，人愛戰爭功。","數夜城頭月，彎彎如引弓。"]', '["蕭蕭隴水側，落日客愁中。","古塞一声笛，长沙千里风。","鸟無棲息处，人愛戰爭功。","數夜城头月，彎彎如引弓。"]', '诗', 'shi', '', NULL, '塞上作 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ec25f7-53f6-4bf5-ad93-ef3ee28c4761', '秋日寄陳景孚秀才', '秋日寄陳景孚秀才', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["征車日已遠，物候尚淒淒。","風葉青桐落，露花紅槿低。","心隨秦國遠，夢到楚山迷。","却恨銜蘆鴈，秋飛不向西。"]', '["征车日已远，物候尚淒淒。","风葉青桐落，露花紅槿低。","心隨秦国远，梦到楚山迷。","却恨銜蘆鴈，秋飞不向西。"]', '诗', 'shi', '', NULL, '秋日寄陳景孚秀才 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8da3899-c3ad-4b5f-ab8a-2b6ab3ca02da', '冬日送友人西歸', '冬日送友人西归', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["北風吹別思，杳杳度雲山。","滿望是歸處，一生猶未閑。","知音方見譽，浮宦久相關。","空有心如月，同居千里還。"]', '["北风吹別思，杳杳度云山。","满望是归处，一生猶未闲。","知音方见譽，浮宦久相关。","空有心如月，同居千里還。"]', '诗', 'shi', '', NULL, '冬日送友人西歸 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa752425-61bf-4baf-b534-608c2001b353', '感寓', '感寓', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["海竭山移歲月深，分明齊得世人心。","顏回徒恨少成古，彭祖何曾老至今。","須向道中平貴賤，還從限內任浮沈。","他年免似驪山鬼，信有蓬萊不可尋。"]', '["海竭山移歲月深，分明齊得世人心。","顏回徒恨少成古，彭祖何曾老至今。","須向道中平貴賤，還從限內任浮沈。","他年免似驪山鬼，信有蓬萊不可尋。"]', '诗', 'shi', '', NULL, '感寓 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85fcb8b2-075f-4635-95b5-c14e815fabdc', '七夕', '七夕', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["烏鵲橋成上界通，千秋靈會此宵同。","雲收喜氣星樓曉，香拂輕塵玉殿空。","翠輦不行青草路，金鑾徒候白榆風。","綵盤花閣無窮意，只在遊絲一縷中。"]', '["烏鵲橋成上界通，千秋靈會此宵同。","云收喜氣星楼晓，香拂轻塵玉殿空。","翠輦不行青草路，金鑾徒候白榆风。","綵盤花閣無窮意，只在游絲一縷中。"]', '诗', 'shi', '', NULL, '七夕 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d24ac9-126d-4870-8599-9173734f7686', '晚春陪王員外東塘遊宴', '晚春陪王員外东塘游宴', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["水綠山青春日長，政成因暇泛回塘。","初移柳岸笙歌合，欲過蘋洲羅綺香。","共濟已驚依玉樹，隨流還許醉金觴。","一聲畫角嚴城暮，雲雨分時滿路光。"]', '["水綠山青春日长，政成因暇泛回塘。","初移柳岸笙歌合，欲過蘋洲羅綺香。","共濟已驚依玉樹，隨流還許醉金觴。","一声畫角嚴城暮，云雨分时满路光。"]', '诗', 'shi', '', NULL, '晚春陪王員外東塘遊宴 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49234525-7774-497c-9d13-0c70403e9b74', '遊東湖黃處士園林', '游东湖黄处士园林', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["偶向東湖更向東，數聲雞犬翠微中。","遙知楊柳是門處，似隔芙蓉無路通。","樵客出來山帶雨，漁舟過去水生風。","物情多與閑相稱，所恨求安計不同。"]', '["偶向东湖更向东，數声雞犬翠微中。","遙知楊柳是门处，似隔芙蓉無路通。","樵客出来山带雨，漁舟過去水生风。","物情多與闲相稱，所恨求安計不同。"]', '诗', 'shi', '', NULL, '遊東湖黃處士園林 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024a6b65-b543-41cc-89eb-af2f33164db1', '題許子正處士新池', '題許子正处士新池', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["坐愛風塵日已西，功成得與化工齊。","巧分孤島思何遠，欲似五湖心易迷。","漸有野禽來試水，又憐春草自侵隄。","那堪更到芙蓉拆，晚夕香聯桃李蹊。"]', '["坐愛风塵日已西，功成得與化工齊。","巧分孤島思何远，欲似五湖心易迷。","漸有野禽来試水，又怜春草自侵隄。","那堪更到芙蓉拆，晚夕香聯桃李蹊。"]', '诗', 'shi', '', NULL, '題許子正處士新池 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb760b4c-60d5-46e3-82df-c0edf0ac55ee', '旅懷', '旅懷', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["物態人心漸渺茫，十年徒學釣滄浪。","老將何面還吾土，夢有驚魂在楚鄉。","自是一身嫌苟合，誰憐今日欲佯狂。","無名無位却無事，醉落烏紗臥夕陽。"]', '["物態人心漸渺茫，十年徒学釣滄浪。","老將何面還吾土，梦有驚魂在楚乡。","自是一身嫌苟合，誰怜今日欲佯狂。","無名無位却無事，醉落烏紗臥夕陽。"]', '诗', 'shi', '', NULL, '旅懷 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9dbd1b1-59b8-407c-869f-aaf7f96f53ea', '早秋歸', '早秋归', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["數口飄零身未迴，夢魂遙斷越王臺。","家書欲寄鴈飛遠，客恨正深秋又來。","風解綠楊三署冷，月當銀漢四山開。","茫茫歸路在何處，砧杵一聲心已摧。"]', '["數口飄零身未迴，梦魂遙斷越王台。","家书欲寄鴈飞远，客恨正深秋又来。","风解綠楊三署冷，月當銀漢四山开。","茫茫归路在何处，砧杵一声心已摧。"]', '诗', 'shi', '', NULL, '早秋歸 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996c3dca-9022-4c10-bd7a-dc189359052c', '歐陽示新詩因貽四韻', '歐陽示新诗因貽四韻', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["衝戛瑤瓊得至音，數篇清越應南金。","都由苦思無休日，已證前賢不到心。","風入寒松聲自古，水歸滄海意皆深。","欲知字字驚神鬼，一氣秋時試夜吟。"]', '["衝戛瑤瓊得至音，數篇清越應南金。","都由苦思無休日，已證前賢不到心。","风入寒松声自古，水归滄海意皆深。","欲知字字驚神鬼，一氣秋时試夜吟。"]', '诗', 'shi', '', NULL, '歐陽示新詩因貽四韻 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c1476c-fbf9-4134-8ccb-8b16b09251d3', '尉遲將軍', '尉遲將軍', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["天仗擁門希授鉞，重臣入夢豈安金。","江河定後威風在，社稷危來寄託深。","扶病暫將弓試力，感恩重與劍論心。","明妃若遇英雄世，青塚何由怨陸沈。"]', '["天仗擁门希授鉞，重臣入梦豈安金。","江河定後威风在，社稷危来寄託深。","扶病暫將弓試力，感恩重與劍論心。","明妃若遇英雄世，青塚何由怨陸沈。"]', '诗', 'shi', '', NULL, '尉遲將軍 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b41a2ac6-bb1b-48e2-9da5-c75b3164e8c9', '贈歐陽秀才', '贈歐陽秀才', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["桐上知音日下身，道光誰不仰清塵。","偶來水館逢爲客，舊熟詩名似故人。","永日空驚滄海闊，何年重見白頭新。","權門要路應行遍，閑伴山夫一夜貧。"]', '["桐上知音日下身，道光誰不仰清塵。","偶来水館逢爲客，旧熟诗名似故人。","永日空驚滄海闊，何年重见白头新。","權门要路應行遍，闲伴山夫一夜貧。"]', '诗', 'shi', '', NULL, '贈歐陽秀才 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03cee168-b83e-4483-89f3-a27a200e5f2a', '贈道者', '贈道者', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["五雲深處有真仙，歲月催多却少年。","入郭不知今世事，賣丹猶覓古時錢。","閑尋白鹿眠瑤草，暗摘紅桃去洞天。","時向人間深夜坐，鬼神長在藥囊邊。"]', '["五云深处有真仙，歲月催多却少年。","入郭不知今世事，賣丹猶覓古时錢。","闲尋白鹿眠瑤草，暗摘紅桃去洞天。","时向人间深夜坐，鬼神长在藥囊邊。"]', '诗', 'shi', '', NULL, '贈道者 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd3c1be-a415-4895-b77c-e3e454593219', '贈道者', '贈道者', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["道帔輕裾三島雲，綠髯長占鏡中春。","高風已駕祥鸞馭，浮世休驚野馬塵。","過海獨辭王母面，度關誰識老聃身。","儒生也愛長生術，不見人間大笑人。"]', '["道帔轻裾三島云，綠髯长占镜中春。","高风已駕祥鸾馭，浮世休驚野马塵。","過海独辞王母面，度关誰識老聃身。","儒生也愛长生術，不见人间大笑人。"]', '诗', 'shi', '', NULL, '贈道者 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('289759a9-5897-415d-a4d7-4a4e59a3035c', '遣懷寄歐陽秀才', '遣懷寄歐陽秀才', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["地上江河天上烏，百年流轉只須臾。","平生閑過日將日，欲老始知吾負吾。","似豹一班時或有，如龜三顧豈全無。","古來晚達人何限，莫笑空枝猶望蘇。"]', '["地上江河天上烏，百年流轉只須臾。","平生闲過日將日，欲老始知吾負吾。","似豹一班时或有，如龟三顧豈全無。","古来晚達人何限，莫笑空枝猶望蘇。"]', '诗', 'shi', '', NULL, '遣懷寄歐陽秀才 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8420503-eea9-47b8-a839-04d8d4f9cd7e', '送元秀才入道', '送元秀才入道', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["不教榮樂損天機，願逐鸞皇次第飛。","明月滿時開道帔，俗塵飄處脫儒衣。","只攜仙籍還金洞，便與時流隔翠微。","空有緘題報親愛，一千年後始西歸。"]', '["不教榮乐損天機，願逐鸾皇次第飞。","明月满时开道帔，俗塵飄处脫儒衣。","只携仙籍還金洞，便與时流隔翠微。","空有緘題報親愛，一千年後始西归。"]', '诗', 'shi', '', NULL, '送元秀才入道 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25ad1fe-c20e-494b-9fbf-234bd6de9d6c', '三閭大夫', '三閭大夫', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["三閭一去湘山老，煙水悠悠痛古今。","青史已書殷鑒在，詞人勞詠楚江深。","竹移低影潛貞節，月入中流洗恨心。","再引離騷見微旨，肯敎漁父會昇沈。"]', '["三閭一去湘山老，煙水悠悠痛古今。","青史已书殷鑒在，词人勞詠楚江深。","竹移低影潛貞節，月入中流洗恨心。","再引離騷见微旨，肯敎漁父會昇沈。"]', '诗', 'shi', '', NULL, '三閭大夫 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('493f71a1-febe-4c30-ab39-163afd3c387f', '傷曾秀才馬', '傷曾秀才马', '693b6381-62cd-442f-96f9-815fdf18a782', '唐', '["買得龍媒越水濆，輕桃細杏色初分。","秋歸未過陽關日，夜魄忽銷陰塞雲。","吳練已知隨影沒，朔風猶想帶嘶聞。","臨軒振策休惆悵，坐致煙霄只在君。"]', '["買得龙媒越水濆，轻桃細杏色初分。","秋归未過陽关日，夜魄忽銷陰塞云。","吳練已知隨影沒，朔风猶想带嘶闻。","臨軒振策休惆悵，坐致煙霄只在君。"]', '诗', 'shi', '', NULL, '傷曾秀才馬 劉威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb7a007-7ef8-487d-a000-aa47b2381cab', '噴玉泉冥會詩八首 白衣叟途中吟二首 一', '噴玉泉冥會诗八首 白衣叟途中吟二首 一', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["春草萋萋春水綠，野棠開盡飄香玉。","繡嶺宮前鶴髮人，猶唱開元太平曲。"]', '["春草萋萋春水綠，野棠开尽飄香玉。","繡嶺宮前鹤髮人，猶唱开元太平曲。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 白衣叟途中吟二首 一 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5df52bd-c35e-4d7f-bf3f-779d4fed5aec', '噴玉泉冥會詩八首 白衣叟途中吟二首 二', '噴玉泉冥會诗八首 白衣叟途中吟二首 二', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["厭世逃名者，誰能荅姓名。","曾聞王樂否，眷取路傍情。"]', '["厭世逃名者，誰能荅姓名。","曾闻王乐否，眷取路傍情。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 白衣叟途中吟二首 二 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7188b2-7f76-4197-a68b-f7f86d8271e0', '噴玉泉冥會詩八首 白衣叟述甘棠館西楹詩', '噴玉泉冥會诗八首 白衣叟述甘棠館西楹诗', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["浮雲淒慘日微明，沈痛將軍負罪名。","白晝叫閽無近戚，縞衣飲氣只門生。","佳人暗泣填宮淚，廐馬連嘶換主聲。","六合茫茫皆漢土，此身無處哭田橫。"]', '["浮云淒慘日微明，沈痛將軍負罪名。","白晝叫閽無近戚，縞衣饮氣只门生。","佳人暗泣填宮泪，廐马連嘶換主声。","六合茫茫皆漢土，此身無处哭田橫。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 白衣叟述甘棠館西楹詩 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d67904a-b7bb-4b9b-9f68-4495b7582f87', '噴玉泉冥會詩八首 白衣叟噴玉泉感舊遊書懷', '噴玉泉冥會诗八首 白衣叟噴玉泉感旧游书懷', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["樹色川光向晚晴，舊曾遊處事分明。","鼠穿月榭荆榛合，草掩花園畦壠平。","迹陷黃沙仍未寤，罪標青簡竟何名。","傷心谷口東流水，猶噴當時寒玉聲。"]', '["樹色川光向晚晴，旧曾游处事分明。","鼠穿月榭荆榛合，草掩花园畦壠平。","迹陷黄沙仍未寤，罪標青簡竟何名。","傷心谷口东流水，猶噴當时寒玉声。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 白衣叟噴玉泉感舊遊書懷 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3406400f-2968-42f3-b8c2-d86a1110bcca', '噴玉泉冥會詩八首 四丈夫同賦 一', '噴玉泉冥會诗八首 四丈夫同賦 一', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["鳥啼鶯語思何窮，一世榮華一夢中。","李固有冤藏蠹簡，鄧攸無子續清風。","文章高韻傳流水，絲管遺音託草蟲。","春月不知人事改，閑垂光影照洿宮。"]', '["鸟啼鶯語思何窮，一世榮华一梦中。","李固有冤藏蠹簡，鄧攸無子續清风。","文章高韻傳流水，絲管遺音託草蟲。","春月不知人事改，闲垂光影照洿宮。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 四丈夫同賦 一 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152eed2d-cad2-48e0-99c6-dee08508c5d4', '噴玉泉冥會詩八首 四丈夫同賦 二', '噴玉泉冥會诗八首 四丈夫同賦 二', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["桃蹊李徑盡荒涼，訪舊尋新益自傷。","雖有衣衾藏李固，終無表疏雪王章。","羈魂尚覺霜風冷，朽骨徒驚月桂香。","天爵竟爲人爵悞，誰能高叫問蒼蒼。"]', '["桃蹊李徑尽荒涼，訪旧尋新益自傷。","雖有衣衾藏李固，終無表疏雪王章。","羈魂尚覺霜风冷，朽骨徒驚月桂香。","天爵竟爲人爵悞，誰能高叫问蒼蒼。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 四丈夫同賦 二 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de058199-5b27-4b87-a078-d6dfab9d5283', '噴玉泉冥會詩八首 四丈夫同賦 三', '噴玉泉冥會诗八首 四丈夫同賦 三', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["落花寂寂草綿綿，雲影山光盡宛然。","壞室基摧新石鼠，瀦宮水引故山泉。","青雲自致慚天爵，白首同[歸]感昔賢。","惆悵林間中夜月，孤光曾照讀書筵。"]', '["落花寂寂草綿綿，云影山光尽宛然。","壞室基摧新石鼠，瀦宮水引故山泉。","青云自致慚天爵，白首同[归]感昔賢。","惆悵林间中夜月，孤光曾照读书筵。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 四丈夫同賦 三 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a865837-f2a7-4c0a-a5ce-8b2896663827', '噴玉泉冥會詩八首 四丈夫同賦 四', '噴玉泉冥會诗八首 四丈夫同賦 四', '336fd55e-0a21-47f8-8ab4-df6b67460d62', '唐', '["新荆棘路舊衡門，又駐高車會一尊。","寒骨未沾新雨露，春風不長敗蘭蓀。","丹誠豈分埋幽壤，白日終希照覆盆。","珍重昔年金谷友，共來泉際話幽魂。"]', '["新荆棘路旧衡门，又駐高车會一尊。","寒骨未沾新雨露，春风不长敗蘭蓀。","丹誠豈分埋幽壤，白日終希照覆盆。","珍重昔年金谷友，共来泉際話幽魂。"]', '诗', 'shi', '', NULL, '噴玉泉冥會詩八首 四丈夫同賦 四 李玖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a44dc3e3-bee8-4523-a1d8-3288fdf0f825', '下第歸宜春酬黃頗餞別', '下第归宜春酬黄頗餞別', 'a0971b88-effe-495d-98c4-65ddef9c2431', '唐', '["聖代澄清雨露均，獨懷惆悵出咸秦。","承明未薦相如賦，故國猶慚季子貧。","御苑鐘聲臨遠水，都門樹色背行塵。","一從此地曾攜手，益羨江頭桃李春。"]', '["聖代澄清雨露均，独懷惆悵出咸秦。","承明未薦相如賦，故国猶慚季子貧。","御苑鐘声臨远水，都门樹色背行塵。","一從此地曾携手，益羨江头桃李春。"]', '诗', 'shi', '', NULL, '下第歸宜春酬黃頗餞別 潘唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5164d760-c21f-4e5c-9d3f-67032ab8ccb7', '題泐潭', '題泐潭', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["泐潭形勝地，祖塔在雲湄。","浩劫有窮日，真風無墜時。","歲華空自老，消息竟誰知。","到此輕塵慮，功名自可遺。"]', '["泐潭形勝地，祖塔在云湄。","浩劫有窮日，真风無墜时。","歲华空自老，消息竟誰知。","到此轻塵慮，功名自可遺。"]', '诗', 'shi', '', NULL, '題泐潭 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c7b7b4-11e4-491a-81d7-8f3eff674928', '贈黃蘖山僧希運', '贈黄蘖山僧希運', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["曾傳達士心中印，額有圓珠七尺身。","挂錫十年棲蜀水，浮杯今日渡漳濱。","一千龍象隨高步，萬里香華結勝因。","擬欲事師爲弟子，不知將法付何人。"]', '["曾傳達士心中印，額有圓珠七尺身。","挂錫十年棲蜀水，浮杯今日渡漳濱。","一千龙象隨高步，万里香华結勝因。","擬欲事師爲弟子，不知將法付何人。"]', '诗', 'shi', '', NULL, '贈黃蘖山僧希運 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44517169-5297-4342-a322-9353c0d329cd', '登望京樓賦', '登望京楼賦', '8dbdb98a-ca4d-4c01-b86b-59a22c9e9ea7', '唐', '["夷門一鎮五經秋，未得朝天不免愁。","因上此樓望京國，便名樓作望京樓。"]', '["夷门一鎮五經秋，未得朝天不免愁。","因上此楼望京国，便名楼作望京楼。"]', '诗', 'shi', '', NULL, '登望京樓賦 令狐綯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2def3636-f6a8-4cbd-8eec-49e944e6b24e', '享太廟樂章', '享太廟乐章', 'f86bca6c-0179-4ff7-b80b-6e3cde37ecdc', '唐', '["於鑠令主，聖祚重昌。","興起敎義，申明典章。","俗尚素朴，人皆樂康。","積德可報，流慶無疆。"]', '["於鑠令主，聖祚重昌。","兴起敎義，申明典章。","俗尚素朴，人皆乐康。","積德可報，流慶無疆。"]', '诗', 'shi', '', NULL, '享太廟樂章 夏侯孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8100633a-14fe-47d6-b018-e6341dc437b8', '和重陽錫宴御製詩', '和重陽錫宴御製诗', 'bd84a5ee-b988-4506-9458-91520db6f7cf', '唐', '["四方無事去，宸豫杪秋來。","八水寒光起，千山霽色開。"]', '["四方無事去，宸豫杪秋来。","八水寒光起，千山霽色开。"]', '诗', 'shi', '', NULL, '和重陽錫宴御製詩 魏謩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63263b60-508c-4daa-8f71-7d017e2d453c', '賀王僕射放榜', '賀王僕射放榜', 'd77376a5-1ab8-43c0-b281-def605726ee0', '唐', '["文場三化魯儒生，三十餘年振重名。","曾忝木雞誇羽翼，又陪金馬入蓬瀛。","雖欣月桂居先折，更羨春蘭最後榮。","欲到龍門看風雨，關防不許暫離營。"]', '["文場三化魯儒生，三十餘年振重名。","曾忝木雞誇羽翼，又陪金马入蓬瀛。","雖欣月桂居先折，更羨春蘭最後榮。","欲到龙门看风雨，关防不許暫離營。"]', '诗', 'shi', '', NULL, '賀王僕射放榜 周墀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c69e1496-2c52-4632-9bd5-505488cb9f4a', '酬李常侍立秋日奉詔祭嶽見寄', '酬李常侍立秋日奉詔祭嶽见寄', 'd77376a5-1ab8-43c0-b281-def605726ee0', '唐', '["秋祠靈嶽奉尊罍，風過深林古柏開。","蓮掌月高珪幣列，金天雨露鬼神陪。","質明三獻雖終禮，祈壽千年別上杯。","豈是瑣才能祀事，洪農太守主張來。"]', '["秋祠靈嶽奉尊罍，风過深林古柏开。","蓮掌月高珪幣列，金天雨露鬼神陪。","質明三獻雖終禮，祈壽千年別上杯。","豈是瑣才能祀事，洪農太守主張来。"]', '诗', 'shi', '', NULL, '酬李常侍立秋日奉詔祭嶽見寄 周墀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd4d29e-5e2b-45f2-9c7c-f1f50932a87d', '寄華州周侍郎立秋日奉詔祭嶽詩', '寄华州周侍郎立秋日奉詔祭嶽诗', 'fcc0e24c-d31f-4d13-a7fa-9c8b87ef7b86', '唐', '["關河豁靜曉雲開，承詔秋祠太守來。","山霽蓮花添翠黛，路陰桐葉少塵埃。","朱轓入廟威儀肅，玉佩昇壇步武回。","往歲今朝幾時事，謝君非重我非才。"]', '["关河豁静晓云开，承詔秋祠太守来。","山霽蓮花添翠黛，路陰桐葉少塵埃。","朱轓入廟威儀肅，玉佩昇壇步武回。","往歲今朝幾时事，謝君非重我非才。"]', '诗', 'shi', '', NULL, '寄華州周侍郎立秋日奉詔祭嶽詩 李景讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633ff2e6-edbc-4e31-87ea-c233f5b8f470', '句', '句', 'fcc0e24c-d31f-4d13-a7fa-9c8b87ef7b86', '唐', '["成都十萬戶，拋若一鴻毛。"]', '["成都十万戶，拋若一鴻毛。"]', '诗', 'shi', '', NULL, '句 李景讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b5578d-ebd4-41f9-a0e2-6fc5cf53f1b6', '續夢中十韻', '續梦中十韻', '4c2e87e6-d872-4267-9660-33f1023a1aad', '唐', '["間歲流虹節，歸軒出禁扃。","奔波陶畏景，蕭灑夢殊庭。","境象非曾到，崇嚴昔未經。","日斜烏斂翼，風動鶴飄翎。","異苑人爭集，涼臺筆不停。","石門霧露白，玉殿莓苔青。","若匪災先兆，何緣思入冥。","御爐虛仗馬，華蓋負云亭。","白日成千古，金縢閟九齡。","小臣哀絕筆，湖上泣青萍。"]', '["间歲流虹節，归軒出禁扃。","奔波陶畏景，蕭灑梦殊庭。","境象非曾到，崇嚴昔未經。","日斜烏斂翼，风动鹤飄翎。","異苑人爭集，涼台笔不停。","石门霧露白，玉殿莓苔青。","若匪災先兆，何緣思入冥。","御爐虛仗马，华蓋負云亭。","白日成千古，金縢閟九齡。","小臣哀絕笔，湖上泣青萍。"]', '诗', 'shi', '', NULL, '續夢中十韻 鄭顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809ea1ce-bc9d-4ffa-82da-323b7b6009cc', '揚州送人', '揚州送人', '4c2e87e6-d872-4267-9660-33f1023a1aad', '唐', '["桂檝木蘭舟，楓江竹箭流。","故人從此去，望遠不勝愁。","落日低帆影，歸風引櫂謳。","思君折楊柳，淚盡武昌樓。"]', '["桂檝木蘭舟，楓江竹箭流。","故人從此去，望远不勝愁。","落日低帆影，归风引櫂謳。","思君折楊柳，泪尽武昌楼。"]', '诗', 'shi', '', NULL, '揚州送人 鄭顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03dbc38b-82e8-4c7e-9e4e-92239a64e52a', '置酒', '置酒', '4c2e87e6-d872-4267-9660-33f1023a1aad', '唐', '["酒熟人須飲，春還鬢已秋。","願逢千日醉，得逭百年愁。","卒卒周姬旦，棲棲魯孔丘。","平生能幾日，不及且遨遊。"]', '["酒熟人須饮，春還鬢已秋。","願逢千日醉，得逭百年愁。","卒卒周姬旦，棲棲魯孔丘。","平生能幾日，不及且遨游。"]', '诗', 'shi', '', NULL, '置酒 鄭顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599897c4-0fbf-4317-aa8e-9b4eac949cb9', '重陽宴東觀山亭和從事盧順之', '重陽宴东观山亭和從事盧順之', 'fc2862a8-d8a8-4b72-b8de-09c253480688', '唐', '["亂山青翠郡城東，爽節憑高一望通。","交友會時絲管合，羽觴飛處笑言同。","金英耀彩晴雲外，玉樹凝霜暮雨中。","高詠已勞潘岳思，醉歡慙道自車公。"]', '["亂山青翠郡城东，爽節憑高一望通。","交友會时絲管合，羽觴飞处笑言同。","金英耀彩晴云外，玉樹凝霜暮雨中。","高詠已勞潘岳思，醉歡慙道自车公。"]', '诗', 'shi', '', NULL, '重陽宴東觀山亭和從事盧順之 張固 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c459a7f6-7383-4ba2-b37d-581af3a1c888', '獨秀山', '独秀山', 'fc2862a8-d8a8-4b72-b8de-09c253480688', '唐', '["孤峰不與衆山儔，直入青雲勢未休。","會得乾坤融結意，擎天一柱在南州。"]', '["孤峰不與衆山儔，直入青云勢未休。","會得乾坤融結意，擎天一柱在南州。"]', '诗', 'shi', '', NULL, '獨秀山 張固 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc1bf87-dc4b-47ae-9c49-e57c8cb338ba', '長門怨', '长门怨', '7de5a2b8-eed6-411f-9218-a652139b926d', '唐', '["營營孤思通，寂寂長門夜。","妾妬亦知非，君恩那不借。","攜琴就玉階，調悲聲未諧。","將心寄明月，流影入君懷。"]', '["營營孤思通，寂寂长门夜。","妾妬亦知非，君恩那不借。","携琴就玉階，調悲声未諧。","將心寄明月，流影入君懷。"]', '诗', 'shi', '', NULL, '長門怨 劉臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('328353d9-9592-461e-9cf7-23aaf3278024', '宿日觀東房詩', '宿日观东房诗', 'f030a83d-328b-4932-b6a7-b18d74435808', '唐', '["曾入桃溪路，仙源信少雙。","洞霞飄素練，蘚壁畫陰窗。","古木愁撐月，危峰欲墮江。","自吟空向寂，誰共倒秋缸。"]', '["曾入桃溪路，仙源信少雙。","洞霞飄素練，蘚壁畫陰窗。","古木愁撐月，危峰欲墮江。","自吟空向寂，誰共倒秋缸。"]', '诗', 'shi', '', NULL, '宿日觀東房詩 李質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1665f4-6069-4138-a632-748594019a13', '贈副戎', '贈副戎', '125cece1-6fdf-4b44-a82b-76c46de9c38e', '唐', '["翱翔曾在玉京天，墮落江南路幾千。","從事不須輕縣宰，滿身猶帶御爐煙。"]', '["翱翔曾在玉京天，墮落江南路幾千。","從事不須轻縣宰，满身猶带御爐煙。"]', '诗', 'shi', '', NULL, '贈副戎 南卓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041d1573-4861-4954-8588-483813699dfc', '命妓盛小叢歌餞崔侍御還闕', '命妓盛小叢歌餞崔侍御還闕', 'd267d361-511e-444f-a9e3-314c904ca151', '唐', '["繡衣奔命去情多，南國佳人斂翠娥。","曾向敎坊聽國樂，爲君重唱盛叢歌。"]', '["繡衣奔命去情多，南国佳人斂翠娥。","曾向敎坊听国乐，爲君重唱盛叢歌。"]', '诗', 'shi', '', NULL, '命妓盛小叢歌餞崔侍御還闕 李訥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb7f3217-29dc-4db3-ae21-918a6fb16cd8', '李尚書命妓歌餞有作奉酬', '李尚书命妓歌餞有作奉酬', '7bd3e084-be3d-480e-8302-1a38eac55d3c', '唐', '["羊公留宴峴山亭，洛浦高歌五夜情。","獨向柏臺爲老吏，可憐林木響餘聲。"]', '["羊公留宴峴山亭，洛浦高歌五夜情。","独向柏台爲老吏，可怜林木响餘声。"]', '诗', 'shi', '', NULL, '李尚書命妓歌餞有作奉酬 崔元範 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e5cedf-c395-497f-82c2-030f029f9ad7', '和李尚書命妓歌餞崔侍御', '和李尚书命妓歌餞崔侍御', 'fd57843f-5118-42f0-b2d8-0a489b223b8b', '唐', '["燕趙能歌有幾人，爲花回雪似含顰。","聲隨御史西歸去，誰伴文翁怨九春。"]', '["燕趙能歌有幾人，爲花回雪似含顰。","声隨御史西归去，誰伴文翁怨九春。"]', '诗', 'shi', '', NULL, '和李尚書命妓歌餞崔侍御 楊知至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e786fff-7dcb-4ba8-92b6-fc847895c08d', '覆落後呈同年', '覆落後呈同年', 'fd57843f-5118-42f0-b2d8-0a489b223b8b', '唐', '["由來梁鴈與冥鴻，不合翩翩向碧空。","寒谷謾勞鄒氏律，長天獨遇宋都風。","此時泣玉情雖異，他日銜環事亦同。","二月春光正搖蕩，無因得醉杏園中。"]', '["由来梁鴈與冥鴻，不合翩翩向碧空。","寒谷謾勞鄒氏律，长天独遇宋都风。","此时泣玉情雖異，他日銜环事亦同。","二月春光正搖蕩，無因得醉杏园中。"]', '诗', 'shi', '', NULL, '覆落後呈同年 楊知至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae85d8a3-368c-45d3-8d80-87c5f4a55d5d', '送韋覲謫潘州', '送韋覲謫潘州', '88517230-64d6-4722-a0ea-3b397c3d4433', '唐', '["北鳥飛不到，南人誰去遊。","天涯浮瘴水，嶺外向潘州。","草木春秋暮，猨猱日夜愁。","定知遷客淚，應只對君流。"]', '["北鸟飞不到，南人誰去游。","天涯浮瘴水，嶺外向潘州。","草木春秋暮，猨猱日夜愁。","定知遷客泪，應只对君流。"]', '诗', 'shi', '', NULL, '送韋覲謫潘州 李明遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c28eb6a-8b42-4620-b354-a1fdc0dfc40d', '前望江麴令頌德', '前望江麴令頌德', '5f6ac007-b83c-4b12-88db-e856ca846c8a', '唐', '["政績雖殊道且同，無辭買石紀前功。","誰論重德光青史，過里猶歌臥轍風。"]', '["政績雖殊道且同，無辞買石紀前功。","誰論重德光青史，過里猶歌臥轍风。"]', '诗', 'shi', '', NULL, '前望江麴令頌德 蕭縝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccff905a-706e-4da7-8ba5-2ada7121f184', '重陽東觀席上贈侍郎張固', '重陽东观席上贈侍郎張固', '609aa02e-8b57-4344-b1fe-919735e89d7f', '唐', '["渡江旌斾動魚龍，令節開筵上碧峰。","翡翠巢低巖桂小，茱萸房濕露香濃。","白雲郊外無塵事，黃菊筵中盡醉容。","好是謝公高興處，夕陽歸騎出疎松。"]', '["渡江旌斾动鱼龙，令節开筵上碧峰。","翡翠巢低巖桂小，茱萸房濕露香濃。","白云郊外無塵事，黄菊筵中尽醉容。","好是謝公高兴处，夕陽归騎出疎松。"]', '诗', 'shi', '', NULL, '重陽東觀席上贈侍郎張固 盧順之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('885563d2-7709-4281-9da7-ac3b0edfa006', '責漢水辭', '責漢水辞', 'f12245fb-44f4-4516-ba77-51ab4cd3e57a', '唐', '["漢之廣兮，風波四起。","雖有風波，不如蹄涔之水。","蹄涔之水，不爲下國而傾天子。","漢之深兮，其隄莫量。","雖云莫量，不如行潦之汪。","行潦之汪，不爲下國而溺天王。","漢之美者曰魴，吾雖饑不食其魴，恐污吾之饑腸。"]', '["漢之廣兮，风波四起。","雖有风波，不如蹄涔之水。","蹄涔之水，不爲下国而傾天子。","漢之深兮，其隄莫量。","雖云莫量，不如行潦之汪。","行潦之汪，不爲下国而溺天王。","漢之美者曰魴，吾雖饑不食其魴，恐污吾之饑腸。"]', '诗', 'shi', '', NULL, '責漢水辭 李善夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b78a8472-7a4d-44ac-9599-931876a69d40', '大隄曲', '大隄曲', 'f12245fb-44f4-4516-ba77-51ab4cd3e57a', '唐', '["酒旗相望大隄頭，隄下連牆隄上樓。","日暮行人爭渡急，槳聲幽軋滿中流。"]', '["酒旗相望大隄头，隄下連牆隄上楼。","日暮行人爭渡急，槳声幽軋满中流。"]', '诗', 'shi', '', NULL, '大隄曲 李善夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d30af02-1a4f-4dd6-9756-5b5a0568261f', '金燈', '金灯', '76771adf-af60-4c28-b753-db2d84ef13d5', '唐', '["疎莖秋擁翠，幽豔夕添紅。","有月長燈在，無煙燼火同。","香濃初受露，勢庳不知風。","應笑金臺上，先隨曉漏終。"]', '["疎莖秋擁翠，幽豔夕添紅。","有月长灯在，無煙燼火同。","香濃初受露，勢庳不知风。","應笑金台上，先隨晓漏終。"]', '诗', 'shi', '', NULL, '金燈 盧溵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458e1358-a003-481f-9a53-a4836419dcfa', '和李尚書命妓餞崔侍御', '和李尚书命妓餞崔侍御', '76771adf-af60-4c28-b753-db2d84ef13d5', '唐', '["烏臺上客紫髯公，共捧天書靜境中。","桃朵不辭歌白苧，耶溪暮雨起樵風。"]', '["烏台上客紫髯公，共捧天书静境中。","桃朵不辞歌白苧，耶溪暮雨起樵风。"]', '诗', 'shi', '', NULL, '和李尚書命妓餞崔侍御 盧溵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0de6aed-cdba-4567-9b8a-e2195c315d55', '對酒', '对酒', '50b07413-dad4-4bb3-bf9b-80c49bfd29e8', '唐', '["雲翁耕扶桑，種黍養日烏。","手挼六十花甲子，循環落落如弄珠。","長繩繫日未是愚，有翁臨鏡捋白鬚。","飢魂弔骨吟古書，馮唐八十無高車。","人生如雲在須臾，何乃自苦八尺軀。","裂衣換酒且爲娛，勸君朝飲一瓢。","夜飲一壺，杞天崩。","雷騰騰，桀非堯是何足憑。","桐君桂父豈勝我，醉裏白龍多上昇。","菖蒲花開魚尾定，金丹始可延君命。"]', '["云翁耕扶桑，種黍養日烏。","手挼六十花甲子，循环落落如弄珠。","长繩繫日未是愚，有翁臨镜捋白鬚。","飢魂弔骨吟古书，馮唐八十無高车。","人生如云在須臾，何乃自苦八尺軀。","裂衣換酒且爲娛，勸君朝饮一瓢。","夜饮一壺，杞天崩。","雷腾腾，桀非堯是何足憑。","桐君桂父豈勝我，醉裏白龙多上昇。","菖蒲花开鱼尾定，金丹始可延君命。"]', '诗', 'shi', '', NULL, '對酒 趙牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea5bed7-7241-475a-b705-57e485598f87', '南歌子詞三首 一', '南歌子词三首 一', '4bd453a8-8732-4753-8a58-b17d08162259', '唐', '["不是廚中丳，爭知{炙火=肉}裏心。","井邊銀釧落，展轉恨還深。"]', '["不是廚中丳，爭知{炙火=肉}裏心。","井邊銀釧落，展轉恨還深。"]', '诗', 'shi', '', NULL, '南歌子詞三首 一 裴諴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fac70547-dcd4-442d-bced-1b1fb21237fd', '南歌子詞三首 二', '南歌子词三首 二', '4bd453a8-8732-4753-8a58-b17d08162259', '唐', '["不信長相憶，擡頭問取天。","風吹荷葉動，無夜不搖蓮。"]', '["不信长相憶，擡头问取天。","风吹荷葉动，無夜不搖蓮。"]', '诗', 'shi', '', NULL, '南歌子詞三首 二 裴諴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0496f2e5-4641-496a-bb5f-e29dce50ba64', '南歌子詞三首 三', '南歌子词三首 三', '4bd453a8-8732-4753-8a58-b17d08162259', '唐', '["簳蠟爲紅燭，情知不自由。","細絲斜結網，爭奈眼相鉤。"]', '["簳蠟爲紅燭，情知不自由。","細絲斜結網，爭奈眼相鉤。"]', '诗', 'shi', '', NULL, '南歌子詞三首 三 裴諴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a123ac-c724-442f-8686-05fc32ab767c', '新添聲楊柳枝詞 一', '新添声楊柳枝词 一', '4bd453a8-8732-4753-8a58-b17d08162259', '唐', '["思量大是惡姻緣，只得相看不得憐。","願作琵琶槽那畔，得他長抱在胷前。"]', '["思量大是惡姻緣，只得相看不得怜。","願作琵琶槽那畔，得他长抱在胷前。"]', '诗', 'shi', '', NULL, '新添聲楊柳枝詞 一 裴諴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b477a845-5886-4311-af1c-c80aad5e5852', '新添聲楊柳枝詞 二', '新添声楊柳枝词 二', '4bd453a8-8732-4753-8a58-b17d08162259', '唐', '["獨房蓮子沒人看，偷折蓮時命也𢬵。","若有所由來借問，但道偷蓮是下官。"]', '["独房蓮子沒人看，偷折蓮时命也𢬵。","若有所由来借问，但道偷蓮是下官。"]', '诗', 'shi', '', NULL, '新添聲楊柳枝詞 二 裴諴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49f4d48e-ce28-4470-a353-7e445cd9a76c', '夏杪登越王樓臨涪江望雪山寄朝中知友', '夏杪登越王楼臨涪江望雪山寄朝中知友', 'd7c3a54d-baf2-48c5-a716-8a96576016d9', '唐', '["巴西西北樓，堪望亦堪愁。","山亂江迴遠，川清樹欲秋。","晴明中雪嶺，煙靄下漁舟。","寫寄朝天客，知余恨獨遊。"]', '["巴西西北楼，堪望亦堪愁。","山亂江迴远，川清樹欲秋。","晴明中雪嶺，煙靄下漁舟。","寫寄朝天客，知余恨独游。"]', '诗', 'shi', '', NULL, '夏杪登越王樓臨涪江望雪山寄朝中知友 于興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a74baf-db59-478d-9017-4c45aa6b82d7', '東陽涵碧亭', '东陽涵碧亭', 'd7c3a54d-baf2-48c5-a716-8a96576016d9', '唐', '["高低竹雜松，積翠復留風。","路劇陰溪裏，寒生暑氣中。"]', '["高低竹杂松，積翠复留风。","路劇陰溪裏，寒生暑氣中。"]', '诗', 'shi', '', NULL, '東陽涵碧亭 于興宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9aa030-e68d-4f23-bac4-b11fb14b4fd3', '奉酬綿州中丞以江山小圖遠垂賜及兼寄詩', '奉酬綿州中丞以江山小圖远垂賜及兼寄诗', 'd1289d87-7358-4014-a931-fd3c795d0c68', '唐', '["巴江與雪山，井邑共迴環。","圖寫丹青內，分明煙靄間。","移君名郡興，助我小齋閑。","日想登臨處，高蹤不可攀。"]', '["巴江與雪山，井邑共迴环。","圖寫丹青內，分明煙靄间。","移君名郡兴，助我小斋闲。","日想登臨处，高蹤不可攀。"]', '诗', 'shi', '', NULL, '奉酬綿州中丞以江山小圖遠垂賜及兼寄詩 李朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7b5a89-1483-4a68-896c-8f9858501779', '奉酬于中丞登越王樓見寄之什', '奉酬于中丞登越王楼见寄之什', 'd1444ad9-7e40-451f-a948-c231ee923a45', '唐', '["劒外書來日，驚忙自折封。","丹青得山水，強健慰心胸。","事少勝諸郡，江迴見幾重。","寧悲久作別，且似一相逢。","詩合焚香詠，愁應賴酒濃。","庾樓寒更憶，腸斷雪千峰。"]', '["劒外书来日，驚忙自折封。","丹青得山水，強健慰心胸。","事少勝諸郡，江迴见幾重。","寧悲久作別，且似一相逢。","诗合焚香詠，愁應賴酒濃。","庾楼寒更憶，腸斷雪千峰。"]', '诗', 'shi', '', NULL, '奉酬于中丞登越王樓見寄之什 楊牢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acc507d-b716-4f23-ba3b-c4747d82769d', '贈舍弟', '贈舍弟', 'd1444ad9-7e40-451f-a948-c231ee923a45', '唐', '["秦雲蜀浪兩堪愁，爾養晨昏我遠遊。","千里客心難寄夢，兩行鄉淚爲君流。","早驅風雨知龍聖，餓食魚鰕覺虎羞。","袖裏鏌鋣光似水，丈夫不合等閑休。"]', '["秦云蜀浪兩堪愁，爾養晨昏我远游。","千里客心难寄梦，兩行乡泪爲君流。","早驱风雨知龙聖，餓食鱼鰕覺虎羞。","袖裏鏌鋣光似水，丈夫不合等闲休。"]', '诗', 'shi', '', NULL, '贈舍弟 楊牢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83611bbb-8060-4599-b986-eddb78bd50cd', '句', '句', 'd1444ad9-7e40-451f-a948-c231ee923a45', '唐', '["蝦𢋙欲喫月，保讓常敎圓。","心明外不察，月向懷中圓。","羅幃若不卷，誰道中無人。","魁形下方天頂亞，二十四寸窗中月。"]', '["蝦𢋙欲喫月，保讓常敎圓。","心明外不察，月向懷中圓。","羅幃若不卷，誰道中無人。","魁形下方天頂亞，二十四寸窗中月。"]', '诗', 'shi', '', NULL, '句 楊牢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b929881e-5b10-4218-917b-3908b654adf7', '和綿州于中丞登越王樓見寄', '和綿州于中丞登越王楼见寄', '58aa8ab8-95dc-4c9b-88fb-91fc2e8fdbe2', '唐', '["早年登此樓，退想不勝愁。","地遠二千里，時將四十秋。","邅迍多失路，華皓任虛舟。","詩酒雖堪使，何因得共遊。"]', '["早年登此楼，退想不勝愁。","地远二千里，时將四十秋。","邅迍多失路，华皓任虛舟。","诗酒雖堪使，何因得共游。"]', '诗', 'shi', '', NULL, '和綿州于中丞登越王樓見寄 李續 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6288ee91-8336-42d4-baf8-da52e9af2a65', '和綿州于中丞登越王樓作', '和綿州于中丞登越王楼作', '8bd4ae3f-6f5c-4c08-8398-db39c1b09d63', '唐', '["珍重巴西守，殷勤寄遠情。","劒峰當戶碧，詩韻滿樓清。","日照涪川闊，煙籠雪嶠明。","徵黃看即及，莫歎滯江城。"]', '["珍重巴西守，殷勤寄远情。","劒峰當戶碧，诗韻满楼清。","日照涪川闊，煙籠雪嶠明。","徵黄看即及，莫歎滯江城。"]', '诗', 'shi', '', NULL, '和綿州于中丞登越王樓作 李汶濡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394a5ba3-c0e5-4237-b403-ca61997714bc', '和于中丞夏杪登越王樓望雪山見寄', '和于中丞夏杪登越王楼望雪山见寄', 'd32b4668-99ca-4216-854e-86e1a44af6ab', '唐', '["志乖多感物，臨眺更增愁。","暑候雖云夏，江聲已似秋。","雪遙難辨木，村近好維舟。","莫恨歸朝晚，朝簪擬勝遊。"]', '["志乖多感物，臨眺更增愁。","暑候雖云夏，江声已似秋。","雪遙难辨木，村近好維舟。","莫恨归朝晚，朝簪擬勝游。"]', '诗', 'shi', '', NULL, '和于中丞夏杪登越王樓望雪山見寄 田章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2505789c-8f1b-4687-b8c7-5b7eebc6f1c9', '和綿州于中丞登越王樓作', '和綿州于中丞登越王楼作', '5692c605-5d98-4134-b8f8-a03c3f1aed47', '唐', '["左綿江上樓，五馬此銷愁。","暑退千山雪，風來萬木秋。","邅迴猶刺郡，繫滯似維舟。","即有徵黃日，名川莫厭遊。"]', '["左綿江上楼，五马此銷愁。","暑退千山雪，风来万木秋。","邅迴猶刺郡，繫滯似維舟。","即有徵黄日，名川莫厭游。"]', '诗', 'shi', '', NULL, '和綿州于中丞登越王樓作 薛蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60371035-d60b-4644-b11d-175b8156d546', '和綿州于中丞登越王樓作', '和綿州于中丞登越王楼作', '3931b1d7-69fb-4549-98e8-88e5a87055a9', '唐', '["長聽巴西事，看圖勝所聞。","江樓明返照，雪嶺亂晴雲。","景象詩情在，幽奇筆跡分。","使君徒說好，不祗怨離羣。"]', '["长听巴西事，看圖勝所闻。","江楼明返照，雪嶺亂晴云。","景象诗情在，幽奇笔跡分。","使君徒说好，不祗怨離羣。"]', '诗', 'shi', '', NULL, '和綿州于中丞登越王樓作 李鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4622eb-c07a-4c0e-9e33-1abe592615d0', '和綿州于中丞登越王樓作二首 一', '和綿州于中丞登越王楼作二首 一', '9d3e4380-a552-4022-b649-8943da013c6d', '唐', '["樓因藩邸號，川勢似依樓。","顯敞含清暑，嵐光入素秋。","山宜姑射貌，江泛李膺舟。","郢曲思朋執，輕紗畫勝遊。"]', '["楼因藩邸號，川勢似依楼。","显敞含清暑，嵐光入素秋。","山宜姑射貌，江泛李膺舟。","郢曲思朋執，轻紗畫勝游。"]', '诗', 'shi', '', NULL, '和綿州于中丞登越王樓作二首 一 于瓌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18bb6383-5f0f-4cee-a93e-8997bed2663a', '和綿州于中丞登越王樓作二首 二', '和綿州于中丞登越王楼作二首 二', '9d3e4380-a552-4022-b649-8943da013c6d', '唐', '["極目郡城樓，浮雲拂檻愁。","政成多暇日，詩思動先秋。","遠霽千巖雪，隨波一葉舟。","昔曾窺粉繪，今願許陪遊。"]', '["極目郡城楼，浮云拂檻愁。","政成多暇日，诗思动先秋。","远霽千巖雪，隨波一葉舟。","昔曾窺粉繪，今願許陪游。"]', '诗', 'shi', '', NULL, '和綿州于中丞登越王樓作二首 二 于瓌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('371766bd-0e6d-40ed-ac46-91eb42ae44a8', '和于中丞登越王樓', '和于中丞登越王楼', '50bb0570-4133-4a42-8afa-f53b9a72be2c', '唐', '["雉堞臨朱檻，登茲便散愁。","蟬聲怨炎夏，山色報新秋。","江轉穿雲樹，心閑隨葉舟。","仲[宣]徒有歎，謝守幾追遊。"]', '["雉堞臨朱檻，登茲便散愁。","蟬声怨炎夏，山色報新秋。","江轉穿云樹，心闲隨葉舟。","仲[宣]徒有歎，謝守幾追游。"]', '诗', 'shi', '', NULL, '和于中丞登越王樓 王嚴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baccb10c-17de-41e1-9805-5e1dae11b8bf', '題越王樓寄獻中丞使君', '題越王楼寄獻中丞使君', '5effe7be-6239-47a9-9be6-070e648587cb', '唐', '["朱軒迥壓碧煙州，昔歲賢王是勝遊。","山簇劒峰朝闕遠，水如巴字遶城流。","人間物象分千里，天上笙歌醉五侯。","今日登臨無限意，同霑惠化自銷愁。"]', '["朱軒迥壓碧煙州，昔歲賢王是勝游。","山簇劒峰朝闕远，水如巴字遶城流。","人间物象分千里，天上笙歌醉五侯。","今日登臨無限意，同霑惠化自銷愁。"]', '诗', 'shi', '', NULL, '題越王樓寄獻中丞使君 劉暌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b5ee1e-f6da-4f8d-84ab-19241ccb1631', '秋日登越王樓獻于中丞', '秋日登越王楼獻于中丞', '5ccb6cab-8ef8-47c7-934e-6afe3916a1f5', '唐', '["越王曾牧劒南州，因向城隅建此樓。","橫玉遠開千嶠雪，暗雷下聽一江流。","畫簷先弄朝陽色，朱檻低臨衆木秋。","徒學仲宣聊四望，且將詞賦好依劉。"]', '["越王曾牧劒南州，因向城隅建此楼。","橫玉远开千嶠雪，暗雷下听一江流。","畫簷先弄朝陽色，朱檻低臨衆木秋。","徒学仲宣聊四望，且將词賦好依劉。"]', '诗', 'shi', '', NULL, '秋日登越王樓獻于中丞 李渥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac7b2d1-e127-439e-a44d-fe34bab71429', '洋州于中丞頃牧左綿題詩越王樓上朝賢繼和輙課四韻', '洋州于中丞頃牧左綿題诗越王楼上朝賢繼和輙課四韻', '9b3395a7-c9be-4f0c-95c9-3d54f1bb7bdd', '唐', '["隔政代君侯，多慚跡令猷。","山光來戶牖，江鳥滿汀洲。","雅韻徵朝客，清詞寫郡樓。","至今謠未已，注意在洋州。"]', '["隔政代君侯，多慚跡令猷。","山光来戶牖，江鸟满汀洲。","雅韻徵朝客，清词寫郡楼。","至今謠未已，注意在洋州。"]', '诗', 'shi', '', NULL, '洋州于中丞頃牧左綿題詩越王樓上朝賢繼和輙課四韻 劉璐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c30f00-d622-4664-8b24-6510310fd1ad', '和于中丞登越王樓作', '和于中丞登越王楼作', '8e9131f5-0f6e-43a9-be89-3bdcd0301615', '唐', '["圖[畫]越王樓，開緘慰別愁。","山光涵雪冷，水色帶江秋。","雲島孤征鴈，煙帆一葉舟。","嚮風舒霽景，如伴謝公遊。"]', '["圖[畫]越王楼，开緘慰別愁。","山光涵雪冷，水色带江秋。","云島孤征鴈，煙帆一葉舟。","嚮风舒霽景，如伴謝公游。"]', '诗', 'shi', '', NULL, '和于中丞登越王樓作 盧栯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf3c1df5-f8f0-4d09-a062-d81369bc6f54', '飛鴻響遠音', '飞鴻响远音', '64df0156-1201-48d9-be79-74ce48ba6694', '唐', '["漠漠微霜夕，翩翩出渚鴻。","清聲流逈野，高韻入寥空。","舊質經寒塞，殘音響遠風。","縈雲猶類網，避月尚疑弓。","弱羽雖能振，丹霄竟未通。","欲知多怨思，聽取暮煙中。"]', '["漠漠微霜夕，翩翩出渚鴻。","清声流逈野，高韻入寥空。","旧質經寒塞，殘音响远风。","縈云猶類網，避月尚疑弓。","弱羽雖能振，丹霄竟未通。","欲知多怨思，听取暮煙中。"]', '诗', 'shi', '', NULL, '飛鴻響遠音 李體仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db11089a-c221-4b07-b5d6-d37a299c8bea', '春愁', '春愁', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["金烏長飛玉兔走，青鬢長青古無有。","秦娥十六語如弦，未解貪花惜楊柳。","吳魚嶺鴈無消息，水誓蘭情別來久。","勸君年少莫遊春，煖風遲日濃於酒。"]', '["金烏长飞玉兔走，青鬢长青古無有。","秦娥十六語如弦，未解貪花惜楊柳。","吳鱼嶺鴈無消息，水誓蘭情別来久。","勸君年少莫游春，煖风遲日濃於酒。"]', '诗', 'shi', '', NULL, '春愁 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02fc56ef-7e3e-44d2-8251-eeb352170cdc', '牡丹', '牡丹', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["殘花何處藏，盡在牡丹房。","嫩蘂包金粉，重葩結繡囊。","雲凝巫峽夢，簾閉景陽粧。","應恨年華促，遲遲待日長。"]', '["殘花何处藏，尽在牡丹房。","嫩蘂包金粉，重葩結繡囊。","云凝巫峽梦，簾閉景陽粧。","應恨年华促，遲遲待日长。"]', '诗', 'shi', '', NULL, '牡丹 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0923419a-0eef-4cb1-84fd-31374c32e8a0', '興平縣野中得落星石移置縣齋', '兴平縣野中得落星石移置縣斋', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["的的墮芊蒼，茫茫不記年。","幾逢疑虎將，應逐犯牛仙。","擇地依蘭畹，題詩間錦錢。","何時成五色，却上女媧天。"]', '["的的墮芊蒼，茫茫不記年。","幾逢疑虎將，應逐犯牛仙。","擇地依蘭畹，題诗间錦錢。","何时成五色，却上女媧天。"]', '诗', 'shi', '', NULL, '興平縣野中得落星石移置縣齋 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96afd27a-b059-4d11-9430-d3bf951080a3', '題商山店', '題商山店', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["商山驛路幾經過，未到仙娥見謝娥。","紅錦機頭拋皓腕，綠雲鬟下送橫波。","佯嗔阿母留賓客，暗爲王孫換綺羅。","碧澗門前一條水，豈知平地有天河。"]', '["商山驛路幾經過，未到仙娥见謝娥。","紅錦機头拋皓腕，綠云鬟下送橫波。","佯嗔阿母留賓客，暗爲王孫換綺羅。","碧澗门前一條水，豈知平地有天河。"]', '诗', 'shi', '', NULL, '題商山店 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0a5bff1-a091-44d7-8a36-2248b7f079c8', '風', '风', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["競持飄忽意何窮，爲盛爲衰半不同。","偃草喜逢新雨後，鳴條愁聽曉霜中。","涼飛玉管來秦甸，暗褭花枝入楚宮。","莫見東風便無定，滿帆還有濟川功。"]', '["競持飄忽意何窮，爲盛爲衰半不同。","偃草喜逢新雨後，鳴條愁听晓霜中。","涼飞玉管来秦甸，暗褭花枝入楚宮。","莫见东风便無定，满帆還有濟川功。"]', '诗', 'shi', '', NULL, '風 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ecbe5e-0a4f-47f0-8d7f-cf5e09269c76', '雲', '云', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["深惹離情靄落暉，如車如蓋早依依。","山頭觸石應常在，天際從龍自不歸。","莫向隙窗籠夜月，好來仙洞濕行衣。","春風淡蕩無心後，見說襄王夢亦稀。"]', '["深惹離情靄落暉，如车如蓋早依依。","山头觸石應常在，天際從龙自不归。","莫向隙窗籠夜月，好来仙洞濕行衣。","春风淡蕩無心後，见说襄王梦亦稀。"]', '诗', 'shi', '', NULL, '雲 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3816727-d65b-4d4d-aa2e-987c3963759a', '露', '露', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["長隨聖澤墮堯天，濯遍幽蘭葉葉鮮。","纔喜輕塵銷陌上，已愁新月到堦前。","文騰要地成非久，珠綴秋荷偶得圓。","幾處花枝抱離恨，曉風殘月正澘然。"]', '["长隨聖澤墮堯天，濯遍幽蘭葉葉鲜。","纔喜轻塵銷陌上，已愁新月到堦前。","文腾要地成非久，珠綴秋荷偶得圓。","幾处花枝抱離恨，晓风殘月正澘然。"]', '诗', 'shi', '', NULL, '露 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a24c7b-8dd9-48e1-af11-c55f62911741', '霞', '霞', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["應是行雲未擬歸，變成春態媚晴暉。","深如綺色斜分閣，碎似花光散滿衣。","天際欲銷重慘淡，鏡中閑照正依稀。","曉來何處低臨水，無限鴛鴦妬不飛。"]', '["應是行云未擬归，变成春態媚晴暉。","深如綺色斜分閣，碎似花光散满衣。","天際欲銷重慘淡，镜中闲照正依稀。","晓来何处低臨水，無限鴛鴦妬不飞。"]', '诗', 'shi', '', NULL, '霞 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0411d3f-e7de-4f9f-b85a-3f579009a09b', '潁亭', '潁亭', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["潁上新亭瞰一川，幾重舊址敞幽關。","寒聲北下當軒水，翠影西來撲檻山。","遠目靜隨孤鶴去，高情常共白雲閑。","知君久負巢由志，早晚相忘寂寞間。"]', '["潁上新亭瞰一川，幾重旧址敞幽关。","寒声北下當軒水，翠影西来撲檻山。","远目静隨孤鹤去，高情常共白云闲。","知君久負巢由志，早晚相忘寂寞间。"]', '诗', 'shi', '', NULL, '潁亭 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38210d93-9a4a-41fb-a79c-d7ed0383618b', '詠馬', '詠马', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["曾經伯樂識長鳴，不似龍行不敢行。","金埒未登嘶若是，鹽車猶駕瘦何驚。","難逢王濟知音癖，欲就燕昭買駿名。","早晚飛黃引同皂，碧雲天上作鸞鳴。"]', '["曾經伯乐識长鳴，不似龙行不敢行。","金埒未登嘶若是，鹽车猶駕瘦何驚。","难逢王濟知音癖，欲就燕昭買駿名。","早晚飞黄引同皂，碧云天上作鸾鳴。"]', '诗', 'shi', '', NULL, '詠馬 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34d5d1c-c3bb-43a2-906b-48116b8cdf28', '題圭峰下長孫家林亭', '題圭峰下长孫家林亭', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["趙國林亭二百年，綠苔如毯葛如煙。","閑期竹色搖霜看，醉惜松聲枕月眠。","出樹圭峰寒壓坐，入籬沙瀨碧流天。","明知富貴非身物，莫爲金章墮地仙。"]', '["趙国林亭二百年，綠苔如毯葛如煙。","闲期竹色搖霜看，醉惜松声枕月眠。","出樹圭峰寒壓坐，入籬沙瀨碧流天。","明知富貴非身物，莫爲金章墮地仙。"]', '诗', 'shi', '', NULL, '題圭峰下長孫家林亭 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('416bb99b-e2b4-4c5b-828f-4c50907ee901', '牡丹', '牡丹', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["桃時杏日不爭濃，葉帳陰成始放紅。","曉豔遠分金掌露，暮香深惹玉堂風。","名移蘭杜千年後，貴擅笙歌百醉中。","如夢如仙忽零落，暮霞何處綠屏空。"]', '["桃时杏日不爭濃，葉帳陰成始放紅。","晓豔远分金掌露，暮香深惹玉堂风。","名移蘭杜千年後，貴擅笙歌百醉中。","如梦如仙忽零落，暮霞何处綠屏空。"]', '诗', 'shi', '', NULL, '牡丹 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd828ea-c32d-4734-87c3-175f3174f868', '雨', '雨', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["陰雲拂地散絲輕，長得爲霖濟物名。","夜浦漲歸天塹闊，春風灑入御溝平。","軒車幾處歸頻濕，羅綺何人去欲生。","不及流他荷葉上，似珠無數轉分明。"]', '["陰云拂地散絲轻，长得爲霖濟物名。","夜浦漲归天塹闊，春风灑入御溝平。","軒车幾处归頻濕，羅綺何人去欲生。","不及流他荷葉上，似珠無數轉分明。"]', '诗', 'shi', '', NULL, '雨 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91be4f6-cbc2-4da5-8f3f-4569a4622121', '京西即事', '京西即事', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["秋草河蘭起陣雲，涼州唯向管弦聞。","豺狼毳幕三千帳，貔虎金戈十萬軍。","候騎北來驚有說，戍樓西望悔爲文。","昭陽亦待平安火，誰握旌旗不見勳。"]', '["秋草河蘭起陣云，涼州唯向管弦闻。","豺狼毳幕三千帳，貔虎金戈十万軍。","候騎北来驚有说，戍楼西望悔爲文。","昭陽亦待平安火，誰握旌旗不见勳。"]', '诗', 'shi', '', NULL, '京西即事 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ea9961-4b3b-4659-9430-c1c38eb68858', '公子行', '公子行', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["紫袖長衫色，銀蟬半臂花。","帶裝盤水玉，鞍繡坐雲霞。","別殿承恩澤，飛龍賜渥洼。","控羅青褭轡，鏤象碧熏葩。","意氣傾歌舞，闌珊走鈿車。","袖障雲縹緲，釵轉鳳欹斜。","珠卷迎歸箔，雕籠晃醉紗。","唯無難夜日，不得似仙家。"]', '["紫袖长衫色，銀蟬半臂花。","带裝盤水玉，鞍繡坐云霞。","別殿承恩澤，飞龙賜渥洼。","控羅青褭轡，鏤象碧熏葩。","意氣傾歌舞，闌珊走鈿车。","袖障云縹緲，釵轉鳳欹斜。","珠卷迎归箔，雕籠晃醉紗。","唯無难夜日，不得似仙家。"]', '诗', 'shi', '', NULL, '公子行 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a8cd10-771d-4a0f-b491-7f0c3761ea16', '秋晚信州推院親友或責無書即事寄答', '秋晚信州推院親友或責無书即事寄答', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["官信安仁拙，書非叔夜慵。","謬馳驄馬傳，難附鯉魚封。","萬里勞何補，千年運忝逢。","不量橫草力，虛慕入雲蹤。","潔水空澄鑑，持鉛亦礪鋒。","月寒深夜桂，霜凜近秋松。","憲摘無逃魏，冤申得夢馮。","問貍將挾虎，殲蠆敢虞蜂。","商吹移砧調，春華改鏡容。","歸期方畹積，愁思暮山重。","仙鼠猶驚燕，莎雞欲變蛩。","唯應碧湘浦，雲落及芙蓉。"]', '["官信安仁拙，书非叔夜慵。","謬驰驄马傳，难附鯉鱼封。","万里勞何補，千年運忝逢。","不量橫草力，虛慕入云蹤。","潔水空澄鑑，持鉛亦礪鋒。","月寒深夜桂，霜凜近秋松。","憲摘無逃魏，冤申得梦馮。","问貍將挾虎，殲蠆敢虞蜂。","商吹移砧調，春华改镜容。","归期方畹積，愁思暮山重。","仙鼠猶驚燕，莎雞欲变蛩。","唯應碧湘浦，云落及芙蓉。"]', '诗', 'shi', '', NULL, '秋晚信州推院親友或責無書即事寄答 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f536116-335a-487f-b456-d7d129bb0b5f', '晚春江晴寄友人', '晚春江晴寄友人', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["晚日低霞綺，晴山遠畫眉。","春青河畔草，不是望鄉時。"]', '["晚日低霞綺，晴山远畫眉。","春青河畔草，不是望乡时。"]', '诗', 'shi', '', NULL, '晚春江晴寄友人 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277b46a7-7c5c-4f88-a293-b9279e642c61', '涼州詞', '涼州词', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["樹發花如錦，鶯啼柳若絲。","更游歡宴地，悲見別離時。"]', '["樹發花如錦，鶯啼柳若絲。","更游歡宴地，悲见別離时。"]', '诗', 'shi', '', NULL, '涼州詞 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb8cc45e-84e2-4bc9-8e14-a1f5d87d69c6', '莫春滻水送別', '莫春滻水送別', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["綠暗紅稀出鳳城，暮雲樓閣古今情。","行人莫聽宮前水，流盡年光是此聲。"]', '["綠暗紅稀出鳳城，暮云楼閣古今情。","行人莫听宮前水，流尽年光是此声。"]', '诗', 'shi', '', NULL, '莫春滻水送別 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3815943-d2d4-481b-bf06-b45042a28f6b', '駱谷晚望', '駱谷晚望', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["秦川如畫渭如絲，去國還家一望時。","公子王孫莫來好，嶺花多是斷腸枝。"]', '["秦川如畫渭如絲，去国還家一望时。","公子王孫莫来好，嶺花多是斷腸枝。"]', '诗', 'shi', '', NULL, '駱谷晚望 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a3ed20-0274-4da6-aefd-aaa87c432436', '二月二日遊洛源', '二月二日游洛源', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["舊苑新晴草似苔，人還香在踏青迴。","今朝此地成惆悵，已後逢春更莫來。"]', '["旧苑新晴草似苔，人還香在踏青迴。","今朝此地成惆悵，已後逢春更莫来。"]', '诗', 'shi', '', NULL, '二月二日遊洛源 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab10b33-b489-4d53-8d64-573557467a96', '柳', '柳', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["折柳歌中得翠條，遠移金殿種青霄。","上陽宮女含聲送，不忿先歸舞細腰。"]', '["折柳歌中得翠條，远移金殿種青霄。","上陽宮女含声送，不忿先归舞細腰。"]', '诗', 'shi', '', NULL, '柳 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9fec98a-86b3-44aa-b82b-5d35f02506ec', '楊柳枝', '楊柳枝', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["梁苑隋堤事已空，萬條猶舞舊春風。","那堪更想千年後，誰見楊花入漢宮。"]', '["梁苑隋堤事已空，万條猶舞旧春风。","那堪更想千年後，誰见楊花入漢宮。"]', '诗', 'shi', '', NULL, '楊柳枝 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854a38ee-fbe5-4a2d-88de-b2b288c0d828', '楊柳枝詞', '楊柳枝词', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["枝鬬纖腰葉鬬眉，春來無處不如絲。","霸陵原上多離別，少有長條拂地垂。"]', '["枝鬬纖腰葉鬬眉，春来無处不如絲。","霸陵原上多離別，少有长條拂地垂。"]', '诗', 'shi', '', NULL, '楊柳枝詞 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5633e7-ea63-49e4-9011-025e0ab77c5d', '和襄陽徐相公商賀徐副使加章綬', '和襄陽徐相公商賀徐副使加章綬', '676a1633-dc77-4c62-b505-87e02be9d82d', '唐', '["朱紫聯輝照日新，芳菲全屬斷金人。","華筵重處宗盟地，白雪飛時郢曲春。","仙府色饒攀桂侶，蓮花光讓握蘭身。","自憐亦是膺門客，吟想恩榮氣益振。"]', '["朱紫聯輝照日新，芳菲全屬斷金人。","华筵重处宗盟地，白雪飞时郢曲春。","仙府色饒攀桂侶，蓮花光讓握蘭身。","自怜亦是膺门客，吟想恩榮氣益振。"]', '诗', 'shi', '', NULL, '和襄陽徐相公商賀徐副使加章綬 王傳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97f2abd5-6481-4a5d-b6d7-c6953e1184da', '和李尚書命妓餞崔侍御', '和李尚书命妓餞崔侍御', '1e74d280-f05a-4fd6-aeb6-87784d36a11a', '唐', '["何郎載酒別賢侯，更吐歌珠宴庾樓。","莫道江南不同醉，即陪舟檝上京游。"]', '["何郎載酒別賢侯，更吐歌珠宴庾楼。","莫道江南不同醉，即陪舟檝上京游。"]', '诗', 'shi', '', NULL, '和李尚書命妓餞崔侍御 盧鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb41112-dbe6-4161-abd4-bb1d1714f6fa', '松', '松', '954a6541-661b-423c-a1a9-4408bf4dd275', '唐', '["雪霜知勁質，今古占嘉名。","斷砌盤根遠，疎林偃蓋清。","鶴棲何代色，僧老四時聲。","鬱鬱心彌久，煙高萬井生。"]', '["雪霜知勁質，今古占嘉名。","斷砌盤根远，疎林偃蓋清。","鹤棲何代色，僧老四时声。","鬱鬱心彌久，煙高万井生。"]', '诗', 'shi', '', NULL, '松 陸肱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7035cfc5-c312-43ed-9ac3-18aaad4e5753', '贈王福娘', '贈王福娘', 'ac51d998-5542-4eda-a55e-1688f2b00cac', '唐', '["怪得清風送異香，娉婷仙子曳霓裳。","惟應錯認偷桃客，曼倩曾爲漢侍郎。"]', '["怪得清风送異香，娉婷仙子曳霓裳。","惟應錯認偷桃客，曼倩曾爲漢侍郎。"]', '诗', 'shi', '', NULL, '贈王福娘 崔澹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e170f1-e03b-48c7-85cd-7cfb4691f678', '荅問讀書居', '荅问读书居', '38b8fc41-6a1c-4d75-a3c3-3ab609f270e9', '唐', '["書屋倚麒麟，不同牛馬路。","牀頭萬卷書，溪上五龍渡。","井汲冽寒泉，桂花香玉露。","茅簷無外物，只見青雲護。"]', '["书屋倚麒麟，不同牛马路。","牀头万卷书，溪上五龙渡。","井汲冽寒泉，桂花香玉露。","茅簷無外物，只见青云護。"]', '诗', 'shi', '', NULL, '荅問讀書居 莫宣卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840f7753-2fba-403a-8b4b-af57e38ec1b0', '百官乘月早朝聽殘漏', '百官乘月早朝听殘漏', '38b8fc41-6a1c-4d75-a3c3-3ab609f270e9', '唐', '["建禮儼朝冠，重門耿夜闌。","碧空蟾魄度，清禁漏聲殘。","候曉車輿合，凌霜劍佩寒。","星河猶皎皎，銀箭尚珊珊。","杳靄祥光起，霏微瑞氣攢。","忻逢聖明代，長願接鵷鸞。"]', '["建禮儼朝冠，重门耿夜闌。","碧空蟾魄度，清禁漏声殘。","候晓车輿合，凌霜劍佩寒。","星河猶皎皎，銀箭尚珊珊。","杳靄祥光起，霏微瑞氣攢。","忻逢聖明代，长願接鵷鸾。"]', '诗', 'shi', '', NULL, '百官乘月早朝聽殘漏 莫宣卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b83061-2908-40ac-bdb9-8a58df4afc03', '賦得水懷珠', '賦得水懷珠', '38b8fc41-6a1c-4d75-a3c3-3ab609f270e9', '唐', '["長川含媚色，波底孕靈珠。","素魄生蘋末，圓規照水隅。","淪漣冰彩動，蕩漾瑞光鋪。","迥夜星同貫，清秋岸不枯。","江妃思在掌，海客亦忘軀。","合浦當還日，恩威信已敷。"]', '["长川含媚色，波底孕靈珠。","素魄生蘋末，圓規照水隅。","淪漣冰彩动，蕩漾瑞光鋪。","迥夜星同貫，清秋岸不枯。","江妃思在掌，海客亦忘軀。","合浦當還日，恩威信已敷。"]', '诗', 'shi', '', NULL, '賦得水懷珠 莫宣卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594a31ff-f917-43fd-9459-ef50f021cb49', '句', '句', '38b8fc41-6a1c-4d75-a3c3-3ab609f270e9', '唐', '["我本南山鳳，豈同凡鳥羣。"]', '["我本南山鳳，豈同凡鸟羣。"]', '诗', 'shi', '', NULL, '句 莫宣卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20db53d8-dd6b-4cee-806f-e05c4d5d08d4', '和李尚書命妓餞崔侍御', '和李尚书命妓餞崔侍御', '8d650670-d884-4296-8781-c038ba4cb25c', '唐', '["蓮府纔爲綠水賓，忽乘驄馬入咸秦。","爲君唱作西[河]調，日暮偏傷去住人。"]', '["蓮府纔爲綠水賓，忽乘驄马入咸秦。","爲君唱作西[河]調，日暮偏傷去住人。"]', '诗', 'shi', '', NULL, '和李尚書命妓餞崔侍御 封彥卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5780704-16c4-49f5-ad54-77d291382d63', '一', '一', '8d650670-d884-4296-8781-c038ba4cb25c', '唐', '["湘川狺狺兮俗獷且佷，利殺業偷兮吏莫之馴。","繄釋氏兮易暴使仁，釋何在兮釋在斯文。"]', '["湘川狺狺兮俗獷且佷，利殺業偷兮吏莫之馴。","繄釋氏兮易暴使仁，釋何在兮釋在斯文。"]', '诗', 'shi', '', NULL, '一 封彥卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b595f2d-e885-4dc2-ba20-ff39908a3740', '二', '二', '8d650670-d884-4296-8781-c038ba4cb25c', '唐', '["湘水滔滔兮四望何依，猨狖騰拏兮雲樹飛飛。","月沈浦兮煙暝山，檣席卷兮櫓牀閑。"]', '["湘水滔滔兮四望何依，猨狖腾拏兮云樹飞飞。","月沈浦兮煙暝山，檣席卷兮櫓牀闲。"]', '诗', 'shi', '', NULL, '二 封彥卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d08dbc-b71f-47b2-9128-aeb328bade5e', '三', '三', '8d650670-d884-4296-8781-c038ba4cb25c', '唐', '["湘川超忽兮落日晼晼，松覆秋亭兮蘭被春苑。","上人去兮幾千里，何日同遊兮湘川水。"]', '["湘川超忽兮落日晼晼，松覆秋亭兮蘭被春苑。","上人去兮幾千里，何日同游兮湘川水。"]', '诗', 'shi', '', NULL, '三 封彥卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973f08db-e7bb-401d-a3f9-8c71ebea21cf', '和柯古窮居苦日喜雨', '和柯古窮居苦日喜雨', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["貞機澹少思，雅尚防多僻。","攬葛猶不畏，勞形同處瘠。","頭焦詎是焚，背汗寧關炙。","方欣見潤礎，那虞悲鑠石。","道與古人期，情難物外適。","幾懷朱邸綬，頗曠金門籍。","清奧已蕭蕭，陳柯將槭槭。","玉律詩調正，瓊巵酒腸窄。","衣桁襲中單，浴牀拋下綌。","黎侯寓於衛，六義非凡格。"]', '["貞機澹少思，雅尚防多僻。","攬葛猶不畏，勞形同处瘠。","头焦詎是焚，背汗寧关炙。","方欣见潤礎，那虞悲鑠石。","道與古人期，情难物外適。","幾懷朱邸綬，頗曠金门籍。","清奧已蕭蕭，陳柯將槭槭。","玉律诗調正，瓊巵酒腸窄。","衣桁襲中單，浴牀拋下綌。","黎侯寓於衛，六義非凡格。"]', '诗', 'shi', '', NULL, '和柯古窮居苦日喜雨 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d913a7-6d74-4e44-8a9c-c481251861c9', '岳麓道林寺', '岳麓道林寺', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["石門逈接蒼梧野，愁色陰深二妃寡。","廣殿崔嵬萬壑間，長廊詰曲千巖下。","靜聽林飛念佛鳥，細看壁畫馱經馬。","暖日斜明螮蝀梁，濕烟散冪鴛鴦瓦。","北方部落檀香塑，西國文書貝葉寫。","壞欄迸竹醉好題，窄路垂藤困堪把。","沈裴筆力鬬雄壯，宋杜詞源兩風雅。","他方居士來施齋，彼岸上人投結夏。","悲我未離擾擾徒，勸我休學悠悠者。","何時得與劉遺民，同入東林遠公社。"]', '["石门逈接蒼梧野，愁色陰深二妃寡。","廣殿崔嵬万壑间，长廊詰曲千巖下。","静听林飞念佛鸟，細看壁畫馱經马。","暖日斜明螮蝀梁，濕烟散冪鴛鴦瓦。","北方部落檀香塑，西国文书貝葉寫。","壞欄迸竹醉好題，窄路垂藤困堪把。","沈裴笔力鬬雄壯，宋杜词源兩风雅。","他方居士来施斋，彼岸上人投結夏。","悲我未離擾擾徒，勸我休学悠悠者。","何时得與劉遺民，同入东林远公社。"]', '诗', 'shi', '', NULL, '岳麓道林寺 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e212fa0-d4b7-417f-bc85-448ec72499d3', '上元三首 一', '上元三首 一', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["新正圓月夜，尤重看燈時。","累塔嫌沙細，成文訝筆遲。","歸牛疑燧落，過鴈悞書遲。","生惜蘭膏燼，還爲隔歲期。"]', '["新正圓月夜，尤重看灯时。","累塔嫌沙細，成文訝笔遲。","归牛疑燧落，過鴈悞书遲。","生惜蘭膏燼，還爲隔歲期。"]', '诗', 'shi', '', NULL, '上元三首 一 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21330b6-b2fe-4c32-b757-cb6c0351ad43', '上元三首 二', '上元三首 二', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["舉燭光纔起，揮毫勢競分。","點時驚墜石，挑處接崩雲。","辭異秦丞相，銘非竇冠軍。","唯愁殘焰落，逢玉亦俱焚。"]', '["舉燭光纔起，揮毫勢競分。","点时驚墜石，挑处接崩云。","辞異秦丞相，銘非竇冠軍。","唯愁殘焰落，逢玉亦俱焚。"]', '诗', 'shi', '', NULL, '上元三首 二 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a276029b-e627-4297-897e-49409009d997', '上元三首 三', '上元三首 三', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["多寶神光動，生金瑞色浮。","照人低入郭，伴月夜當樓。","熏穴應無取，焚林固有求。","夜闌陪玉帳，不見九枝留。"]', '["多寶神光动，生金瑞色浮。","照人低入郭，伴月夜當楼。","熏穴應無取，焚林固有求。","夜闌陪玉帳，不见九枝留。"]', '诗', 'shi', '', NULL, '上元三首 三 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd7ca9a-96c2-4aad-a410-b848a6859bdb', '梅', '梅', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["高樹臨溪豔，低枝隔竹繁。","何須是桃李，然後欲忘言。","擬折魂先斷，須看眼更昏。","誰知南陌草，却解望王孫。"]', '["高樹臨溪豔，低枝隔竹繁。","何須是桃李，然後欲忘言。","擬折魂先斷，須看眼更昏。","誰知南陌草，却解望王孫。"]', '诗', 'shi', '', NULL, '梅 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6758c58e-ac5a-4529-810a-06e04b49de95', '送盧潘尚書之靈武', '送盧潘尚书之靈武', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["賀蘭山下果園成，塞北江南舊有名。","水木萬家朱戶暗，弓刀千隊鐵衣鳴。","心源落落堪爲將，膽氣堂堂合用兵。","却使六番諸子弟，馬前不信是書生。"]', '["賀蘭山下果园成，塞北江南旧有名。","水木万家朱戶暗，弓刀千隊鐵衣鳴。","心源落落堪爲將，膽氣堂堂合用兵。","却使六番諸子弟，马前不信是书生。"]', '诗', 'shi', '', NULL, '送盧潘尚書之靈武 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e3aa67-2e6c-4fa1-86ba-b8b755051dc6', '題僧壁', '題僧壁', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["一竹橫簷挂淨巾，竈無煙火地無塵。","剃頭未必知心法，要且閑於名利人。"]', '["一竹橫簷挂淨巾，竈無煙火地無塵。","剃头未必知心法，要且闲於名利人。"]', '诗', 'shi', '', NULL, '題僧壁 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a078f0f6-b0fb-4c20-aafd-48b239bbf0c2', '贈商山僧', '贈商山僧', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["商嶺東西路欲分，兩間茅屋一溪雲。","師言耳重知師意，人是人非不欲聞。"]', '["商嶺东西路欲分，兩间茅屋一溪云。","師言耳重知師意，人是人非不欲闻。"]', '诗', 'shi', '', NULL, '贈商山僧 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2c54bfc-5a09-46e3-8c12-4662af9aa973', '長樂驛謔李湯給事題名', '长乐驛謔李湯給事題名', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["渭水秦川拂眼明，希仁何事寡詩情。","只應學得虞姬壻，書字纔能記姓名。"]', '["渭水秦川拂眼明，希仁何事寡诗情。","只應学得虞姬壻，书字纔能記姓名。"]', '诗', 'shi', '', NULL, '長樂驛謔李湯給事題名 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01022d6-b4c9-4308-84ce-1606a267e0ea', '句', '句', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["爭揮鉤弋手，競聳踏搖身。","傷頰詎關舞，捧心非効嚬。"]', '["爭揮鉤弋手，競聳踏搖身。","傷頰詎关舞，捧心非効嚬。"]', '诗', 'shi', '', NULL, '句 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af68f29f-064e-49a1-9854-dcd6e849efc0', '賦得壽星見', '賦得壽星见', 'fc2fc102-1974-4cc4-99c8-529f7178b6d5', '唐', '["玄象今何應，時和政亦平。","祥爲一人壽，色映九霄明。","皎潔垂銀漢，光芒近斗城。","含規同月滿，表瑞得天清。","甘露盈條降，非煙向日生。","無如此嘉祉，率土荷秋成。"]', '["玄象今何應，时和政亦平。","祥爲一人壽，色映九霄明。","皎潔垂銀漢，光芒近斗城。","含規同月满，表瑞得天清。","甘露盈條降，非煙向日生。","無如此嘉祉，率土荷秋成。"]', '诗', 'shi', '', NULL, '賦得壽星見 盧渥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c08330b2-62f4-4919-bdde-c51106d045fe', '題嘉祥驛', '題嘉祥驛', 'fc2fc102-1974-4cc4-99c8-529f7178b6d5', '唐', '["交親榮餞洛城空，秉鉞戎裝上將同。","星使自天丹詔下，雕鞍照地數程中。","馬嘶靜谷聲偏響，斾映晴山色更紅。","到後定知人易化，滿街棠樹有遺風。"]', '["交親榮餞洛城空，秉鉞戎裝上將同。","星使自天丹詔下，雕鞍照地數程中。","马嘶静谷声偏响，斾映晴山色更紅。","到後定知人易化，满街棠樹有遺风。"]', '诗', 'shi', '', NULL, '題嘉祥驛 盧渥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4feb429-ed11-403f-aaa5-34085cbcbd2e', '九華山', '九华山', 'b1a9c98a-a5e1-4a93-a2d3-7bb8f7904b01', '唐', '["巖翠凌雲出迥然，岧嶤萬丈倚秋天。","暮風飄送當軒色，曉霧斜飛入檻煙。","簾捲倚屏雙影聚，鏡開朱戶九條懸。","畫圖何必家家有，自有畫圖來目前。"]', '["巖翠凌云出迥然，岧嶤万丈倚秋天。","暮风飄送當軒色，晓霧斜飞入檻煙。","簾捲倚屏雙影聚，镜开朱戶九條懸。","畫圖何必家家有，自有畫圖来目前。"]', '诗', 'shi', '', NULL, '九華山 郭夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab815e6-0b0a-4999-a02f-102decdfccf2', '送莫仲節狀元歸省', '送莫仲節狀元归省', '1fe4ec9c-f83e-4b76-9f6b-14c75b1c6d72', '唐', '["青驄聚送謫仙人，南國榮親不及君。","椰子味從今日近，鷓鴣聲向舊山聞。","孤猨夜呌三湘月，匹馬時侵五嶺雲。","想到故鄉應臘過，藥欄猶有異花薰。"]', '["青驄聚送謫仙人，南国榮親不及君。","椰子味從今日近，鷓鴣声向旧山闻。","孤猨夜呌三湘月，匹马时侵五嶺云。","想到故乡應臘過，藥欄猶有異花薰。"]', '诗', 'shi', '', NULL, '送莫仲節狀元歸省 柳珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e789504b-5f99-4982-b9d4-c651658e8995', '津陽門詩', '津陽门诗', 'c9649f8f-23ba-49b9-aa91-5be696f16a68', '唐', '["津陽門北臨通逵，雪風獵獵飄酒旗。","泥寒欵段蹶不進，疲童退問前何爲。","酒家顧客催解裝，案前羅列樽與巵。","青錢瑣屑安足數，白醪軟美甘如飴。","開壚引滿相獻酬，枯腸渴肺忘朝飢。","愁憂似見出門去，漸覺春色入四肢。","主翁移客挑華燈，雙肩隱膝烏帽欹。","笑云鮐老不爲禮，飄蕭雪鬢雙垂頤。","問余何往凌寒曦，顧翁枯朽郎豈知。","翁曾豪盛客不見，我自爲君陳昔時。","時平親衛號羽林，我纔十五爲孤兒。","射熊搏虎衆莫敵，彎弧出入隨佽飛。","此時初創觀風樓，簷高百尺堆華榱。","樓南更起鬬雞殿，晨光出影相參差。","其年十月移禁仗，山下櫛比羅百司。","朝元閣成老君見，會昌縣以新豐移。","幽州曉進供奉馬，玉珂寶勒黃金羈。","五王扈駕夾城路，傳聲校獵渭水湄。","羽林六軍各出射，籠山絡野張罝維。","彫弓繡韣不知數，翻身滅沒皆蛾眉。","赤鷹黃鶻雲中來，妖狐狡兔無所依。","人煩馬殆禽獸盡，百里腥膻禾黍稀。","暖山度臘東風微，宮娃賜浴長湯池。","刻成玉蓮噴香液，漱迴煙浪深逶迤。","犀屏象薦雜羅列，錦鳧繡雁相追隨。","破簪碎鈿不足拾，金溝殘溜和纓緌。","上皇寬容易承事，十家三國爭光輝。","繞牀呼盧恣樗博，張燈達晝相謾欺。","相君侈擬縱驕橫，日從秦虢多游嬉。","朱衫馬前未滿足，更驅武卒羅旌旗。","畫輪寶軸從天來，雲中笑語聲融怡。","鳴鞭後騎何躞蹀，宮粧襟袖皆仙姿。","青門紫陌多春風，風中數日殘春遺。","驪駒吐沬一奮迅，路人擁篲爭珠璣。","八姨新起合歡堂，翔鵾賀燕無由窺。","萬金酬工不肯去，矜能恃巧猶嗟咨。","四方節制傾附媚，窮奢極侈沽恩私。","堂中特設夜明枕，銀燭不張光鑒帷。","瑤光樓南皆紫禁，梨園仙宴臨花枝。","迎娘歌喉玉𥦖窱，蠻兒舞帶金葳蕤。","三郎紫笛弄煙月，怨如別鶴呼羈雌。","玉奴琵琶龍香撥，倚歌促酒聲嬌悲。","飲鹿泉邊春露晞，粉梅檀杏飄朱墀。","金沙洞口長生殿，玉蘂峰頭王母祠。","禁庭術士多幻化，上前較勝紛相持。","羅公如意奪顏色，三藏袈裟成散絲。","蓬萊池上望秋月，無雲萬里懸清輝。","上皇夜半月中去，三十六宮愁不歸。","月中秘樂天半間，丁璫玉石和塤篪。","宸聰聽覽未終曲，却到人間迷是非。","千秋御節在八月，會同萬國朝華夷。","花萼樓南大合樂，八音九奏鸞來儀。","都盧尋橦誠齷齪，公孫劒伎方神奇。","馬知舞徹下牀榻，人惜曲終更羽衣。","祿山此時侍御側，金雞畫障當罘罳。","繡{衤羽}衣褓日屓贔，甘言狡計愈嬌癡。","詔令上路建甲第，樓通走馬如飛翬。","大開內府恣供給，玉缶金筐銀簸箕。","異謀潛熾促歸去，臨軒賜帶盈十圍。","忠臣張公識逆狀，日日切諫上弗疑。","湯成召浴果不至，潼關已溢漁陽師。","御街一夕無禁鼓，玉輅順動西南馳。","九門回望塵坌多，六龍夜馭兵衛疲。","縣官無人具軍頓，行宮徹屋屠雲螭。","馬嵬驛前駕不發，宰相射殺冤者誰。","長眉鬒髮作凝血，空有君王潛涕洟。","青泥坂上到三蜀，金堤城邊止九旂。","移文泣祭昔臣墓，度曲悲歌秋雁辭。","明年尚父上捷書，洗清觀闕收封畿。","兩君相見望賢頓，君臣鼓舞皆歔欷。","宮中親呼高驃騎，潛令改葬楊真妃。","花膚雪豔不復見，空有香囊和淚滋。","鑒輿却入華清宮，滿山紅實垂相思。","飛霜殿前月悄悄，迎春亭下風颸颸。","雪衣女失玉籠在，長生鹿瘦銅牌垂。","象牀塵凝罨颯被，畫檐蟲網頗梨碑。","碧菱花覆雲母陵，風篁雨菊低離披。","真人影帳偏生草，果老藥堂空掩扉。","鼎湖一日失弓劒，橋山煙草俄霏霏。","空聞玉椀入金市，但見銅壺飄翠帷。","開元到今踰十紀，當初事跡皆殘隳。","竹花唯養棲梧鳳，水藻周游巢葉龜。","會昌御宇斥內典，去留二敎分黃緇。","慶山汙瀦石甕毀，紅樓綠閣皆支離。","奇松怪柏爲樵蘇，童山眢谷亡嶮巇。","煙中壁碎摩詰畫，雲間字失玄宗詩。","石魚巖底百尋井，銀牀下卷紅綆遲。","當時清影蔭紅葉，一旦飛埃埋素規。","韓家燭臺倚林杪，千枝燦若山霞摛。","昔年光彩奪天月，昨日銷鎔當路岐。","龍宮御榜高可惜，火焚牛挽臨崎峗。","孔雀松殘赤琥珀，鴛鴦瓦碎青琉璃。","今我前程能幾許，徒有餘息筋力羸。","逢君話此空灑涕，却憶歡娛無見期。","主翁莫泣聽我語，寧勞感舊休吁嘻。","河清海宴不難覩，我皇已上昇平基。","湟中土地昔湮沒，昨夜收復無瘡痍。","戎王北走棄青塚，虜馬西奔空月支。","兩逢堯年豈易偶，願翁頤養豐膚肌。","平明酒醒便分首，今夕一樽翁莫違。"]', '["津陽门北臨通逵，雪风獵獵飄酒旗。","泥寒欵段蹶不進，疲童退问前何爲。","酒家顧客催解裝，案前羅列樽與巵。","青錢瑣屑安足數，白醪軟美甘如飴。","开壚引满相獻酬，枯腸渴肺忘朝飢。","愁憂似见出门去，漸覺春色入四肢。","主翁移客挑华灯，雙肩隐膝烏帽欹。","笑云鮐老不爲禮，飄蕭雪鬢雙垂頤。","问余何往凌寒曦，顧翁枯朽郎豈知。","翁曾豪盛客不见，我自爲君陳昔时。","时平親衛號羽林，我纔十五爲孤兒。","射熊搏虎衆莫敵，彎弧出入隨佽飞。","此时初創观风楼，簷高百尺堆华榱。","楼南更起鬬雞殿，晨光出影相參差。","其年十月移禁仗，山下櫛比羅百司。","朝元閣成老君见，會昌縣以新豐移。","幽州晓進供奉马，玉珂寶勒黄金羈。","五王扈駕夾城路，傳声校獵渭水湄。","羽林六軍各出射，籠山絡野張罝維。","彫弓繡韣不知數，翻身滅沒皆蛾眉。","赤鷹黄鶻云中来，妖狐狡兔無所依。","人煩马殆禽獸尽，百里腥膻禾黍稀。","暖山度臘东风微，宮娃賜浴长湯池。","刻成玉蓮噴香液，漱迴煙浪深逶迤。","犀屏象薦杂羅列，錦鳧繡雁相追隨。","破簪碎鈿不足拾，金溝殘溜和纓緌。","上皇寬容易承事，十家三国爭光輝。","繞牀呼盧恣樗博，張灯達晝相謾欺。","相君侈擬縱驕橫，日從秦虢多游嬉。","朱衫马前未满足，更驱武卒羅旌旗。","畫輪寶軸從天来，云中笑語声融怡。","鳴鞭後騎何躞蹀，宮粧襟袖皆仙姿。","青门紫陌多春风，风中數日殘春遺。","驪駒吐沬一奮迅，路人擁篲爭珠璣。","八姨新起合歡堂，翔鵾賀燕無由窺。","万金酬工不肯去，矜能恃巧猶嗟咨。","四方節制傾附媚，窮奢極侈沽恩私。","堂中特設夜明枕，銀燭不張光鑒帷。","瑤光楼南皆紫禁，梨园仙宴臨花枝。","迎娘歌喉玉𥦖窱，蠻兒舞带金葳蕤。","三郎紫笛弄煙月，怨如別鹤呼羈雌。","玉奴琵琶龙香撥，倚歌促酒声嬌悲。","饮鹿泉邊春露晞，粉梅檀杏飄朱墀。","金沙洞口长生殿，玉蘂峰头王母祠。","禁庭術士多幻化，上前較勝紛相持。","羅公如意奪顏色，三藏袈裟成散絲。","蓬萊池上望秋月，無云万里懸清輝。","上皇夜半月中去，三十六宮愁不归。","月中秘乐天半间，丁璫玉石和塤篪。","宸聰听覽未終曲，却到人间迷是非。","千秋御節在八月，會同万国朝华夷。","花萼楼南大合乐，八音九奏鸾来儀。","都盧尋橦誠齷齪，公孫劒伎方神奇。","马知舞徹下牀榻，人惜曲終更羽衣。","祿山此时侍御側，金雞畫障當罘罳。","繡{衤羽}衣褓日屓贔，甘言狡計愈嬌癡。","詔令上路建甲第，楼通走马如飞翬。","大开內府恣供給，玉缶金筐銀簸箕。","異謀潛熾促归去，臨軒賜带盈十圍。","忠臣張公識逆狀，日日切諫上弗疑。","湯成召浴果不至，潼关已溢漁陽師。","御街一夕無禁鼓，玉輅順动西南驰。","九门回望塵坌多，六龙夜馭兵衛疲。","縣官無人具軍頓，行宮徹屋屠云螭。","马嵬驛前駕不發，宰相射殺冤者誰。","长眉鬒髮作凝血，空有君王潛涕洟。","青泥坂上到三蜀，金堤城邊止九旂。","移文泣祭昔臣墓，度曲悲歌秋雁辞。","明年尚父上捷书，洗清观闕收封畿。","兩君相见望賢頓，君臣鼓舞皆歔欷。","宮中親呼高驃騎，潛令改葬楊真妃。","花膚雪豔不复见，空有香囊和泪滋。","鑒輿却入华清宮，满山紅實垂相思。","飞霜殿前月悄悄，迎春亭下风颸颸。","雪衣女失玉籠在，长生鹿瘦銅牌垂。","象牀塵凝罨颯被，畫檐蟲網頗梨碑。","碧菱花覆云母陵，风篁雨菊低離披。","真人影帳偏生草，果老藥堂空掩扉。","鼎湖一日失弓劒，橋山煙草俄霏霏。","空闻玉椀入金市，但见銅壺飄翠帷。","开元到今踰十紀，當初事跡皆殘隳。","竹花唯養棲梧鳳，水藻周游巢葉龟。","會昌御宇斥內典，去留二敎分黄緇。","慶山汙瀦石甕毀，紅楼綠閣皆支離。","奇松怪柏爲樵蘇，童山眢谷亡嶮巇。","煙中壁碎摩詰畫，云间字失玄宗诗。","石鱼巖底百尋井，銀牀下卷紅綆遲。","當时清影蔭紅葉，一旦飞埃埋素規。","韓家燭台倚林杪，千枝燦若山霞摛。","昔年光彩奪天月，昨日銷鎔當路岐。","龙宮御榜高可惜，火焚牛挽臨崎峗。","孔雀松殘赤琥珀，鴛鴦瓦碎青琉璃。","今我前程能幾許，徒有餘息筋力羸。","逢君話此空灑涕，却憶歡娛無见期。","主翁莫泣听我語，寧勞感旧休吁嘻。","河清海宴不难覩，我皇已上昇平基。","湟中