INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6888771c-0035-44d4-a643-a63de93cb9f5', '春日即事', '春日即事', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["一百五日又欲來，梨花梅花參差開。","行人自笑不歸去，瘦馬獨吟真可哀。","杏酪漸香鄰舍粥，榆煙將變舊爐灰。","畫橋春煖清歌夜，肯信愁腸日九迴。"]', '["一百五日又欲来，梨花梅花參差开。","行人自笑不归去，瘦马独吟真可哀。","杏酪漸香鄰舍粥，榆煙將变旧爐灰。","畫橋春煖清歌夜，肯信愁腸日九迴。"]', '诗', 'shi', '', NULL, '春日即事 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0b1ac1-e3f6-4ab7-8b7d-626e5efbbdd1', '春晚岳陽言懷二首 一', '春晚岳陽言懷二首 一', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["煙花零落過清明，異國光陰老客情。","雲夢夕陽愁裏色，洞庭春浪坐來聲。","天邊一與舊山別，江上幾看芳草生。","獨倚闌干意難寫，暮笳嗚咽調孤城。"]', '["煙花零落過清明，異国光陰老客情。","云梦夕陽愁裏色，洞庭春浪坐来声。","天邊一與旧山別，江上幾看芳草生。","独倚闌干意难寫，暮笳嗚咽調孤城。"]', '诗', 'shi', '', NULL, '春晚岳陽言懷二首 一 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2611bd4a-0cca-46d2-8fed-25809965bda6', '春晚岳陽言懷二首 二', '春晚岳陽言懷二首 二', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["翠煙如鈿柳如環，晴倚南樓獨看山。","江國草花三月暮，帝城塵夢一年間。","虛舟尚歎縈難解，飛鳥空慚倦未還。","何似不羈詹父伴，睡煙歌月老潺潺。"]', '["翠煙如鈿柳如环，晴倚南楼独看山。","江国草花三月暮，帝城塵梦一年间。","虛舟尚歎縈难解，飞鸟空慚倦未還。","何似不羈詹父伴，睡煙歌月老潺潺。"]', '诗', 'shi', '', NULL, '春晚岳陽言懷二首 二 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ea037e-2b8c-41fa-8cc4-64c630bff399', '過蠻溪渡', '過蠻溪渡', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["綠楊如髮雨如煙，立馬危橋獨喚船。","山口斷雲迷舊路，渡頭芳草憶前年。","身隨遠道徒悲梗，詩賣明時不直錢。","歸去楚臺還有計，釣船春雨日高眠。"]', '["綠楊如髮雨如煙，立马危橋独喚船。","山口斷云迷旧路，渡头芳草憶前年。","身隨远道徒悲梗，诗賣明时不直錢。","归去楚台還有計，釣船春雨日高眠。"]', '诗', 'shi', '', NULL, '過蠻溪渡 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e992683a-6cc0-4e22-8f48-9125879db9dd', '岸梅', '岸梅', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["含情含怨一枝枝，斜壓漁家短短籬。","惹袖尚餘香半日，向人如訴雨多時。","初開偏稱雕梁畫，未落先愁玉笛吹。","行客見來無去意，解帆煙浦爲題詩。"]', '["含情含怨一枝枝，斜壓漁家短短籬。","惹袖尚餘香半日，向人如訴雨多时。","初开偏稱雕梁畫，未落先愁玉笛吹。","行客见来無去意，解帆煙浦爲題诗。"]', '诗', 'shi', '', NULL, '岸梅 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8dab2b-89ba-4d6c-936f-b044dde69523', '重陽日次荆南路經武寧驛', '重陽日次荆南路經武寧驛', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["茱萸冷吹溪口香，菊花倒遶山脚黃。","家山去此強百里，弟妹待我醉重陽。","風健旱鴻高曉景，露清圓碧照秋光。","莫看時節年年好，暗送搔頭逐手霜。"]', '["茱萸冷吹溪口香，菊花倒遶山脚黄。","家山去此強百里，弟妹待我醉重陽。","风健旱鴻高晓景，露清圓碧照秋光。","莫看时節年年好，暗送搔头逐手霜。"]', '诗', 'shi', '', NULL, '重陽日次荆南路經武寧驛 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1374cea5-5c8b-4afc-8d09-edf0b2f78e81', '述懷', '述懷', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["白首成何事，無歡可替悲。","空餘酒中興，猶似少年時。"]', '["白首成何事，無歡可替悲。","空餘酒中兴，猶似少年时。"]', '诗', 'shi', '', NULL, '述懷 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d649c2c-c094-491a-90be-53512bd5ef1d', '三月晦日送客', '三月晦日送客', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["野酌亂無巡，送君兼送春。","明年春色至，莫作未歸人。"]', '["野酌亂無巡，送君兼送春。","明年春色至，莫作未归人。"]', '诗', 'shi', '', NULL, '三月晦日送客 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9af6d93-8514-4d85-b8c8-0ac656e318db', '華清宮三首 一', '华清宮三首 一', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["草遮回蹬絕鳴鑾，雲樹深深碧殿寒。","明月自來還自去，更無人倚玉欄干。"]', '["草遮回蹬絕鳴鑾，云樹深深碧殿寒。","明月自来還自去，更無人倚玉欄干。"]', '诗', 'shi', '', NULL, '華清宮三首 一 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66930c4d-ac8b-40a3-8cd0-3b62393621f1', '華清宮三首 二', '华清宮三首 二', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["障掩金雞蓄禍機，翠華西拂蜀雲飛。","珠簾一閉朝元閣，不見人歸見燕歸。"]', '["障掩金雞蓄禍機，翠华西拂蜀云飞。","珠簾一閉朝元閣，不见人归见燕归。"]', '诗', 'shi', '', NULL, '華清宮三首 二 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55aaea9-b95c-4135-b978-1f1927ce1cc0', '華清宮三首 三', '华清宮三首 三', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["門橫金鎖悄無人，落日秋聲渭水濱。","紅葉下山寒寂寂，濕雲如夢雨如塵。"]', '["门橫金鎖悄無人，落日秋声渭水濱。","紅葉下山寒寂寂，濕云如梦雨如塵。"]', '诗', 'shi', '', NULL, '華清宮三首 三 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f693478-960f-471e-8ba3-ae1e2d91a9c8', '題雲夢亭', '題云梦亭', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["薄煙如夢雨如塵，霜景晴來卻勝春。","好住池西紅葉樹，何年今日伴何人。"]', '["薄煙如梦雨如塵，霜景晴来卻勝春。","好住池西紅葉樹，何年今日伴何人。"]', '诗', 'shi', '', NULL, '題雲夢亭 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf519daa-eccb-4adf-ad87-0b8946a2719a', '有酒失於虔州陸郎中肱以詩謝之', '有酒失於虔州陸郎中肱以诗謝之', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["醉時顛蹶醒時羞，麴糵推人不自由。","叵耐一雙窮相眼，不堪花卉在前頭。"]', '["醉时顛蹶醒时羞，麴糵推人不自由。","叵耐一雙窮相眼，不堪花卉在前头。"]', '诗', 'shi', '', NULL, '有酒失於虔州陸郎中肱以詩謝之 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a591b0-7101-4fa1-ba22-a6bfe5fe00dc', '聞笛', '闻笛', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["銀河漾漾月暉暉，樓礙星邊織女機。","橫玉叫雲天似水，滿空霜逐一聲飛。"]', '["銀河漾漾月暉暉，楼礙星邊织女機。","橫玉叫云天似水，满空霜逐一声飞。"]', '诗', 'shi', '', NULL, '聞笛 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d29ca8-addb-47f7-b7da-050eba1f7bb9', '山路見花', '山路见花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["曉紅初拆露香新，獨立空山冷笑人。","春意自知無主惜，恣風吹逐馬蹄塵。"]', '["晓紅初拆露香新，独立空山冷笑人。","春意自知無主惜，恣风吹逐马蹄塵。"]', '诗', 'shi', '', NULL, '山路見花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b02bba6-59b2-44b9-8766-c581a55ccc64', '暮春對花', '暮春对花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["病香無力被風欺，多在青苔少在枝。","馬上行人莫回首，斷君腸是欲殘時。"]', '["病香無力被风欺，多在青苔少在枝。","马上行人莫回首，斷君腸是欲殘时。"]', '诗', 'shi', '', NULL, '暮春對花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6595e0a9-cc53-4b80-b030-e7b74de97cc0', '句', '句', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["強半瘦因前夜雪，數枝愁向晚天來。","無人解把無塵袖，盛取殘香盡日憐。","一番春雨吹巢冷，半朵山花咽觜香。","雲生柱礎降龍地，露洗林巒放鶴天。","菱葉乍翻人採後，荇花初沒舸行時。"]', '["強半瘦因前夜雪，數枝愁向晚天来。","無人解把無塵袖，盛取殘香尽日怜。","一番春雨吹巢冷，半朵山花咽觜香。","云生柱礎降龙地，露洗林巒放鹤天。","菱葉乍翻人採後，荇花初沒舸行时。"]', '诗', 'shi', '', NULL, '句 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628527d2-e757-437e-86cd-88daa0a48338', '烏夜號', '烏夜號', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["層波隔夢渚，一望青楓林。","有鳥在其間，達曉自悲吟。","是時月黑天，四野煙雨深。","如聞生離哭，其聲痛人心。","悄悄夜正長，空山響哀音。","遠客不可聽，坐愁華髮侵。","既非蜀帝魂，恐是桓山禽。","四子各分散，母聲猶至今。"]', '["層波隔梦渚，一望青楓林。","有鸟在其间，達晓自悲吟。","是时月黑天，四野煙雨深。","如闻生離哭，其声痛人心。","悄悄夜正长，空山响哀音。","远客不可听，坐愁华髮侵。","既非蜀帝魂，恐是桓山禽。","四子各分散，母声猶至今。"]', '诗', 'shi', '', NULL, '烏夜號 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a85ae87e-c49e-4b8d-af9b-4def60bc555e', '昇仙操', '昇仙操', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["嬴女去秦宮，瓊笙飛碧空。","鳳臺閉煙霧，鸞吹飄天風。","復聞周太子，亦遇浮丘公。","叢簧發天弄，輕舉紫霞中。","濁世不久駐，清都路何窮。","一去霄漢上，世人那得逢。"]', '["嬴女去秦宮，瓊笙飞碧空。","鳳台閉煙霧，鸾吹飄天风。","复闻周太子，亦遇浮丘公。","叢簧發天弄，轻舉紫霞中。","濁世不久駐，清都路何窮。","一去霄漢上，世人那得逢。"]', '诗', 'shi', '', NULL, '昇仙操 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7bd5b2d-55c0-42fb-a451-e2dc688a2686', '雨夜呈長官', '雨夜呈长官', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["遠客坐長夜，雨聲孤寺秋。","請量東海水，看取淺深愁。","愁窮重於山，終年壓人頭。","朱顏與芳景，暗赴東波流。","鱗翼思風水，青雲方阻修。","孤燈冷素豔，蟲響寒房幽。","借問陶淵明，何物號忘憂。","無因一酩酊，高枕萬情休。"]', '["远客坐长夜，雨声孤寺秋。","請量东海水，看取淺深愁。","愁窮重於山，終年壓人头。","朱顏與芳景，暗赴东波流。","鱗翼思风水，青云方阻修。","孤灯冷素豔，蟲响寒房幽。","借问陶淵明，何物號忘憂。","無因一酩酊，高枕万情休。"]', '诗', 'shi', '', NULL, '雨夜呈長官 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530ef76a-4fa3-476b-8ae5-24b469c1dcd7', '小弟艎南遊近書來', '小弟艎南游近书来', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["湘南客帆稀，遊子寡消息。","經時停尺素，望盡雲邊翼。","笑言頻夢寐，獨立想容色。","落景無來人，修江入天白。","停停倚門念，瑟瑟風雨夕。","何處泊扁舟，迢遰湍波側。","秋歸舊窗竹，永夜一淒寂。","吟爾鶺鴒篇，中宵慰相憶。"]', '["湘南客帆稀，游子寡消息。","經时停尺素，望尽云邊翼。","笑言頻梦寐，独立想容色。","落景無来人，修江入天白。","停停倚门念，瑟瑟风雨夕。","何处泊扁舟，迢遰湍波側。","秋归旧窗竹，永夜一淒寂。","吟爾鶺鴒篇，中宵慰相憶。"]', '诗', 'shi', '', NULL, '小弟艎南遊近書來 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3993e8-4e3c-4a20-9665-d500360e246b', '贈方處士', '贈方处士', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["白衣方外人，高閑溪中鶴。","無心戀稻粱，但以林泉樂。","赤霄終得意，天池俟飛躍。","歲晏入帝鄉，期君在寥廓。"]', '["白衣方外人，高闲溪中鹤。","無心戀稻粱，但以林泉乐。","赤霄終得意，天池俟飞躍。","歲晏入帝乡，期君在寥廓。"]', '诗', 'shi', '', NULL, '贈方處士 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1740b3-c2bf-4591-b539-b9e66b68ea6d', '秋怨', '秋怨', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["瑟瑟涼海氣，西來送愁容。","金風死綠蕙，玉露生寒松。","所思在溟碧，無因一相逢。","登樓睇去翼，目盡滄波重。","虛窗度流螢，斜月啼幽蛩。","疎紅落殘豔，冷水凋芙蓉。","歲暮空太息，年華逐遺踪。","凝情耿不寐，攬涕起疎慵。"]', '["瑟瑟涼海氣，西来送愁容。","金风死綠蕙，玉露生寒松。","所思在溟碧，無因一相逢。","登楼睇去翼，目尽滄波重。","虛窗度流螢，斜月啼幽蛩。","疎紅落殘豔，冷水凋芙蓉。","歲暮空太息，年华逐遺踪。","凝情耿不寐，攬涕起疎慵。"]', '诗', 'shi', '', NULL, '秋怨 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c9f0ed-ed3c-429a-b5fc-416083b335b2', '感春', '感春', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["春情不可狀，豔豔令人醉。","暮水綠楊愁，深窗落花思。","吳宮新暖日，海燕雙飛至。","秋思逐煙光，空濛滿天地。"]', '["春情不可狀，豔豔令人醉。","暮水綠楊愁，深窗落花思。","吳宮新暖日，海燕雙飞至。","秋思逐煙光，空濛满天地。"]', '诗', 'shi', '', NULL, '感春 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29d2129-1f90-4c70-bcda-383046feb5de', '山中秋夕', '山中秋夕', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["抱琴出南樓，氣爽浮雲滅。","松風吹天簫，竹路踏碎月。","後山鶴唳定，前浦荷香發。","境寂良夜深，了與人間別。"]', '["抱琴出南楼，氣爽浮云滅。","松风吹天簫，竹路踏碎月。","後山鹤唳定，前浦荷香發。","境寂良夜深，了與人间別。"]', '诗', 'shi', '', NULL, '山中秋夕 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('404322da-384b-43c6-b893-725402b463a0', '將遊羅浮登廣陵楞伽臺別羽客', '將游羅浮登廣陵楞伽台別羽客', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["清遠登高臺，晃朗縱覽歷。","濯泉喚仙風，於此盪靈魄。","冷光邀遠目，百里見海色。","送雲歸蓬壺，望鶴滅秋碧。","波瀾收日氣，天自回澄寂。","百越落掌中，十洲點空白。","身居飛鳥上，口詠玄元籍。","飄如出塵籠，想望吹簫客。","冥冥人間世，歌笑不足惜。","朅來羅浮巔，披雲煉瓊液。","謝公雲岑興，可以躡高跡。","吾將抱瑤琴，絕境縱所適。"]', '["清远登高台，晃朗縱覽歷。","濯泉喚仙风，於此盪靈魄。","冷光邀远目，百里见海色。","送云归蓬壺，望鹤滅秋碧。","波瀾收日氣，天自回澄寂。","百越落掌中，十洲点空白。","身居飞鸟上，口詠玄元籍。","飄如出塵籠，想望吹簫客。","冥冥人间世，歌笑不足惜。","朅来羅浮巔，披云煉瓊液。","謝公云岑兴，可以躡高跡。","吾將抱瑤琴，絕境縱所適。"]', '诗', 'shi', '', NULL, '將遊羅浮登廣陵楞伽臺別羽客 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4167338-a88d-42bf-b436-35a768b4b778', '盧溪道中', '盧溪道中', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["曉發潺湲亭，夜宿潺湲水。","風篁掃石瀨，琴聲九十里。","光奔覺來眼，寒落夢中耳。","曾向三峽行，巴江亦如此。"]', '["晓發潺湲亭，夜宿潺湲水。","风篁掃石瀨，琴声九十里。","光奔覺来眼，寒落梦中耳。","曾向三峽行，巴江亦如此。"]', '诗', 'shi', '', NULL, '盧溪道中 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c9bdc93-aa10-43a6-9c24-b46e941f4dbf', '湖中古愁三首 一', '湖中古愁三首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["涼風西海來，直渡洞庭水。","翛翛木葉下，白浪連天起。","蘅蘭委皓雪，百草一時死。","摧殘負志人，感歎何窮已。"]', '["涼风西海来，直渡洞庭水。","翛翛木葉下，白浪連天起。","蘅蘭委皓雪，百草一时死。","摧殘負志人，感歎何窮已。"]', '诗', 'shi', '', NULL, '湖中古愁三首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32083c21-f38b-4576-93f8-7dda5f34ff6b', '湖中古愁三首 二', '湖中古愁三首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["昔我覩雲夢，窮秋經汨羅。","靈均竟不返，怨氣成微波。","奠桂開古祠，朦朧入幽蘿。","落日瀟湘上，淒涼吟九歌。"]', '["昔我覩云梦，窮秋經汨羅。","靈均竟不返，怨氣成微波。","奠桂开古祠，朦朧入幽蘿。","落日瀟湘上，淒涼吟九歌。"]', '诗', 'shi', '', NULL, '湖中古愁三首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('614ec9da-1be9-4d6e-813b-a029127f32c3', '湖中古愁三首 三', '湖中古愁三首 三', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["南雲哭重華，水死悲二女。","天邊九點黛，白骨迷處所。","朦朧波上瑟，清夜降北渚。","萬古一雙魂，飄飄在煙雨。"]', '["南云哭重华，水死悲二女。","天邊九点黛，白骨迷处所。","朦朧波上瑟，清夜降北渚。","万古一雙魂，飄飄在煙雨。"]', '诗', 'shi', '', NULL, '湖中古愁三首 三 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c667c63-e96a-41c7-8185-9284534a31fa', '別狄佩', '別狄佩', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["翠竹不著花，鳳雛長忍飢。","未開丹霄翮，空把碧梧枝。","聖人奏雲韶，祥鳳一來儀。","文章耀白日，衆鳥莫敢窺。","鬱抑不自言，凡鳥何由知。","當看九千仞，飛出太平時。"]', '["翠竹不著花，鳳雛长忍飢。","未开丹霄翮，空把碧梧枝。","聖人奏云韶，祥鳳一来儀。","文章耀白日，衆鸟莫敢窺。","鬱抑不自言，凡鸟何由知。","當看九千仞，飞出太平时。"]', '诗', 'shi', '', NULL, '別狄佩 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af80c94-ce50-4394-8c4b-ca5bb9be4186', '古鏡', '古镜', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["明月何處來，朦朧在人境。","得非軒轅作，妙絕世莫竝。","瑤匣開旭日，白電走孤影。","泓澄一尺天，徹底寒霜景。","冰輝凜毛髮，使我肝膽冷。","忽驚行深幽，面落九秋井。","雲天入掌握，爽朗神魂淨。","不必負局仙，金沙發光炯。","陰沈蓄靈怪，可與天地永。","恐爲悲龍吟，飛去在俄頃。"]', '["明月何处来，朦朧在人境。","得非軒轅作，妙絕世莫竝。","瑤匣开旭日，白電走孤影。","泓澄一尺天，徹底寒霜景。","冰輝凜毛髮，使我肝膽冷。","忽驚行深幽，面落九秋井。","云天入掌握，爽朗神魂淨。","不必負局仙，金沙發光炯。","陰沈蓄靈怪，可與天地永。","恐爲悲龙吟，飞去在俄頃。"]', '诗', 'shi', '', NULL, '古鏡 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86c6de0-4b6c-4841-86e1-4a9924b9761f', '我思何所在', '我思何所在', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["我思何所在，乃在陽臺側。","良宵相望時，空此明月色。","歸魂泊湘雲，飄蕩去不得。","覺來理舟檝，波浪春湖白。","煙光浩楚秋，瑤草不忍摘。","因書天末心，繫此雙飛翼。"]', '["我思何所在，乃在陽台側。","良宵相望时，空此明月色。","归魂泊湘云，飄蕩去不得。","覺来理舟檝，波浪春湖白。","煙光浩楚秋，瑤草不忍摘。","因书天末心，繫此雙飞翼。"]', '诗', 'shi', '', NULL, '我思何所在 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c430f15-548e-491d-a1cc-8e03d067655c', '送蕭綰之桂林', '送蕭綰之桂林', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["蘭香佩蘭人，弄蘭蘭江春。","爾爲蘭林秀，芳藻驚常倫。","燦燦鳳池裔，一毛今再新。","竹花不給口，憔悴清湘濱。","一朝南溟飛，彩翮不可親。","蒼梧雲水晚，離思空凝顰。","我亦縱煙櫂，西浮彭蠡津。","丈夫未虎變，落魄甘風塵。","大禹惜寸陰，況我無才身。","流光銷道路，以此生嗟辛。","萬里闊分袂，相思杳難申。","桂水秋更碧，寄書西上鱗。"]', '["蘭香佩蘭人，弄蘭蘭江春。","爾爲蘭林秀，芳藻驚常倫。","燦燦鳳池裔，一毛今再新。","竹花不給口，憔悴清湘濱。","一朝南溟飞，彩翮不可親。","蒼梧云水晚，離思空凝顰。","我亦縱煙櫂，西浮彭蠡津。","丈夫未虎变，落魄甘风塵。","大禹惜寸陰，況我無才身。","流光銷道路，以此生嗟辛。","万里闊分袂，相思杳难申。","桂水秋更碧，寄书西上鱗。"]', '诗', 'shi', '', NULL, '送蕭綰之桂林 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d77e4e4-856f-4eac-a140-43ceb4cb7e67', '感興四首 一', '感兴四首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["子雲吞白鳳，遂吐太玄書。","幽微十萬字，枝葉何扶疎。","婉孌猛虎口，甘言累其初。","一覩美新作，斯瑕安可除。"]', '["子云吞白鳳，遂吐太玄书。","幽微十万字，枝葉何扶疎。","婉孌猛虎口，甘言累其初。","一覩美新作，斯瑕安可除。"]', '诗', 'shi', '', NULL, '感興四首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1b91a7-53c5-4c92-b4de-965158b853ea', '感興四首 二', '感兴四首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["昔竊不死藥，奔空有嫦娥。","盈盈天上豔，孤潔棲金波。","織女了無語，長宵隔銀河。","軋軋揮素手，幾時停玉梭。"]', '["昔竊不死藥，奔空有嫦娥。","盈盈天上豔，孤潔棲金波。","织女了無語，长宵隔銀河。","軋軋揮素手，幾时停玉梭。"]', '诗', 'shi', '', NULL, '感興四首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf4326c-6369-43ba-95bc-2ae73da4a51f', '感興四首 三', '感兴四首 三', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["洞房三五夕，金釭凝焰滅。","美人抱雲和，斜倚紗窗月。","沈吟想幽夢，閨思深不說。","弦冷玉指寒，含顰待明發。"]', '["洞房三五夕，金釭凝焰滅。","美人抱云和，斜倚紗窗月。","沈吟想幽梦，閨思深不说。","弦冷玉指寒，含顰待明發。"]', '诗', 'shi', '', NULL, '感興四首 三 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5228be-2f54-4d0a-8856-2016c6086f51', '感興四首 四', '感兴四首 四', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["朔雁銜邊秋，寒聲落燕代。","先驚愁人耳，顏髮潛消改。","凝雲蔽洛浦，夢寐勞光彩。","天邊無書來，相思淚成海。"]', '["朔雁銜邊秋，寒声落燕代。","先驚愁人耳，顏髮潛消改。","凝云蔽洛浦，梦寐勞光彩。","天邊無书来，相思泪成海。"]', '诗', 'shi', '', NULL, '感興四首 四 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3442a4b4-c259-49d4-a36e-e187d6212da0', '將之吳越留別坐中文酒諸侶', '將之吳越留別坐中文酒諸侶', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["秋色滿水國，江湖興蕭然。","氛埃斂八極，萬里淨澄鮮。","涔浦縱孤櫂，吳門渺三千。","迴隨衡陽雁，南入洞庭天。","早聞陸士龍，矯掌跨山川。","非思鱸魚膾，且弄五湖船。","暝泊遠浦霞，曉飯蘆洲煙。","風流訪王謝，佳境恣洄沿。","霜剪別岸柳，香枯北池蓮。","歲華坐搖落，寂寂感流年。","明朝即漂萍，離憾無由宣。"]', '["秋色满水国，江湖兴蕭然。","氛埃斂八極，万里淨澄鲜。","涔浦縱孤櫂，吳门渺三千。","迴隨衡陽雁，南入洞庭天。","早闻陸士龙，矯掌跨山川。","非思鱸鱼膾，且弄五湖船。","暝泊远浦霞，晓飯蘆洲煙。","风流訪王謝，佳境恣洄沿。","霜剪別岸柳，香枯北池蓮。","歲华坐搖落，寂寂感流年。","明朝即漂萍，離憾無由宣。"]', '诗', 'shi', '', NULL, '將之吳越留別坐中文酒諸侶 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('760d0a75-788f-4cb8-a91a-b7f58eb8a898', '大雲池泛舟', '大云池泛舟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["九月蓮花死，萍枯霜水清。","船浮天光遠，櫂拂翠瀾輕。","古木□□□，了無煙靄生。","游鱗泳皎潔，洞見逍遙情。","漁父一曲歌，滄浪遂知名。","未知斯水上，可以濯吾纓。"]', '["九月蓮花死，萍枯霜水清。","船浮天光远，櫂拂翠瀾轻。","古木□□□，了無煙靄生。","游鱗泳皎潔，洞见逍遙情。","漁父一曲歌，滄浪遂知名。","未知斯水上，可以濯吾纓。"]', '诗', 'shi', '', NULL, '大雲池泛舟 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f8cd5b-d88f-4bd4-b198-a00da4f1be6d', '送友人之峽', '送友人之峽', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["東吳有賦客，願識陽臺仙。","彩毫飛白雲，不減郢中篇。","楚水五月浪，輕舟入暮煙。","巫雲多感夢，桂檝早回旋。"]', '["东吳有賦客，願識陽台仙。","彩毫飞白云，不減郢中篇。","楚水五月浪，轻舟入暮煙。","巫云多感梦，桂檝早回旋。"]', '诗', 'shi', '', NULL, '送友人之峽 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2dc6859-8cc9-49fd-a5dd-73c15437a51d', '登宜春醉宿景星寺寄鄭判官兼簡空上人', '登宜春醉宿景星寺寄鄭判官兼簡空上人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["曉發碧水陽，暝宿金山寺。","松風灑寒雨，淅瀝醒餘醉。","夜中香積飯，蔬粒俱精異。","境寂滅塵愁，神高得詩思。","皎皎滎陽子，芳春富才義。","漲海豁心源，冰壺見門地。","碧霄有鳩序，未展聯行翅。","俱笑一尺繩，三年絆騏驥。","摧藏擔簦客，鬱抑胸襟事。","名業爾未從，臨風嘿舒志。","一身渺雲嶺，中夜空涕泗。","側枕對孤燈，衾寒不成寐。","糧薪極桂玉，大道生榛刺。","耻息惡木陰，難書劒歌意。","揚鞭入莽蒼，山驛凌煙翠。","越鳥日南飛，芳音願相次。"]', '["晓發碧水陽，暝宿金山寺。","松风灑寒雨，淅瀝醒餘醉。","夜中香積飯，蔬粒俱精異。","境寂滅塵愁，神高得诗思。","皎皎滎陽子，芳春富才義。","漲海豁心源，冰壺见门地。","碧霄有鳩序，未展聯行翅。","俱笑一尺繩，三年絆騏驥。","摧藏擔簦客，鬱抑胸襟事。","名業爾未從，臨风嘿舒志。","一身渺云嶺，中夜空涕泗。","側枕对孤灯，衾寒不成寐。","糧薪極桂玉，大道生榛刺。","耻息惡木陰，难书劒歌意。","揚鞭入莽蒼，山驛凌煙翠。","越鸟日南飞，芳音願相次。"]', '诗', 'shi', '', NULL, '登宜春醉宿景星寺寄鄭判官兼簡空上人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be4c7b2-39b9-49d4-a8d7-6aeb97cc095e', '江樓獨酌懷從叔', '江楼独酌懷從叔', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["水國發爽氣，川光靜高秋。","酣歌金尊醁，送此清風愁。","楚色忽滿目，灘聲落西樓。","雲翻天邊葉，月弄波上鉤。","芳意長搖落，蘅蘭謝汀洲。","長吟碧雲合，悵望江之幽。"]', '["水国發爽氣，川光静高秋。","酣歌金尊醁，送此清风愁。","楚色忽满目，灘声落西楼。","云翻天邊葉，月弄波上鉤。","芳意长搖落，蘅蘭謝汀洲。","长吟碧云合，悵望江之幽。"]', '诗', 'shi', '', NULL, '江樓獨酌懷從叔 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb080ad-48cf-4187-a6ea-d6b431945387', '登章華樓', '登章华楼', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["楚子故宮地，蒼然雲水秋。","我來覽從事，落景空生愁。","伯業沒荆棘，雄圖成古丘。","沈吟問鼎語，但見東波流。","征鴻引鄉心，一去何悠悠。","晴湖碧雲晚，暝色空高樓。","迢遰趨遠嶠，微茫入孤舟。","空路不堪望，西風白浪稠。"]', '["楚子故宮地，蒼然云水秋。","我来覽從事，落景空生愁。","伯業沒荆棘，雄圖成古丘。","沈吟问鼎語，但见东波流。","征鴻引乡心，一去何悠悠。","晴湖碧云晚，暝色空高楼。","迢遰趨远嶠，微茫入孤舟。","空路不堪望，西风白浪稠。"]', '诗', 'shi', '', NULL, '登章華樓 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93485a55-27ee-4f7b-a6a0-128ac61a858c', '驄馬', '驄马', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["浮雲何權奇，絕足世未知。","長嘶清海風，蹀躞振雲絲。","由來渥洼種，本是蒼龍兒。","穆滿不再活，無人崑閬騎。","若識躍嶠怯，寧勞耀金羈。","青芻與白水，空笑駑駘肥。","伯樂儻一見，應驚耳長垂。","當思八荒外，逐日向瑤池。"]', '["浮云何權奇，絕足世未知。","长嘶清海风，蹀躞振云絲。","由来渥洼種，本是蒼龙兒。","穆满不再活，無人崑閬騎。","若識躍嶠怯，寧勞耀金羈。","青芻與白水，空笑駑駘肥。","伯乐儻一见，應驚耳长垂。","當思八荒外，逐日向瑤池。"]', '诗', 'shi', '', NULL, '驄馬 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('857e4e1c-5a8b-4152-965c-f8781faf916c', '贈方處士兼以寫別', '贈方处士兼以寫別', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["天與雲鶴情，人間恣詩酒。","龍宮奉採覓，澒洞一千首。","清如南薰絲，韻若黃鍾吼。","喜於風騷地，忽見陶謝手。","籍籍九江西，篇篇在人口。","芙蓉爲芳菲，未落諸花後。","所知心眼大，別自開戶牖。","才力似風鵬，誰能算升斗。","無營傲雲竹，琴帙靜爲友。","鸞鳳戢羽儀，騏驥在郊藪。","鏡湖春水綠，越客憶歸否。","白衣四十秋，逍遙一何久。","此身無定跡，又逐浮雲走。","離思書不窮，殘陽落江柳。"]', '["天與云鹤情，人间恣诗酒。","龙宮奉採覓，澒洞一千首。","清如南薰絲，韻若黄鍾吼。","喜於风騷地，忽见陶謝手。","籍籍九江西，篇篇在人口。","芙蓉爲芳菲，未落諸花後。","所知心眼大，別自开戶牖。","才力似风鵬，誰能算升斗。","無營傲云竹，琴帙静爲友。","鸾鳳戢羽儀，騏驥在郊藪。","镜湖春水綠，越客憶归否。","白衣四十秋，逍遙一何久。","此身無定跡，又逐浮云走。","離思书不窮，殘陽落江柳。"]', '诗', 'shi', '', NULL, '贈方處士兼以寫別 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9523d9-de43-4d8f-9add-0e990804c7d0', '湘西寺霽夜', '湘西寺霽夜', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["雨過琉璃宮，佳興浩清絕。","松風冷晴灘，竹路踏碎月。","月波蕩如水，氣爽星朗滅。","皓夜千樹寒，崢嶸萬巖雪。","後山鶴唳斷，前池荷香發。","境寂涼夜深，神思空飛越。"]', '["雨過琉璃宮，佳兴浩清絕。","松风冷晴灘，竹路踏碎月。","月波蕩如水，氣爽星朗滅。","皓夜千樹寒，崢嶸万巖雪。","後山鹤唳斷，前池荷香發。","境寂涼夜深，神思空飞越。"]', '诗', 'shi', '', NULL, '湘西寺霽夜 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68686207-a94d-4f61-9a7c-90c517aba3ee', '傷思', '傷思', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["八月白露濃，芙蓉抱香死。","紅枯金粉墮，寥落寒塘水。","西風團葉下，疊縠參差起。","不見櫂歌人，空垂綠房子。"]', '["八月白露濃，芙蓉抱香死。","紅枯金粉墮，寥落寒塘水。","西风團葉下，叠縠參差起。","不见櫂歌人，空垂綠房子。"]', '诗', 'shi', '', NULL, '傷思 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8e6700-a4f4-4a7d-a5ca-823312ad46c6', '送鄭京昭之雲安', '送鄭京昭之云安', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["君吟高唐賦，路過巫山渚。","莫令巫山下，幽夢惹雲雨。","往事幾千年，芬菲今尚傳。","空留荆王館，巖嶂深蒼然。","楚水五月浪，輕舟入蘋煙。","送君揚檝去，愁絕郢城篇。"]', '["君吟高唐賦，路過巫山渚。","莫令巫山下，幽梦惹云雨。","往事幾千年，芬菲今尚傳。","空留荆王館，巖嶂深蒼然。","楚水五月浪，轻舟入蘋煙。","送君揚檝去，愁絕郢城篇。"]', '诗', 'shi', '', NULL, '送鄭京昭之雲安 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab89901-9d1d-4476-89b0-249c6716fc30', '送處士自番禺東遊便歸蘇臺別業', '送处士自番禺东游便归蘇台別業', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["啞軋暮江上，櫓聲搖落心。","宛陵三千里，路指吳雲深。","蓴菜動歸興，忽然聞會吟。","南浮龍川月，東下敬亭岑。","多君詠逍遙，結蘿碧溪陰。","高籠華表鶴，靜對幽蘭琴。","汗漫江海思，傲然抽冠簪。","歸嶼未云寂，還家應追尋。","二陸文苑秀，岧嶤懷所欽。","惜我入洛晚，不睹雙南金。","江左風流盡，名賢成古今。","送君無限意，別酒但加斟。"]', '["啞軋暮江上，櫓声搖落心。","宛陵三千里，路指吳云深。","蓴菜动归兴，忽然闻會吟。","南浮龙川月，东下敬亭岑。","多君詠逍遙，結蘿碧溪陰。","高籠华表鹤，静对幽蘭琴。","汗漫江海思，傲然抽冠簪。","归嶼未云寂，還家應追尋。","二陸文苑秀，岧嶤懷所欽。","惜我入洛晚，不睹雙南金。","江左风流尽，名賢成古今。","送君無限意，別酒但加斟。"]', '诗', 'shi', '', NULL, '送處士自番禺東遊便歸蘇臺別業 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0636722-7ab2-456a-aeee-48d366755146', '法華微上人盛話金山境勝舊遊在目吟成此篇', '法华微上人盛話金山境勝旧游在目吟成此篇', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["江上青蓮宮，人間蓬萊島。","煙霞與波浪，隱暎樓臺好。","潮門梵音靜，海日天光早。","願與靈鷲人，吟經此終老。"]', '["江上青蓮宮，人间蓬萊島。","煙霞與波浪，隐暎楼台好。","潮门梵音静，海日天光早。","願與靈鷲人，吟經此終老。"]', '诗', 'shi', '', NULL, '法華微上人盛話金山境勝舊遊在目吟成此篇 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5fb9e03-9aca-4f5b-a906-672e30fcec3d', '洞庭入澧江寄巴丘故人', '洞庭入澧江寄巴丘故人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["四月桑半枝，吳蠶初弄絲。","江行好風日，燕舞輕波時。","去事旋成夢，來歡難預期。","唯憑東流水，日夜寄相思。"]', '["四月桑半枝，吳蠶初弄絲。","江行好风日，燕舞轻波时。","去事旋成梦，来歡难預期。","唯憑东流水，日夜寄相思。"]', '诗', 'shi', '', NULL, '洞庭入澧江寄巴丘故人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070d66a9-c9a0-44a3-be22-af612fac4861', '自澧浦東遊江表途出巴丘投員外從公虞', '自澧浦东游江表途出巴丘投員外從公虞', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["短翮後飛者，前攀鸞鶴翔。","力微應萬里，矯首空蒼蒼。","誰昔探花源，考槃西岳陽。","高風動商洛，綺皓無馨香。","一朝下蒲輪，清輝照巖廊。","孤醒立衆醉，古道何由昌。","經術震浮盪，國風掃齊梁。","文襟即玄圃，筆下成琳琅。","霞水散吟嘯，松筠奉琴觴。","冰壺避皎潔，武庫羞鋒鋩。","小子書代耕，束髮頗自強。","艱哉水投石，壯志空摧藏。","十年侶龜魚，垂頭在沅湘。","巴歌揜白雪，鮑肆埋蘭芳。","騷雅道未喪，何憂名不彰。","飢寒束困厄，默塞飛星霜。","百志不成一，東波擲年光。","塵生脫粟甑，萬里違高堂。","中夜恨火來，焚燒九回腸。","平明梁山淚，緣枕霑匡牀。","依泊洞庭波，木葉忽已黃。","哀碪擣秋色，曉月啼寒螿。","復此櫂孤舟，雲濤浩茫茫。","朱門待媒勢，短褐誰揄揚。","仰羨野陂鳧，無心憂稻粱。","不如天邊雁，南北皆成行。","男兒白日間，變化未可量。","所希困辱地，剪拂成騰驤。","咋筆話肝肺，詠茲枯魚章。","何由首西路，目斷白雲鄉。"]', '["短翮後飞者，前攀鸾鹤翔。","力微應万里，矯首空蒼蒼。","誰昔探花源，考槃西岳陽。","高风动商洛，綺皓無馨香。","一朝下蒲輪，清輝照巖廊。","孤醒立衆醉，古道何由昌。","經術震浮盪，国风掃齊梁。","文襟即玄圃，笔下成琳琅。","霞水散吟嘯，松筠奉琴觴。","冰壺避皎潔，武庫羞鋒鋩。","小子书代耕，束髮頗自強。","艱哉水投石，壯志空摧藏。","十年侶龟鱼，垂头在沅湘。","巴歌揜白雪，鲍肆埋蘭芳。","騷雅道未喪，何憂名不彰。","飢寒束困厄，默塞飞星霜。","百志不成一，东波擲年光。","塵生脫粟甑，万里違高堂。","中夜恨火来，焚燒九回腸。","平明梁山泪，緣枕霑匡牀。","依泊洞庭波，木葉忽已黄。","哀碪擣秋色，晓月啼寒螿。","复此櫂孤舟，云濤浩茫茫。","朱门待媒勢，短褐誰揄揚。","仰羨野陂鳧，無心憂稻粱。","不如天邊雁，南北皆成行。","男兒白日间，变化未可量。","所希困辱地，剪拂成腾驤。","咋笔話肝肺，詠茲枯鱼章。","何由首西路，目斷白云乡。"]', '诗', 'shi', '', NULL, '自澧浦東遊江表途出巴丘投員外從公虞 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6386abab-1d67-4389-b62a-25dafa71756a', '洞庭驛樓雪夜讌集奉贈前湘州張員外', '洞庭驛楼雪夜讌集奉贈前湘州張員外', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["昔與張湘州，閑登岳陽樓。","目窮衡巫表，興盡荆吳秋。","擲筆落郢曲，巴人不能酬。","是時簪裾會，景物窮冥搜。","誤忝玳筵秀，得陪文苑遊。","幾篇雲楣上，風雨沈銀鉤。","□□□□□，□□□滄洲。","童兒待郭伋，竹馬空遲留。","路指雲漢津，誰能吟四愁。","銀壺傲海雪，青管羅名謳。","賤子迹未安，謀身拙如鳩。","分隨煙霞老，豈有風雲求。","不逐萬物化，但貽知己羞。","方窮立命說，戰勝心悠悠。","不然蹲會稽，鉤下三五牛。","所期波濤助，燀赫呈吞舟。"]', '["昔與張湘州，闲登岳陽楼。","目窮衡巫表，兴尽荆吳秋。","擲笔落郢曲，巴人不能酬。","是时簪裾會，景物窮冥搜。","誤忝玳筵秀，得陪文苑游。","幾篇云楣上，风雨沈銀鉤。","□□□□□，□□□滄洲。","童兒待郭伋，竹马空遲留。","路指云漢津，誰能吟四愁。","銀壺傲海雪，青管羅名謳。","賤子迹未安，謀身拙如鳩。","分隨煙霞老，豈有风云求。","不逐万物化，但貽知己羞。","方窮立命说，戰勝心悠悠。","不然蹲會稽，鉤下三五牛。","所期波濤助，燀赫呈吞舟。"]', '诗', 'shi', '', NULL, '洞庭驛樓雪夜讌集奉贈前湘州張員外 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de0ff3d4-e404-4673-8181-d733be57d445', '送鄭子寬棄官東遊便歸女几', '送鄭子寬棄官东游便归女几', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["八月湖浸天，揚帆入秋色。","岷峨雪氣來，寒漲瀟湘碧。","子真冥鴻志，不逐籠下翼。","九女疊雲屏，於焉恣栖息。","新詩山水思，靜入陶謝格。","困醉松花春，追攀紫煙客。","相逢十年舊，嚬笑等歡慽。","一飯玉露蔬，中腸展堆積。","停食不盡意，傾意悵可惜。","雲水一分飛，離憂洞庭側。","迴車三鄉路，仙菊正堪摘。","寄謝杜蘭香，何年別張碩。"]', '["八月湖浸天，揚帆入秋色。","岷峨雪氣来，寒漲瀟湘碧。","子真冥鴻志，不逐籠下翼。","九女叠云屏，於焉恣栖息。","新诗山水思，静入陶謝格。","困醉松花春，追攀紫煙客。","相逢十年旧，嚬笑等歡慽。","一飯玉露蔬，中腸展堆積。","停食不尽意，傾意悵可惜。","云水一分飞，離憂洞庭側。","迴车三乡路，仙菊正堪摘。","寄謝杜蘭香，何年別張碩。"]', '诗', 'shi', '', NULL, '送鄭子寬棄官東遊便歸女几 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db65641-29c3-4dc7-95d5-acc8e587bbf4', '長沙九日登東樓觀舞 一', '长沙九日登东楼观舞 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["南國有佳人，輕盈綠腰舞。","華筵九秋暮，飛袂拂雲雨。","翩如蘭苕翠，婉如游龍舉。","越豔罷前溪，吳姬停白紵。"]', '["南国有佳人，轻盈綠腰舞。","华筵九秋暮，飞袂拂云雨。","翩如蘭苕翠，婉如游龙舉。","越豔罷前溪，吳姬停白紵。"]', '诗', 'shi', '', NULL, '長沙九日登東樓觀舞 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8585ac55-69dd-47ef-92b8-006e47054cc2', '長沙九日登東樓觀舞 二', '长沙九日登东楼观舞 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["慢態不能窮，繁姿曲向終。","低回蓮破浪，凌亂雪縈風。","墜珥時流盻，修裾欲遡空。","唯愁捉不住，飛去逐驚鴻。"]', '["慢態不能窮，繁姿曲向終。","低回蓮破浪，凌亂雪縈风。","墜珥时流盻，修裾欲遡空。","唯愁捉不住，飞去逐驚鴻。"]', '诗', 'shi', '', NULL, '長沙九日登東樓觀舞 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c8d423-0fc2-41b9-a961-1432f4157104', '龍山人惠石廩方及團茶', '龙山人惠石廩方及團茶', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["客有衡岳隱，遺余石廩茶。","自云凌煙露，采掇春山芽。","珪璧相壓疊，積芳莫能加。","碾成黃金粉，輕嫩如松花。","紅鑪爨霜枝，越兒斟井華。","灘聲起魚眼，滿鼎漂清霞。","凝澄坐曉燈，病眼如蒙紗。","一甌拂昏寐，襟鬲開煩拏。","顧渚與方山，誰人留品差。","持甌默吟味，搖膝空咨嗟。"]', '["客有衡岳隐，遺余石廩茶。","自云凌煙露，采掇春山芽。","珪璧相壓叠，積芳莫能加。","碾成黄金粉，轻嫩如松花。","紅鑪爨霜枝，越兒斟井华。","灘声起鱼眼，满鼎漂清霞。","凝澄坐晓灯，病眼如蒙紗。","一甌拂昏寐，襟鬲开煩拏。","顧渚與方山，誰人留品差。","持甌默吟味，搖膝空咨嗟。"]', '诗', 'shi', '', NULL, '龍山人惠石廩方及團茶 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281ee8e7-0bf6-422b-912c-3d7873e88f2c', '宿鳥遠峽化臺遇風雨', '宿鸟远峽化台遇风雨', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["孤鶴長松顛，獨宿萬巖雨。","龍湫在石腳，引袂時一取。","驚風折喬木，飛焰獵窗戶。","半夜霹靂聲，高齋有人語。"]', '["孤鹤长松顛，独宿万巖雨。","龙湫在石腳，引袂时一取。","驚风折喬木，飞焰獵窗戶。","半夜霹靂声，高斋有人語。"]', '诗', 'shi', '', NULL, '宿鳥遠峽化臺遇風雨 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed147ba-1ea7-4d41-b880-302f1eff3d74', '岳陽春晚', '岳陽春晚', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["不覺春物老，塊然湖上樓。","雲沙鷓鴣思，風日沅湘愁。","去翼滅雲夢，來帆指昭丘。","所嗟芳桂晚，寂寞對汀洲。"]', '["不覺春物老，塊然湖上楼。","云沙鷓鴣思，风日沅湘愁。","去翼滅云梦，来帆指昭丘。","所嗟芳桂晚，寂寞对汀洲。"]', '诗', 'shi', '', NULL, '岳陽春晚 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3649552-59e3-4167-b78d-8f013b5c77b6', '漢陽春晚', '漢陽春晚', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["漢陽抱青山，飛樓暎湘渚。","白雲蔽黃鶴，綠樹藏鸚鵡。","憑高送春目，流恨傷千古。","遐思禰衡才，令人怨黃祖。"]', '["漢陽抱青山，飞楼暎湘渚。","白云蔽黄鹤，綠樹藏鸚鵡。","憑高送春目，流恨傷千古。","遐思禰衡才，令人怨黄祖。"]', '诗', 'shi', '', NULL, '漢陽春晚 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d87da7e0-93c4-4587-9464-85ee87f3afc7', '將離澧浦置酒野嶼奉懷沈正字昆弟三人聯登高第', '將離澧浦置酒野嶼奉懷沈正字昆弟三人聯登高第', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["春月三改兔，花枝成綠陰。","年光東流水，浩歎傷羈心。","酌桂煙嶼晚，鴂鳴江草深。","良圖一超忽，萬恨空相尋。","上國刈翹楚，才微甘陸沈。","無燈假貧女，有淚沾牛衾。","衡岳三麒麟，各振黃鍾音。","卿雲被文彩，芳價搖詞林。","夫子芸閣英，養鱗湘水潯。","晴沙踏蘭菊，隱几當青岑。","明月洞庭上，悠揚挂離襟。","停觴一搖筆，聊寄生芻吟。"]', '["春月三改兔，花枝成綠陰。","年光东流水，浩歎傷羈心。","酌桂煙嶼晚，鴂鳴江草深。","良圖一超忽，万恨空相尋。","上国刈翹楚，才微甘陸沈。","無灯假貧女，有泪沾牛衾。","衡岳三麒麟，各振黄鍾音。","卿云被文彩，芳價搖词林。","夫子芸閣英，養鱗湘水潯。","晴沙踏蘭菊，隐几當青岑。","明月洞庭上，悠揚挂離襟。","停觴一搖笔，聊寄生芻吟。"]', '诗', 'shi', '', NULL, '將離澧浦置酒野嶼奉懷沈正字昆弟三人聯登高第 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd9d980-5bab-4bee-b543-9983e5020b87', '湘中別成威闍黎', '湘中別成威闍黎', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["至哉彼上人，冰霜凜規則。","遊心杳何境，宴坐入冥默。","解空與密行，名臘信崇德。","吐論駕秋濤，龍宮發胸臆。","羣迷行大夜，浩浩一昏黑。","赤水千丈深，玄珠幾人得。","持桮挹溟漲，至理安可測。","寧假喻芭蕉，真成嗅薝蔔。","松聲掃白月，霽夜來靜域。","清梵罷法筵，天香滿衣襋。","何方濟了岸，秪仗慈航力。","願與十八賢，同棲翠蓮國。"]', '["至哉彼上人，冰霜凜規則。","游心杳何境，宴坐入冥默。","解空與密行，名臘信崇德。","吐論駕秋濤，龙宮發胸臆。","羣迷行大夜，浩浩一昏黑。","赤水千丈深，玄珠幾人得。","持桮挹溟漲，至理安可測。","寧假喻芭蕉，真成嗅薝蔔。","松声掃白月，霽夜来静域。","清梵罷法筵，天香满衣襋。","何方濟了岸，秪仗慈航力。","願與十八賢，同棲翠蓮国。"]', '诗', 'shi', '', NULL, '湘中別成威闍黎 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8721c066-db42-44da-be87-a1a76680992b', '別尹鍊師', '別尹鍊師', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["吾家五千言，至道懸日月。","若非函谷令，誰注流沙說。","多君飛昇志，機悟獨超拔。","學道玉笥山，燒丹白雲穴。","南窮衡疑秀，采藥歷幽絕。","夜臥瀑布風，朝行碧巖雪。","洞宮四百日，玉籍恣探閱。","徒以菌蟪姿，緬攀修真訣。","塵籠罩浮世，遐思空飛越。","一罷棋酒歡，離情滿寥泬。","願騎紫蓋鶴，早向黃金闕。","城市不可留，塵埃穢仙骨。"]', '["吾家五千言，至道懸日月。","若非函谷令，誰注流沙说。","多君飞昇志，機悟独超拔。","学道玉笥山，燒丹白云穴。","南窮衡疑秀，采藥歷幽絕。","夜臥瀑布风，朝行碧巖雪。","洞宮四百日，玉籍恣探閱。","徒以菌蟪姿，緬攀修真訣。","塵籠罩浮世，遐思空飞越。","一罷棋酒歡，離情满寥泬。","願騎紫蓋鹤，早向黄金闕。","城市不可留，塵埃穢仙骨。"]', '诗', 'shi', '', NULL, '別尹鍊師 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac31558-9e7a-46cc-a268-d9fd3c3802e3', '飯僧', '飯僧', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["好讀天竺書，爲尋無生理。","焚香面金偈，一室唯巾水。","交信方外言，二三空門子。","峻範照秋霜，高標揜僧史。","清晨潔蔬茗，延請良有以。","一落喧譁競，栖心願依止。","奔曦入半百，冉冉頹濛汜。","雲汎名利心，風輕是非齒。","向爲情愛縛，未盡金仙旨。","以靜制猨心，將虞瞥然起。","綸巾與藜杖，此意真已矣。","他日雲壑間，來尋幽居士。"]', '["好读天竺书，爲尋無生理。","焚香面金偈，一室唯巾水。","交信方外言，二三空门子。","峻範照秋霜，高標揜僧史。","清晨潔蔬茗，延請良有以。","一落喧譁競，栖心願依止。","奔曦入半百，冉冉頹濛汜。","云汎名利心，风轻是非齒。","向爲情愛縛，未尽金仙旨。","以静制猨心，將虞瞥然起。","綸巾與藜杖，此意真已矣。","他日云壑间，来尋幽居士。"]', '诗', 'shi', '', NULL, '飯僧 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612449a3-c1fa-478b-bfa5-6daf76dac4bc', '贈回雪', '贈回雪', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["回雪舞縈盈，縈盈若回雪。","腰支一把玉，秪恐風吹折。","如能買一笑，滿斗量明月。","安得金蓮花，步步承羅襪。"]', '["回雪舞縈盈，縈盈若回雪。","腰支一把玉，秪恐风吹折。","如能買一笑，满斗量明月。","安得金蓮花，步步承羅襪。"]', '诗', 'shi', '', NULL, '贈回雪 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a23b4c7c-255d-4a62-b221-4b62b42fcbcb', '將之京國贈薛員外', '將之京国贈薛員外', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["黃葉下空館，寂寥寒雨愁。","平居歲華晏，絡緯啼林幽。","節物凋壯志，咄嗟不能休。","空懷趙鞅歎，變化良無由。","所思杳何如，側身仰皇州。","蒼煙晦楚野，寒浪埋昭丘。","趙壹賦命薄，陳思多世憂。","翻然羨魚鳥，暢矣山川遊。","薛公龍泉姿，其氣在斗牛。","南冠束秀髮，白石勞悲謳。","圭衮照崇閱，文儒嗣箕裘。","曠然方寸地，霽海浮雲舟。","澧浦一遺佩，郢南再悲秋。","叫閽路既阻，浩蕩懷靈修。","莫奏武溪笛，且登仲宣樓。","亨通與否閉，物理相沈浮。","天子坐宣室，夔龍奉謨猷。","行當賜環去，豈作遺賢羞。"]', '["黄葉下空館，寂寥寒雨愁。","平居歲华晏，絡緯啼林幽。","節物凋壯志，咄嗟不能休。","空懷趙鞅歎，变化良無由。","所思杳何如，側身仰皇州。","蒼煙晦楚野，寒浪埋昭丘。","趙壹賦命薄，陳思多世憂。","翻然羨鱼鸟，暢矣山川游。","薛公龙泉姿，其氣在斗牛。","南冠束秀髮，白石勞悲謳。","圭衮照崇閱，文儒嗣箕裘。","曠然方寸地，霽海浮云舟。","澧浦一遺佩，郢南再悲秋。","叫閽路既阻，浩蕩懷靈修。","莫奏武溪笛，且登仲宣楼。","亨通與否閉，物理相沈浮。","天子坐宣室，夔龙奉謨猷。","行當賜环去，豈作遺賢羞。"]', '诗', 'shi', '', NULL, '將之京國贈薛員外 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d31a8b-5a38-4bb4-89b4-92705c1123d2', '送魏珪覲省', '送魏珪覲省', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["木落楚色深，風高浪花白。","送君飛一葉，鳥逝入空碧。","猗歟白華秀，傷心倚門夕。","不知雲漲遙，萬里看咫尺。","蕭蕭青楓岸，去掩江山宅。","離觴有黃花，節物助淒戚。","瀟湘入𤃩桂，一路縈水石。","煙蘿拂行舟，玉瀨鏘枕席。","多君林泉趣，耽翫日成癖。","長嘯凌清暉，襟情當雪滌。","登龍屈指內，飛譽甚籍籍。","未折月中枝，寧隨宋都鶂。","曰余吞聲地，舉足傷瓦礫。","見爾一開顏，溫明乃珠璧。","春風到雲嶠，把酒時相憶。","荳蔻花入船，鷓鴣啼送客。","颺天與瘴海，此去備沿歷。","珍重春官英，加餐數刀帛。"]', '["木落楚色深，风高浪花白。","送君飞一葉，鸟逝入空碧。","猗歟白华秀，傷心倚门夕。","不知云漲遙，万里看咫尺。","蕭蕭青楓岸，去掩江山宅。","離觴有黄花，節物助淒戚。","瀟湘入𤃩桂，一路縈水石。","煙蘿拂行舟，玉瀨鏘枕席。","多君林泉趣，耽翫日成癖。","长嘯凌清暉，襟情當雪滌。","登龙屈指內，飞譽甚籍籍。","未折月中枝，寧隨宋都鶂。","曰余吞声地，舉足傷瓦礫。","见爾一开顏，溫明乃珠璧。","春风到云嶠，把酒时相憶。","荳蔻花入船，鷓鴣啼送客。","颺天與瘴海，此去備沿歷。","珍重春官英，加餐數刀帛。"]', '诗', 'shi', '', NULL, '送魏珪覲省 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ccb5c9c-756b-4463-b39e-c53622326f39', '始忝四座奏狀聞薦蒙恩授官旋進歌詩延英宣賜言懷紀事呈同館諸公二十四韻', '始忝四座奏狀闻薦蒙恩授官旋進歌诗延英宣賜言懷紀事呈同館諸公二十四韻', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["兩鬢有二毛，光陰流浪中。","形骸日土木，志氣隨雲風。","冥默楚江畔，蕭條林巷空。","幽鳥事翔翥，斂翼依蒿蓬。","一飯五放箸，愀然念途窮。","孟門在步武，所向何由通。","秖徵大易言，物否不可終。","庶期白雪調，一奏驚凡聾。","昨忝丞相召，揚鞭指冥鴻。","姓名挂丹詔，文句飛天聰。","解薜龍鳳署，懷鉛蘭桂叢。","聲名仰聞見，煙漢陪高蹤。","峨峨羣玉山，肅肅紫殿東。","神飆泛鐘漏，佳氣浮筠松。","自顧珉玞璞，何緣侶圭琮。","羣賢垂重價，省已增磨礱。","天子棲穆清，三台付夔龍。","九霄降雨露，萬國望時雍。","巍巍致君期，勛華將比崇。","承天四柱石，嶷若窺衡嵩。","日見帝道昇，謀猷垂景鍾。","寰瀛納壽域，翔泳皆沖融。","百神儼云亭，佇將告成功。","吾徒事文藻，驤首歌登封。"]', '["兩鬢有二毛，光陰流浪中。","形骸日土木，志氣隨云风。","冥默楚江畔，蕭條林巷空。","幽鸟事翔翥，斂翼依蒿蓬。","一飯五放箸，愀然念途窮。","孟门在步武，所向何由通。","秖徵大易言，物否不可終。","庶期白雪調，一奏驚凡聾。","昨忝丞相召，揚鞭指冥鴻。","姓名挂丹詔，文句飞天聰。","解薜龙鳳署，懷鉛蘭桂叢。","声名仰闻见，煙漢陪高蹤。","峨峨羣玉山，肅肅紫殿东。","神飆泛鐘漏，佳氣浮筠松。","自顧珉玞璞，何緣侶圭琮。","羣賢垂重價，省已增磨礱。","天子棲穆清，三台付夔龙。","九霄降雨露，万国望时雍。","巍巍致君期，勛华將比崇。","承天四柱石，嶷若窺衡嵩。","日见帝道昇，謀猷垂景鍾。","寰瀛納壽域，翔泳皆沖融。","百神儼云亭，佇將告成功。","吾徒事文藻，驤首歌登封。"]', '诗', 'shi', '', NULL, '始忝四座奏狀聞薦蒙恩授官旋進歌詩延英宣賜言懷紀事呈同館諸公二十四韻 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a30d65-cd5e-40e7-b923-be3c706ad898', '穆天子', '穆天子', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["穆滿恣逸志，而輕天下君。","一朝得八駿，逐日西溟濆。","寂漠崦嵫幽，絕迹留空文。","三千閟宮豔，怨絕寧勝云。","或言帝軒轅，乘龍凌紫氛。","橋山葬弓劒，曖昧竟難分。","不思五弦琴，作歌詠南薰。","但聽西王母，瑤池吟白雲。"]', '["穆满恣逸志，而轻天下君。","一朝得八駿，逐日西溟濆。","寂漠崦嵫幽，絕迹留空文。","三千閟宮豔，怨絕寧勝云。","或言帝軒轅，乘龙凌紫氛。","橋山葬弓劒，曖昧竟难分。","不思五弦琴，作歌詠南薰。","但听西王母，瑤池吟白云。"]', '诗', 'shi', '', NULL, '穆天子 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6deaec83-a8cc-4d61-88de-31ae247c8cfc', '廣州重別方處士之封川 一', '廣州重別方处士之封川 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["楚國傲名客，九州徧芳聲。","白衣謝簪紱，雲臥重巖扃。","長波飛素舸，五月下南溟。","大笑相逢日，天邊作酒星。"]', '["楚国傲名客，九州徧芳声。","白衣謝簪紱，云臥重巖扃。","长波飞素舸，五月下南溟。","大笑相逢日，天邊作酒星。"]', '诗', 'shi', '', NULL, '廣州重別方處士之封川 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e6a74f-2234-4671-b8be-0fb8e8b589ce', '廣州重別方處士之封川 二', '廣州重別方处士之封川 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["七年一雲雨，常恨輝容隔。","天末又分襟，離憂鬢堪白。","顧回凌潮檝，且著登山屐。","共期羅浮秋，與子醉海色。"]', '["七年一云雨，常恨輝容隔。","天末又分襟，離憂鬢堪白。","顧回凌潮檝，且著登山屐。","共期羅浮秋，與子醉海色。"]', '诗', 'shi', '', NULL, '廣州重別方處士之封川 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bedb7651-87b4-4c81-8786-bf88bca46b92', '洞庭遇秋', '洞庭遇秋', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["塵愁老來顏，久與江山隔。","逍遙澄湖上，洗眼見秋色。","涼波弄輕櫂，湖月生遠碧。","未減遙客情，西望杳何極。"]', '["塵愁老来顏，久與江山隔。","逍遙澄湖上，洗眼见秋色。","涼波弄轻櫂，湖月生远碧。","未減遙客情，西望杳何極。"]', '诗', 'shi', '', NULL, '洞庭遇秋 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb1deb3-6c95-4534-8fd5-90edc67cdd7e', '寄短書歌', '寄短书歌', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["骨肉萍蓬各天末，十度附書九不達。","孤臺冷眼無來人，楚水秦天莽空闊。","翔雁橫秋過洞庭，西風落日浪崢嶸。","三年音信凝顰外，一曲哀歌白髮生。"]', '["骨肉萍蓬各天末，十度附书九不達。","孤台冷眼無来人，楚水秦天莽空闊。","翔雁橫秋過洞庭，西风落日浪崢嶸。","三年音信凝顰外，一曲哀歌白髮生。"]', '诗', 'shi', '', NULL, '寄短書歌 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a8c48b-ca6b-416a-b0da-664309a8e4da', '王內人琵琶引', '王內人琵琶引', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["檀槽一曲黃鍾羽，細撥紫雲金鳳語。","萬里胡天海塞秋，分明彈出風沙愁。","三千宮嬪推第一，斂黛傾鬟豔蘭室。","嬴女停吹降浦簫，嫦娥淨揜空波瑟。","翠幕橫雲蠟燄光，銀龍吐酒菊花香。","皓魄翻。"]', '["檀槽一曲黄鍾羽，細撥紫云金鳳語。","万里胡天海塞秋，分明彈出风沙愁。","三千宮嬪推第一，斂黛傾鬟豔蘭室。","嬴女停吹降浦簫，嫦娥淨揜空波瑟。","翠幕橫云蠟燄光，銀龙吐酒菊花香。","皓魄翻。"]', '诗', 'shi', '', NULL, '王內人琵琶引 李羣玉 shi');
